insert into public.species (id, line_id, stage, name, category, flavor, height, weight, btype, hp, atk, def, spa, spd, spe, dex, evo_lv, evo_item) values
 (1, 1, 1, '캐이시', '초능력포켓몬', '자는 동안에도 다양한 초능력을 사용하기 때문에 깨어 있는 것이 아닌지 헷갈린다.', '0.9m', '19.5kg', '에스퍼', 25, 20, 15, 105, 55, 90, 63, null, false),
 (2, 1, 2, '윤겔라', '초능력포켓몬', '은 숟가락을 가만히 주시하고 사이코 파워를 증폭하여 발산한다. 금 숟가락으로는 안 되는 듯하다.', '1.3m', '56.5kg', '에스퍼', 40, 35, 30, 120, 70, 105, 64, 16, false),
 (3, 1, 3, '후딘', '초능력포켓몬', '지니고 있는 숟가락은 후딘이 초능력으로 만들어 낸 것이다. 이 세상에 1개뿐인 오리지널이다.', '1.5m', '48kg', '에스퍼', 55, 50, 45, 135, 95, 120, 65, 40, false),
 (4, 2, 1, '랄토스', '느낌포켓몬', '머리의 뿔로 사람의 기분을 감지한다. 사람 앞에는 좀처럼 모습을 나타내지 않지만 긍정적인 기분을 캐치하면 다가온다.', '0.4m', '6.6kg', '에스퍼/페어리', 28, 25, 25, 45, 35, 40, 280, null, false),
 (5, 2, 2, '킬리아', '감정포켓몬', '트레이너의 긍정적인 감정에 닿은 킬리아는 아름답게 성장한다고 한다. 발달한 뇌로 사이코 파워를 다룬다.', '0.8m', '20.2kg', '에스퍼/페어리', 38, 35, 35, 65, 55, 50, 281, 20, false),
 (6, 2, 3, '가디안', '포용포켓몬', '미래를 예지하는 능력으로 트레이너의 위험을 감지했을 때 최대 파워의 사이코 에너지를 사용한다고 전해진다.', '1.6m', '48.4kg', '에스퍼/페어리', 68, 65, 65, 125, 115, 80, 282, 30, false),
 (7, 3, 1, '구구', '아기새포켓몬', '방향 감각이 매우 뛰어나서 아무리 멀리 떨어진 곳에서도 헤매지 않고 자신의 둥지까지 찾아 돌아올 수 있다.', '0.3m', '1.8kg', '노말/비행', 40, 45, 40, 35, 35, 56, 16, null, false),
 (8, 3, 2, '피죤', '새포켓몬', '넓은 영역을 날며 순찰한다. 영역을 침범하는 상대는 용서하지 않는다. 날카로운 발톱으로 철저히 혼내준다.', '1.1m', '30kg', '노말/비행', 63, 60, 55, 50, 50, 71, 17, 18, false),
 (9, 3, 3, '피죤투', '새포켓몬', '아름답게 윤이 나는 깃털을 가진 포켓몬이다. 머리 깃털의 아름다움에 마음을 빼앗겨 피죤투를 기르는 트레이너도 많다.', '1.5m', '39.5kg', '노말/비행', 83, 80, 75, 70, 70, 101, 18, 36, false),
 (10, 4, 1, '고오스', '가스포켓몬', '무덤에서 발생한 가스에 원념이 머물러 이윽고 포켓몬이 되었다고 전해진다.', '1.3m', '0.1kg', '고스트/독', 30, 35, 30, 100, 35, 80, 92, null, false),
 (11, 4, 2, '고우스트', '가스포켓몬', '달이 뜨지 않은 밤. 고우스트는 저주할 상대를 찾기 때문에 나다니지 않는 것이 좋다.', '1.6m', '0.1kg', '고스트/독', 45, 50, 45, 115, 55, 95, 93, 25, false),
 (12, 4, 3, '팬텀', '그림자포켓몬', '못된 아이가 있는 곳에 팬텀이 찾아온다고 하는 이야기는 전 세계에서 들을 수 있다.', '1.5m', '40.5kg', '고스트/독', 60, 65, 60, 130, 75, 110, 94, 40, false),
 (13, 5, 1, '코일', '자석포켓몬', '종종 정전의 원인이 되기 때문에 코일이 싫어하는 전파를 내보내는 발전소도 있을 정도다.', '0.3m', '6kg', '전기/강철', 25, 35, 70, 95, 55, 45, 81, null, false),
 (14, 5, 2, '레어코일', '자석포켓몬', '정체 모를 전파를 발신하기 때문에 레어코일이 사는 곳에는 정밀 기기가 고장 난다.', '1m', '60kg', '전기/강철', 50, 60, 95, 120, 70, 70, 82, 30, false),
 (15, 5, 3, '자포코일', '자기장포켓몬', '자신의 영토를 레이더로 감시하고 있다. 침입자는 파괴광선으로 즉시 처분한다.', '1.2m', '180kg', '전기/강철', 70, 70, 115, 130, 90, 60, 462, null, true),
 (16, 6, 1, '메탕', '철공포켓몬', '체내에는 혈액을 대신하여 자력이 돌고 있다. 몸 상태가 좋지 않을 때는 자석을 주자.', '0.6m', '95.2kg', '강철/에스퍼', 40, 55, 80, 35, 60, 30, 374, null, false),
 (17, 6, 2, '메탕구', '철발톱포켓몬', '2개의 뇌에서 강력한 사이코 에너지를 방사하여 먹이를 움직이지 못하게 한다.', '1.2m', '202.5kg', '강철/에스퍼', 60, 75, 100, 55, 80, 50, 375, 20, false),
 (18, 6, 3, '메타그로스', '무쇠다리포켓몬', '사이코 파워뿐만 아니라 괴력도 겸비하고 있다. 4개의 다리로 먹이를 붙잡고 발톱으로 움직이지 못하게 한다.', '1.6m', '550kg', '강철/에스퍼', 80, 135, 130, 95, 90, 70, 376, 45, false),
 (19, 7, 1, '가보리', '철갑옷포켓몬', '강철 몸을 만들기 위해 철광석을 산에서 채광해 먹지만 가끔 다리나 레일을 먹어버리는 말썽꾸러기다.', '0.4m', '60kg', '강철/바위', 50, 70, 100, 40, 40, 30, 304, null, false),
 (20, 7, 2, '갱도라', '철갑옷포켓몬', '영양 만점인 샘물을 배 속 가득 마셔서 강철 몸을 단련시킨다. 맛있는 샘물 가까이에 거처를 만든다.', '0.9m', '120kg', '강철/바위', 60, 90, 140, 50, 50, 40, 305, 32, false),
 (21, 7, 3, '보스로라', '철갑옷포켓몬', '산 하나를 자신의 영역으로 만들고 침범한 상대는 봐주지 않고 때려눕힌다. 항상 산속을 돌아보고 있다.', '2.1m', '360kg', '강철/바위', 70, 110, 180, 60, 60, 50, 306, 42, false),
 (22, 8, 1, '기어르', '톱니바퀴포켓몬', '두 개의 몸을 맞물려 회전시켜서 살아가기 위한 에너지를 만들고 있다.', '0.3m', '21kg', '강철', 40, 55, 70, 45, 60, 30, 599, null, false),
 (23, 8, 2, '기기어르', '톱니바퀴포켓몬', '회전 방향을 바꿔서 동료에게 감정을 전한다. 화가 나면 회전이 빨라진다.', '0.6m', '51kg', '강철', 60, 80, 95, 70, 85, 50, 600, 38, false),
 (24, 8, 3, '기기기어르', '톱니바퀴포켓몬', '빨간 코어가 달린 기어를 고속 회전시켜서 에너지를 급속 충전한다.', '0.6m', '81kg', '강철', 60, 100, 115, 70, 85, 90, 601, 49, false),
 (25, 9, 1, '깨비참', '아기새포켓몬', '자신의 영역을 지키기 위해서라면 상대가 큰 포켓몬이라도 덤벼드는 무모한 성질을 가졌다.', '0.3m', '2kg', '노말/비행', 40, 60, 30, 31, 31, 70, 21, null, false),
 (26, 9, 2, '깨비드릴조', '부리포켓몬', '깨비드릴조 영역에서 음식을 갖고 다니는 것은 위험하다. 순식간에 빼앗긴다.', '1.2m', '38kg', '노말/비행', 65, 90, 65, 61, 61, 100, 22, 20, false),
 (28, 10, 1, '주뱃', '박쥐포켓몬', '눈이 없어서 보지 못한다. 입으로 초음파를 발산하여 주변의 상황을 파악한다.', '0.8m', '7.5kg', '독/비행', 40, 45, 35, 30, 40, 55, 41, null, false),
 (29, 10, 2, '골뱃', '박쥐포켓몬', '배가 고픈 나머지 강철포켓몬을 물어 버리는 바람에 이빨이 빠진 골뱃을 가끔 볼 수 있다.', '1.6m', '55kg', '독/비행', 75, 80, 70, 65, 75, 90, 42, 22, false),
 (30, 10, 3, '크로뱃', '박쥐포켓몬', '이빨이 예리해서 어둠 속에서 물려 피를 빨려도 통증이 없기 때문에 금세 알아차리지 못한다.', '1.8m', '75kg', '독/비행', 85, 90, 80, 70, 80, 130, 169, 40, false),
 (31, 11, 1, '부우부', '부엉이포켓몬', '매일 정해진 리듬에 맞춰 목을 기울인다. 옛날 사람들은 시계 대용으로 길렀다.', '0.7m', '21.2kg', '노말/비행', 60, 30, 30, 36, 56, 50, 163, null, false),
 (32, 11, 2, '야부엉', '부엉이포켓몬', '어둠 속에서도 뚜렷이 볼 수 있는 눈을 갖고 있어 먹이를 놓치지 않는다. 어둠의 제왕이라고도 불린다.', '1.6m', '40.8kg', '노말/비행', 100, 50, 50, 86, 96, 70, 164, 20, false),
 (34, 12, 1, '피츄', '아기쥐포켓몬', '여전히 전기 사용에 서툴다. 놀라거나 흥분하게 되면 바로 방전돼 버린다.', '0.3m', '2kg', '전기', 20, 40, 15, 35, 35, 60, 172, null, false),
 (35, 12, 2, '피카츄', '쥐포켓몬', '전기를 모으는 성질을 띠고 있다. 피카츄가 무리 지어 사는 숲은 낙뢰가 끊이지 않아 위험하다.', '0.4m', '6kg', '전기', 35, 55, 40, 50, 50, 90, 25, 25, false),
 (36, 12, 3, '라이츄', '쥐포켓몬', '몸에 전기가 쌓일수록 공격적으로 변한다. 사실은 전기가 스트레스라는 설도 있다.', '0.8m', '30kg', '전기', 60, 90, 55, 90, 80, 110, 26, null, true),
 (37, 13, 1, '니드런♀', '독침포켓몬', '작은 몸을 지키기 위해 강력한 독침이 발달한 것이라 여겨진다. 화가 나면 뿔 끝에서 맹독을 뿜는다.', '0.4m', '7kg', '독', 55, 47, 52, 40, 40, 41, 29, null, false),
 (38, 13, 2, '니드리나', '독침포켓몬', '동료나 가족과 함께일 때는 서로 상처 입히지 않도록 가시를 세우지 않는다. 동료와 떨어지면 불안해하는 것 같다.', '0.8m', '20kg', '독', 70, 62, 67, 55, 55, 56, 30, 16, false),
 (39, 13, 3, '니드퀸', '드릴포켓몬', '단단한 비늘로 뒤덮인 몸을 부딪쳐서 상대를 튕겨내는 공격이 특기다. 자식을 지킬 때 가장 강하다.', '1.3m', '60kg', '독/땅', 90, 92, 87, 75, 85, 76, 31, null, true),
 (40, 14, 1, '캐터피', '애벌레포켓몬', '빨리 성장하고 싶어서인지 식욕이 왕성하여 하루에 100장의 잎사귀를 먹는다.', '0.3m', '2.9kg', '벌레', 45, 30, 35, 20, 20, 45, 10, null, false),
 (41, 14, 2, '단데기', '번데기포켓몬', '껍질 안은 걸쭉한 액체다. 진화를 대비하여 몸 전체의 세포를 재구성하고 있다.', '0.7m', '9.9kg', '벌레', 50, 20, 55, 25, 25, 30, 11, 7, false),
 (42, 14, 3, '버터플', '나비포켓몬', '날개를 감싼 인분은 맹독이다. 캐터피를 노리는 새포켓몬을 발견하면 흩뿌려 내쫓는다.', '1.1m', '32kg', '벌레/비행', 60, 45, 50, 90, 80, 70, 12, 10, false),
 (43, 15, 1, '꼬마돌', '암석포켓몬', '오래 산 꼬마돌은 모가 없이 동그랗다. 성격도 매우 차분하고 온화하다.', '0.4m', '20kg', '바위/땅', 40, 80, 100, 30, 30, 20, 74, null, false),
 (44, 15, 2, '데구리', '암석포켓몬', '정상을 목표로 절벽을 오른다. 정상에 도착하면 곧바로 올라온 산길을 굴러 내려간다.', '1m', '105kg', '바위/땅', 55, 95, 115, 45, 45, 35, 75, 25, false),
 (45, 15, 3, '딱구리', '메가톤포켓몬', '나이가 들면 탈피를 하지 않는다. 긴 세월을 산 딱구리의 껍질은 이끼가 끼어 초록색이다.', '1.4m', '300kg', '바위/땅', 80, 120, 130, 55, 65, 45, 76, 40, false),
 (46, 16, 1, '토게피', '바늘알포켓몬', '사람이나 포켓몬이 발산하는 상냥함이나 즐거운 마음을 에너지로 삼는다. 껍질 안에 모은 행복을 나눈다.', '0.3m', '1.5kg', '페어리', 35, 20, 65, 40, 65, 20, 175, null, false),
 (47, 16, 2, '토게틱', '행복포켓몬', '행운을 가져다주는 포켓몬이라고 전해진다. 순수한 마음을 지닌 자를 발견하면 모습을 드러내고 행복을 나누어준다.', '0.6m', '3.2kg', '페어리/비행', 55, 40, 85, 80, 105, 40, 176, 25, false),
 (48, 16, 3, '토게키스', '축복포켓몬', '다툼이 없는 평화로운 땅에 토게키스가 나타나 여러 가지 은총을 나눠줬다고 전해진다.', '1.5m', '38kg', '페어리/비행', 85, 50, 95, 120, 115, 80, 468, null, true),
 (49, 17, 1, '깜눈크', '사막악어포켓몬', '일 년 내내 따듯한 알로라는 지내기 좋은 환경이다. 사막이 아닌 곳에서도 가끔 볼 수 있다.', '0.7m', '15.2kg', '땅/악', 50, 72, 35, 35, 35, 65, 551, null, false),
 (50, 17, 2, '악비르', '사막악어포켓몬', '몸이 차가워지는 것을 매우 싫어한다. 기온이 내려가는 밤에는 사막 모래 속으로 깊숙이 파고든다.', '1m', '33.4kg', '땅/악', 60, 82, 45, 45, 45, 74, 552, 29, false),
 (51, 17, 3, '악비아르', '위협포켓몬', '50km 떨어져 있는 먹이를 발견하면 사막을 헤엄치듯이 이동하여 덤벼들어 덥석 문다.', '1.5m', '96.3kg', '땅/악', 95, 117, 80, 65, 70, 92, 553, 40, false),
 (52, 18, 1, '발챙이', '올챙이포켓몬', '위험한데도 지상으로 올라가고 싶어한다. 아직 아장아장 걷기 때문에 적에게 노출되면 황급히 물속으로 들어간다.', '0.6m', '12.4kg', '물', 40, 50, 40, 40, 40, 90, 60, null, false),
 (53, 18, 2, '슈륙챙이', '올챙이포켓몬', '지상에서 살 수 있게 되었는데도 먹이인 물고기포켓몬이 많은 수중에서 지낸다.', '1m', '20kg', '물', 65, 65, 65, 50, 50, 90, 61, 25, false),
 (54, 18, 3, '강챙이', '올챙이포켓몬', '물포켓몬 중에서도 수영 실력이 매우 뛰어난 부류인데도 평상시에는 지상에서 지낸다.', '1.3m', '54kg', '물/격투', 90, 95, 95, 70, 90, 70, 62, null, true),
 (55, 19, 1, '델빌', '다크포켓몬', '동료와의 연계가 특기다. 파트너가되면 트레이너의 명령에 매우 충실하다.', '0.6m', '10.8kg', '악/불꽃', 45, 60, 30, 80, 50, 65, 228, null, false),
 (56, 19, 2, '헬가', '다크포켓몬', '독소가 섞인 불꽃을 불어 상대를 처리한다. 먹이는 무리가 공평에게 나눈다.', '1.4m', '35kg', '악/불꽃', 75, 90, 50, 110, 80, 95, 229, 24, false),
 (58, 20, 1, '이상해씨', '씨앗포켓몬', '양지에서 낮잠 자는 모습을 볼 수 있다. 태양의 빛을 많이 받으면 등의 씨앗이 크게 자란다.', '0.7m', '6.9kg', '풀/독', 45, 49, 49, 65, 65, 45, 1, null, false),
 (59, 20, 2, '이상해풀', '씨앗포켓몬', '꽃봉오리를 지탱하기 위해 하반신이 강해진다. 양지에서 가만히 있는 시간이 길어지면 드디어 커다란 꽃이 필 때다.', '1m', '13kg', '풀/독', 60, 62, 63, 80, 80, 60, 2, 16, false),
 (60, 20, 3, '이상해꽃', '씨앗포켓몬', '충분한 영양분과 태양의 빛이 꽃의 색을 선명하게 만든다고 한다. 꽃의 향기는 사람의 마음을 치유한다.', '2m', '100kg', '풀/독', 80, 82, 83, 100, 100, 80, 3, 32, false),
 (61, 21, 1, '파이리', '도롱뇽포켓몬', '꼬리의 불꽃은 기분을 표현한다. 즐거울 때는 흔들흔들 불꽃이 흔들리고 화가 났을 때는 활활 맹렬히 불타오른다.', '0.6m', '8.5kg', '불꽃', 39, 52, 43, 60, 50, 65, 4, null, false),
 (62, 21, 2, '리자드', '화염포켓몬', '날카로운 발톱으로 봐주지 않고 때려눕힌다. 강한 적을 만나면 기분이 고양되며 꼬리의 불꽃이 푸르스름하게 불타오른다.', '1.1m', '19kg', '불꽃', 58, 64, 58, 80, 65, 80, 5, 16, false),
 (63, 21, 3, '리자몽', '화염포켓몬', '강한 상대를 찾아 하늘을 날아다닌다. 무엇이든 다 녹여버리는 고열의 불꽃을 자신보다 약한 자에게 들이대지 않는다.', '1.7m', '90.5kg', '불꽃/비행', 78, 84, 78, 109, 85, 100, 6, 36, false),
 (64, 22, 1, '꼬부기', '꼬마거북포켓몬', '등껍질의 역할은 몸을 지키는 것뿐만이 아니다. 둥그런 모양과 표면의 홈이 물의 저항을 줄여서 빠르게 헤엄칠 수 있다.', '0.5m', '9kg', '물', 44, 48, 65, 50, 64, 43, 7, null, false),
 (65, 22, 2, '어니부기', '거북포켓몬', '푹신한 털로 덮인 큰 꼬리는 오래 살수록 깊은 색으로 변한다. 등껍질의 상처는 강자임을 증명한다.', '1m', '22.5kg', '물', 59, 63, 80, 65, 80, 58, 8, 16, false),
 (66, 22, 3, '거북왕', '껍질포켓몬', '등껍질의 분사구로 하는 조준은 정확하다. 물 탄환으로 50m 떨어진 빈 캔을 명중시킬 수 있다.', '1.6m', '85.5kg', '물', 79, 83, 100, 85, 105, 78, 9, 36, false),
 (67, 23, 1, '치코리타', '잎사귀포켓몬', '잎사귀를 휘둘러 상대를 위협하지만 잎사귀에서 달콤한 향기가 풍겨 나와 서로 온화한 분위기가 된다.', '0.9m', '6.4kg', '풀', 45, 49, 65, 49, 65, 45, 152, null, false),
 (68, 23, 2, '베이리프', '잎사귀포켓몬', '목 주변의 둥그렇게 말린 잎사귀 안에는 작은 새싹 한 개가 나 있다. 그 향기는 사람을 기운 나게 한다.', '1.2m', '15.8kg', '풀', 60, 62, 80, 63, 80, 60, 153, 16, false),
 (69, 23, 3, '메가니움', '허브포켓몬', '꽃의 향기는 기분을 평안하게 만든다. 싸울 때는 향기를 발산하여 상대의 전의를 떨어뜨린다.', '1.8m', '100.5kg', '풀', 80, 82, 100, 83, 100, 80, 154, 32, false),
 (70, 24, 1, '브케인', '불쥐포켓몬', '등에서 불꽃을 내뿜어 몸을 지킨다. 화났을 때의 불꽃은 기운차지만 지쳤을 때는 불완전연소한다.', '0.5m', '7.9kg', '불꽃', 39, 52, 43, 60, 50, 65, 155, null, false),
 (71, 24, 2, '마그케인', '화산포켓몬', '불꽃의 기세와 열풍으로 위협한다. 재빠른 몸동작으로 상대의 공격을 피하면서 동시에 불꽃으로 태운다.', '0.9m', '19kg', '불꽃', 58, 64, 58, 80, 65, 80, 156, 14, false),
 (72, 24, 3, '블레이범', '화산포켓몬', '작열하는 불꽃으로 주변에 아지랑이를 만들어내서 모습을 숨길 수 있다. 불타오르며 폭발하는 바람은 모든 것을 태운다.', '1.7m', '79.5kg', '불꽃', 78, 84, 78, 109, 85, 100, 157, 36, false),
 (73, 25, 1, '폴리곤', '가상포켓몬', '약 20년 전의 과학 기술로 태어난 포켓몬이기 때문에 지금은 시대에 뒤떨어진 부분도 많다.', '0.8m', '36.5kg', '노말', 65, 60, 70, 85, 75, 40, 137, null, false),
 (74, 25, 2, '폴리곤2', '가상포켓몬', 'AI를 탑재했다. 자력으로 다양한 것을 습득하지만 필요 없는 것까지 배운다.', '0.6m', '32.5kg', '노말', 85, 80, 90, 105, 95, 60, 233, 25, false),
 (75, 25, 3, '폴리곤Z', '가상포켓몬', '불안정한 거동이 눈에 띈다. 프로그램을 업데이트한 기술자의 실력이 문제인 듯하다.', '0.9m', '34kg', '노말', 85, 80, 70, 135, 75, 90, 474, 40, false),
 (76, 26, 1, '찌리리공', '볼포켓몬', '몬스터볼을 만드는 회사에서 처음 발견됐다는 점과 생김새가 비슷한 점의 관련성은 아직도 수수께끼다.', '0.5m', '10.4kg', '전기', 40, 30, 50, 55, 55, 100, 100, null, false),
 (77, 26, 2, '붐볼', '볼포켓몬', '공기 중의 전기 에너지를 먹는다. 번개가 치는 날에는 전기를 너무 먹은 붐볼이 이곳저곳에서 대폭발한다.', '1.2m', '66.6kg', '전기', 60, 50, 70, 80, 80, 150, 101, 30, false),
 (79, 27, 1, '저리어', '전기물고기포켓몬', '한 마리의 전력은 적지만 많은 저리어가 연결되면 번개와 같은 위력이 된다.', '0.2m', '0.3kg', '전기', 35, 55, 40, 45, 40, 60, 602, null, false),
 (80, 27, 2, '저리릴', '전기물고기포켓몬', '상대를 휘감고 동그란 반점에서 전기를 흘려보내 마비시킨 뒤 통째로 문다.', '1.2m', '22kg', '전기', 65, 85, 70, 75, 70, 40, 603, 39, false),
 (81, 27, 3, '저리더프', '전기물고기포켓몬', '흡반 같은 입으로 먹이에 달라붙은 후 박아 넣은 이빨을 통해 전기를 흘려 감전시킨다.', '2.1m', '80.5kg', '전기', 85, 115, 80, 105, 80, 50, 604, null, true),
 (82, 28, 1, '미뇽', '드래곤포켓몬', '아직 약해서 물밑으로 몸을 숨기고 가라앉는 것을 먹으면서 얌전히 지낸다.', '1.8m', '3.3kg', '드래곤', 41, 64, 45, 50, 50, 50, 147, null, false),
 (83, 28, 2, '신뇽', '드래곤포켓몬', '날씨를 조종한다는 믿음 때문에 신뇽이 있는 호수에는 공물이 끊이지 않는다.', '4m', '16.5kg', '드래곤', 61, 84, 65, 70, 70, 70, 148, 30, false),
 (84, 28, 3, '망나뇽', '드래곤포켓몬', '성난 바다도 아랑곳하지 않고 날아간다. 그 모습을 본 선장은 바다의 화신이라고 불렀다.', '2.2m', '210kg', '드래곤/비행', 91, 134, 95, 100, 100, 80, 149, 55, false),
 (85, 29, 1, '아공이', '돌머리포켓몬', '하늘을 나는 새포켓몬을 볼 때마다 부러워서 머리로 주변에 있는 것을 들이받아 산산조각으로 부숴 버린다.', '0.6m', '42.1kg', '드래곤', 45, 75, 60, 40, 30, 50, 371, null, false),
 (86, 29, 2, '쉘곤', '인내포켓몬', '체내의 세포가 빠르게 변화하고 있는 중이다. 단단한 껍질은 뼈와 같은 성분이다.', '1.1m', '110.5kg', '드래곤', 65, 95, 100, 60, 50, 50, 372, 30, false),
 (87, 29, 3, '보만다', '드래곤포켓몬', '드디어 날 수 있다는 기쁨에 넓은 하늘을 날아다닌다. 지쳐서 잠들기 전까지 지상으로 거의 내려오지 않는다.', '1.5m', '102.6kg', '드래곤/비행', 95, 135, 80, 110, 80, 100, 373, 50, false),
 (88, 30, 1, '딥상어동', '육지상어포켓몬', '움직이는 것에 반응하여 달려들어 덥석 문다. 자신이 상처를 입어도 별로 신경 쓰지 않는다.', '0.7m', '20.5kg', '드래곤/땅', 58, 70, 45, 40, 45, 42, 443, null, false),
 (89, 30, 2, '한바이트', '동굴포켓몬', '반짝이는 것을 매우 좋아한다. 멜리시를 노리는 깜까미를 발견하면 격렬하게 화를 내며 덤벼든다.', '1.4m', '56kg', '드래곤/땅', 68, 90, 65, 50, 55, 82, 444, 24, false),
 (90, 30, 3, '한카리아스', '마하포켓몬', '음속으로 날아다니며 먹이를 찾는다. 먹이를 두고 보만다와 공중전을 펼친다.', '1.9m', '95kg', '드래곤/땅', 108, 130, 95, 80, 85, 102, 445, 48, false),
 (91, 31, 1, '푸푸린', '풍선포켓몬', '노래를 잘하고 싶어서 계속 연습을 한다. 잘 때도 꿈속에서 노래를 부른다.', '0.3m', '1kg', '노말/페어리', 90, 30, 15, 40, 20, 15, 174, null, false),
 (92, 31, 2, '푸린', '풍선포켓몬', '백화점 침구 코너에는 푸린의 신비한 자장가를 수록한 CD를 판매하고 있다.', '0.5m', '5.5kg', '노말/페어리', 115, 45, 20, 45, 25, 20, 39, 25, false),
 (93, 31, 3, '푸크린', '풍선포켓몬', '탄력 있는 몸과 세밀한 결의 모피가 인기다. 껴안고 자면 기분 좋다.', '1m', '12kg', '노말/페어리', 140, 70, 45, 85, 50, 45, 40, null, true),
 (94, 32, 1, '알통몬', '괴력포켓몬', '동료들과의 트레이닝으로 자신감과 근육이 생기면 마크탕에게 대결을 신청한다.', '0.8m', '19.5kg', '격투', 70, 80, 50, 35, 35, 35, 66, null, false),
 (95, 32, 2, '근육몬', '괴력포켓몬', '진정한 강적을 만나면 허리의 파워 세이브 벨트를 풀고 전력을 발휘한다.', '1.5m', '70.5kg', '격투', 80, 100, 70, 50, 60, 45, 67, 28, false),
 (96, 32, 3, '괴력몬', '괴력포켓몬', '4개의 팔로 상대를 붙잡아 복잡한 모양으로 세게 조른다. 사람들은 괴력몬 스페셜이라고 부른다.', '1.6m', '130kg', '격투', 90, 130, 80, 65, 85, 55, 68, 40, false),
 (97, 33, 1, '배루키', '싸움포켓몬', '매일 트레이닝하지 않으면 스트레스가 쌓이기 때문에 트레이너는 키울 때 스케줄 관리에 여러모로 고민해야 한다.', '0.7m', '21kg', '격투', 35, 35, 35, 35, 35, 35, 236, null, false),
 (98, 33, 2, '시라소몬', '킥포켓몬', '자유롭게 신축되는 다리로 강렬한 킥을 날려 상대를 발로 차 쓰러트린다. 싸운 뒤에 지친 다리를 주물러 풀어준다.', '1.5m', '49.8kg', '격투', 50, 120, 53, 35, 110, 87, 106, 20, false),
 (100, 34, 1, '리오르', '파문포켓몬', '파동이라고 불리는 파를 보면 사람과 포켓몬의 마음을 알 수 있다. 위험한 상대에게는 다가가지 않는다.', '0.7m', '20.2kg', '격투', 40, 70, 40, 35, 40, 60, 447, null, false),
 (101, 34, 2, '루카리오', '파동포켓몬', '정신을 집중하고 발산하는 파동이라고 불리는 신비한 파는 큰 바위도 산산이 부숴 버린다.', '1.2m', '54kg', '격투/강철', 70, 110, 70, 115, 70, 90, 448, 25, false),
 (103, 35, 1, '기라티나', '반골포켓몬', '상식이 통하지 않는 이 세상의 이면에 있다고 전해지는 깨어진 세계에 서식한다.', '4.5m', '750kg', '고스트/드래곤', 150, 100, 120, 100, 120, 90, 487, null, false),
 (106, 36, 1, '아르세우스', '창조포켓몬', '알에서 모습을 나타내 모든 세계를 창조했다고 신오신화에서 묘사된다.', '3.2m', '320kg', '노말', 120, 120, 120, 120, 120, 120, 493, null, false),
 (109, 37, 1, '뮤', '신종포켓몬', '모든 포켓몬의 유전자를 가졌다고 한다. 자유자재로 모습을 숨길 수 있어서 사람에게 가까이 다가가도 절대 들키지 않는다.', '0.4m', '4kg', '에스퍼', 100, 100, 100, 100, 100, 100, 151, null, false),
 (112, 38, 1, '파이어', '화염포켓몬', '불꽃을 조종하는 전설의 새포켓몬이다. 몸이 상처 입으면 분화구의 마그마에 들어가 전신을 불태워 상처를 치료한다고 한다.', '2m', '60kg', '불꽃/비행', 90, 100, 90, 125, 85, 90, 146, null, false),
 (115, 39, 1, '썬더', '전기포켓몬', '전기를 조종하는 전설의 새포켓몬이다. 평상시는 번개 구름 속에서 지낸다. 번개를 맞으면 힘이 솟아난다.', '1.6m', '52.6kg', '전기/비행', 90, 90, 85, 125, 90, 100, 145, null, false),
 (118, 40, 1, '프리져', '냉동포켓몬', '얼음을 조종하는 전설의 새포켓몬이다. 날갯짓하면 공기가 차갑게 식기 때문에 프리져가 날면 눈이 온다고 전해진다.', '1.7m', '55.4kg', '얼음/비행', 90, 85, 100, 95, 125, 85, 144, null, false),
 (121, 41, 1, '뮤츠', '유전포켓몬', '유전자조작을 통해 만들어진 포켓몬이다. 인간은 과학의 힘으로 몸은 만들었지만 상냥한 마음을 만들 수는 없었다.', '2m', '122kg', '에스퍼', 106, 110, 90, 154, 90, 130, 150, null, false),
 (124, 42, 1, '지가르데', '질서포켓몬', '지가르데의 일부가 반 정도 모인 모습이다. 생태계를 감시하는 역할을 맡고 있다.', '5m', '305kg', '드래곤/땅', 108, 100, 121, 81, 95, 95, 718, null, false),
 (127, 43, 1, '찌르꼬', '찌르레기포켓몬', '많은 수가 무리를 이루어 행동한다. 몸은 작지만 날개 치는 힘은 매우 강하다.', '0.3m', '2kg', '노말/비행', 40, 55, 30, 30, 30, 60, 396, null, false),
 (128, 43, 2, '찌르버드', '찌르레기포켓몬', '큰 그룹을 만들어 행동하는 습성이 있다. 그룹 간의 분쟁이 격하다.', '0.6m', '15.5kg', '노말/비행', 55, 75, 50, 40, 40, 80, 397, 14, false),
 (129, 43, 3, '찌르호크', '맹금포켓몬', '날개와 발의 근육이 강해 작은 포켓몬을 붙잡은 채로 너끈히 날 수 있다.', '1.2m', '24.9kg', '노말/비행', 85, 120, 70, 50, 60, 100, 398, 34, false),
 (130, 44, 1, '몽나', '꿈먹기포켓몬', '나쁜 꿈에 시달리고 있는 포켓몬이나 사람 앞에 나타나 그 꿈을 먹어버리는 포켓몬.', '0.6m', '23.3kg', '에스퍼', 76, 25, 45, 67, 55, 24, 517, null, false),
 (131, 44, 2, '몽얌나', '꿈결포켓몬', '이마에서 나오는 연기 속에는 사람이나 포켓몬이 꾼 꿈이 많이 모여 있다.', '1.1m', '60.5kg', '에스퍼', 116, 55, 85, 107, 95, 29, 518, null, true),
 (133, 45, 1, '아라리', '알포켓몬', '6마리가 1마리다. 어쩌다 1마리가 줄어도 다음날 아침이 되면 다시 6마리로 돌아와 있다.', '0.4m', '2.5kg', '풀/에스퍼', 60, 40, 80, 60, 45, 40, 102, null, false),
 (134, 45, 2, '나시', '야자열매포켓몬', '사이코 파워로 적을 대적한다. 3개의 머리가 각각 염동력을 발산해서 그 위력은 3배가 된다.', '2m', '120kg', '풀/에스퍼', 95, 95, 85, 125, 75, 55, 103, null, true),
 (136, 46, 1, '야돈', '얼간이포켓몬', '하품을 하면 비가 온다는 구전 때문에 야돈을 받을어 모시는 지역도 있다고 한다.', '1.2m', '36kg', '물/에스퍼', 90, 65, 65, 40, 40, 15, 79, null, false),
 (137, 46, 2, '야도란', '기생포켓몬', '기본적으로 멍하니 있다. 꼬리가 끊겨 셀러가 떨어지면 야돈으로 돌아간다.', '1.6m', '78.5kg', '물/에스퍼', 95, 75, 110, 100, 80, 30, 80, 37, false),
 (139, 47, 1, '슬리프', '최면포켓몬', '레저 시설 근처에서 볼 수 있다. 그날 밤 아이가 꾸는 즐거운 꿈을 노리고 있다.', '1m', '32.4kg', '에스퍼', 60, 48, 45, 43, 90, 42, 96, null, false),
 (140, 47, 2, '슬리퍼', '최면포켓몬', '알로라에서 사는 슬리퍼의 타깃은 주로 자말라다. 사람은 그다지 피해를 입지 않는다.', '1.6m', '75.6kg', '에스퍼', 85, 73, 70, 73, 115, 67, 97, 26, false),
 (142, 48, 1, '네이티', '아기새포켓몬', '아직 날 수 없지만, 점프력은 상당하다. 높은 나뭇가지에 뛰어올라 나무순을 쪼아 먹는다.', '0.2m', '2kg', '에스퍼/비행', 40, 50, 45, 70, 45, 70, 177, null, false),
 (143, 48, 2, '네이티오', '정령포켓몬', '미래를 예지하는 힘이 있지만, 미래를 바꿀 정도의 힘은 없다고 전해지는 포켓몬.', '1.5m', '15kg', '에스퍼/비행', 65, 75, 70, 95, 70, 95, 178, 25, false),
 (145, 49, 1, '꾸꾸리', '산돼지포켓몬', '땅에 코를 비비며 먹이를 찾는다. 마른 풀 밑에 난 버섯을 좋아한다. 가끔 온천을 파내기도 한다.', '0.4m', '6.5kg', '얼음/땅', 50, 50, 40, 30, 30, 50, 220, null, false),
 (146, 49, 2, '메꾸리', '멧돼지포켓몬', '얼어붙는 추위에도 버틸 수 있도록 두껍고 긴 털가죽에 덮여 있다. 얼음에 묻힌 먹이를 이빨로 파낸다.', '1.1m', '55.8kg', '얼음/땅', 100, 100, 80, 60, 60, 50, 221, 33, false),
 (147, 49, 3, '맘모꾸리', '2개송곳니포켓몬', '1만 년 전의 얼음 밑에서 발견된 적이 있을 정도로 오랜 옛날부터 있었던 포켓몬이다.', '2.5m', '291kg', '얼음/땅', 110, 130, 80, 70, 60, 80, 473, 43, false),
 (148, 50, 1, '눈꼬마', '눈우산포켓몬', '눈과 얼음이 주요 먹이다. 따듯한 알로라에서는 한정된 장소에서만 살 수 있다.', '0.7m', '16.8kg', '얼음', 50, 50, 50, 50, 50, 50, 361, null, false),
 (149, 50, 2, '얼음귀신', '얼굴포켓몬', '먹이를 얼려 통째로 갉아먹는다. 하지만 바닐프티처럼 처음부터 얼어 있는 포켓몬을 더 좋아한다.', '1.5m', '256.5kg', '얼음', 80, 80, 80, 80, 80, 80, 362, 42, false),
 (151, 51, 1, '바닐프티', '신설포켓몬', '마이너스 50도 냉기를 내뱉는다. 따듯한 장소에 있으면 조금씩 작아진다.', '0.4m', '5.7kg', '얼음', 36, 50, 50, 65, 60, 44, 582, null, false),
 (152, 51, 2, '바닐리치', '빙설포켓몬', '얼음 입자를 세게 내뿜어 적의 몸을 얼린다. 알로라의 바닐리치는 전체적으로 몸집이 작다.', '1.1m', '41kg', '얼음', 51, 65, 65, 80, 75, 59, 583, 35, false),
 (153, 51, 3, '배바닐라', '블리자드포켓몬', '2개의 입에서 눈보라를 뿜어낸다. 어디에서든 눈을 만들어 내기 때문에 스키어나 스노보더에게 인기다.', '1.3m', '57.5kg', '얼음', 71, 95, 85, 110, 95, 79, 584, 47, false),
 (154, 52, 1, '동미러', '청동포켓몬', '동미러의 등 모양에는 신비한 힘이 깃들어 있다고 옛날 사람들은 믿고 있었다.', '0.5m', '60.5kg', '강철/에스퍼', 57, 24, 86, 24, 86, 23, 436, null, false),
 (155, 52, 2, '동탁군', '동탁포켓몬', '비구름을 부르는 포켓몬으로 아주 옛날부터 떠받들어졌다. 가끔 땅에 묻혀 있다.', '1.3m', '187kg', '강철/에스퍼', 67, 89, 116, 79, 116, 33, 437, 33, false),
 (157, 53, 1, '오뚝군', '토우포켓몬', '원시인이 살았던 동굴 벽에 오뚝군으로 추정되는 포켓몬의 모습이 그려져 있다.', '0.5m', '21.5kg', '땅/에스퍼', 40, 40, 55, 40, 70, 55, 343, null, false),
 (158, 53, 2, '점토도리', '토우포켓몬', '젖으면 몸이 녹아버린다. 비가 오면 사이코 파워로 전신을 감싸서 지킨다.', '1.5m', '108kg', '땅/에스퍼', 60, 70, 105, 70, 120, 75, 344, 36, false),
 (160, 54, 1, '코고미', '빙결포켓몬', '언제나 콧물을 달고 다닌다. 콧물을 훌쩍거려 기술을 사용한다. 콧물이 기술의 재료인 셈이다.', '0.5m', '8.5kg', '얼음', 55, 70, 40, 60, 40, 40, 613, null, false),
 (161, 54, 2, '툰베어', '동결포켓몬', '북쪽의 차가운 바다를 좋아한다. 입에서 내뿜는 숨을 얼려 바다 위에 길을 만들어 걷는다.', '2.6m', '260kg', '얼음', 95, 130, 80, 70, 80, 50, 614, 37, false),
 (163, 55, 1, '눈쓰개', '얼음나무포켓몬', '추운 계절에는 산기슭까지 내려오지만 봄이 되면 눈이 남아 있는 산 정상으로 돌아간다.', '1m', '50.5kg', '풀/얼음', 60, 62, 50, 62, 60, 40, 459, null, false),
 (164, 55, 2, '눈설왕', '얼음나무포켓몬', '블리자드를 발생시켜 주변 일대를 새하얗게 만든다. 별명은 아이스 몬스터다.', '2.2m', '135.5kg', '풀/얼음', 90, 92, 75, 92, 85, 60, 460, 40, false),
 (166, 56, 1, '테일로', '아기제비포켓몬', '아무리 강한 상대라도 용감히 맞선다. 져도 주저앉지 않는 근성의 소유자다. 배가 고프면 큰 소리로 운다.', '0.3m', '2.3kg', '노말/비행', 40, 55, 30, 30, 30, 85, 276, null, false),
 (167, 56, 2, '스왈로', '제비포켓몬', '높은 상공을 원을 그리듯 날아다니다 먹이를 발견하면 급강하한다. 발톱으로 단단히 잡고 놓치지 않는다.', '0.7m', '19.8kg', '노말/비행', 60, 85, 60, 75, 50, 125, 277, 22, false),
 (169, 57, 1, '파비코', '솜새포켓몬', '뭉게구름처럼 푹신한 날개를 지녔다. 사람을 무서워하지 않고 솜 모자처럼 머리에 살포시 앉는 포켓몬이다.', '0.4m', '1.2kg', '노말/비행', 45, 40, 60, 40, 75, 50, 333, null, false),
 (170, 57, 2, '파비코리', '허밍포켓몬', '뭉게구름에 뒤섞여 넓은 하늘을 떠돈다. 맑은 목소리로 멜로디를 지저귀면 그 소리를 들은 자들은 꿈꾸는 듯한 기분이 된다.', '1.1m', '20.6kg', '드래곤/비행', 75, 70, 90, 70, 105, 80, 334, 35, false),
 (172, 58, 1, '콩둘기', '아기비둘기포켓몬', '매우 건망증이 심한 포켓몬으로 트레이너에게 명령을 받았어도 새로운 명령을 기다리고 있다.', '0.3m', '2.1kg', '노말/비행', 50, 55, 50, 36, 30, 43, 519, null, false),
 (173, 58, 2, '유토브', '들비둘기포켓몬', '유토브가 사는 숲 속에는 싸움이 없는 평화로운 나라가 있다고 믿어진다.', '0.6m', '15kg', '노말/비행', 62, 77, 62, 50, 42, 65, 520, 21, false),
 (174, 58, 3, '켄호로우', '프라이드포켓몬', '수컷은 머리의 장식을 흔들어서 상대를 위협한다. 암컷의 비행 능력은 수컷을 뛰어넘는다.', '1.2m', '29kg', '노말/비행', 80, 115, 80, 65, 55, 93, 521, 32, false),
 (175, 59, 1, '삐', '별포켓몬', '별똥별이 많은 밤에 둥글게 무리 지어 춤을 춘다. 그 모습을 보면 조금 좋은 일이 생긴다.', '0.3m', '3kg', '페어리', 50, 25, 28, 45, 55, 15, 173, null, false),
 (176, 59, 2, '삐삐', '요정포켓몬', '인기가 있지만, 개체 수가 적어 귀하다. 함부로 자랑하다가는 도둑의 타깃이 된다.', '0.6m', '7.5kg', '페어리', 70, 45, 48, 60, 65, 35, 35, 25, false),
 (177, 59, 3, '픽시', '요정포켓몬', '1km 떨어진 곳에서 바늘이 떨어지는 소리도 들을 수 있어 사람과 포켓몬이 적은 깊은 산속에 산다.', '1.3m', '40kg', '페어리', 95, 70, 73, 95, 90, 60, 36, null, true),
 (178, 60, 1, '블루', '요정포켓몬', '금방 따르고 금방 응석을 부린다. 하는 행동과 생김새의 격차 때문에 젊은 여성은 헤롱헤롱하는 듯하다.', '0.6m', '7.8kg', '페어리', 60, 80, 50, 40, 40, 30, 209, null, false),
 (179, 60, 2, '그랑블루', '요정포켓몬', '턱의 힘은 강력하지만 다툼을 좋아하지 않아 그다지 싸우는 걸 볼 기회가 많지 않다.', '1.4m', '48.7kg', '페어리', 90, 120, 75, 60, 60, 45, 210, 23, false),
 (181, 61, 1, '슈쁘', '향수포켓몬', '냄새를 맡은 자를 황홀하게 만드는 향기를 몸에서 풍긴다. 먹은 먹이에 따라 향기가 달라진다.', '0.2m', '0.5kg', '페어리', 78, 52, 60, 63, 65, 23, 682, null, false),
 (182, 61, 2, '프레프티르', '방향포켓몬', '여러 가지 향기를 만들어 낸다. 상대가 싫어하는 냄새를 내보내 싸움을 유리하게 이끌어 나간다.', '0.8m', '15.5kg', '페어리', 101, 72, 72, 99, 89, 29, 683, 25, false),
 (184, 62, 1, '수리둥보', '새끼독수리포켓몬', '강한 다릿심과 튼튼한 발톱으로 딱딱한 셀러의 껍질도 부수고 안에 있는 내용물을 쪼아 먹는다.', '0.5m', '10.5kg', '노말/비행', 70, 83, 50, 37, 50, 60, 627, null, false),
 (185, 62, 2, '워글', '용맹포켓몬', '안면에 상처가 많을수록 용감하다고 평가받고 뒤에 상처가 많으면 무리에서 무시당한다.', '1.5m', '41kg', '노말/비행', 100, 123, 75, 57, 75, 80, 628, 54, false),
 (187, 63, 1, '메리프', '솜털포켓몬', '메리프의 털로 만든 의복은 정전기가 잘 일어나기 때문에 특수한 가공이 되어 있다.', '0.6m', '7.8kg', '전기', 55, 40, 40, 65, 45, 35, 179, null, false),
 (188, 63, 2, '보송송', '솜털포켓몬', '털이 나지 않은 고무 같은 피부는 전기가 통하지 않아 만져도 안전하다.', '0.8m', '13.3kg', '전기', 70, 55, 55, 80, 60, 45, 180, 15, false),
 (189, 63, 3, '전룡', '라이트포켓몬', '꼬리의 빛은 우주까지 도달하여 어디에 있든 바로 알 수 있다. 그래서 평소에는 끄고 있다.', '1.4m', '61.5kg', '전기', 90, 75, 85, 115, 90, 55, 181, 30, false),
 (190, 64, 1, '꼬링크', '섬광포켓몬', '몸을 움직일 때마다 근육이 늘어났다 줄어들었다 하여 전기가 발생한다. 궁지에 몰리면 몸이 빛난다.', '0.5m', '9.5kg', '전기', 45, 65, 34, 40, 34, 45, 403, null, false),
 (191, 64, 2, '럭시오', '전광포켓몬', '발톱에서는 한 방에 적을 기절시킬 정도로 강한 전류가 흐른다. 여러 마리가 그룹을 이루어 산다.', '0.9m', '30.5kg', '전기', 60, 85, 49, 60, 49, 60, 404, 15, false),
 (192, 64, 3, '렌트라', '안광포켓몬', '눈동자가 금색으로 빛날 때 벽의 저편에 숨어 있는 먹이를 찾아낼 수 있다.', '1.4m', '42kg', '전기', 80, 120, 79, 95, 79, 70, 405, 30, false),
 (193, 65, 1, '파쪼옥', '들러붙기포켓몬', '스스로 전기를 만들 수 없어 다른 큰 포켓몬에 달라붙어 정전기를 흡수한다.', '0.1m', '0.6kg', '벌레/전기', 50, 47, 50, 57, 50, 65, 595, null, false),
 (194, 65, 2, '전툴라', '전기거미포켓몬', '전기를 띤 실로 함정을 설치한다. 감전돼서 움직이지 못하는 먹이를 천천히 먹어치운다.', '0.8m', '14.3kg', '벌레/전기', 70, 77, 60, 97, 60, 108, 596, 36, false),
 (196, 66, 1, '니드런♂', '독침포켓몬', '귀를 움직이는 근육이 발달되어 있어서 어떤 방향으로든 자유로이 귀를 움직일 수 있다. 희미한 소리도 빠트리지 않고 듣는 포켓몬이다.', '0.5m', '9kg', '독', 46, 57, 40, 40, 40, 50, 32, null, false),
 (197, 66, 2, '니드리노', '독침포켓몬', '다이아몬드보다 단단한 뿔을 지녔다. 적의 기척을 느끼면 등에 달린 가시를 일제히 세우고 전력을 다해 맞선다.', '0.9m', '19.5kg', '독', 61, 72, 57, 55, 55, 65, 33, 16, false),
 (198, 66, 3, '니드킹', '드릴포켓몬', '두꺼운 꼬리는 한 번 휘두르면 튼튼한 철탑도 꺾어 버리는 엄청난 파괴력을 지녔다. 한 번 날뛰기 시작하면 손쓸 수 없다.', '1.4m', '62kg', '독/땅', 81, 102, 77, 85, 75, 85, 34, null, true),
 (199, 67, 1, '질퍽이', '진흙포켓몬', '바다 밑의 진흙에서 태어났다. 청결한 장소에서는 체내의 세균이 증식되지 않아 죽어 버린다.', '0.9m', '30kg', '독', 80, 80, 50, 40, 50, 25, 88, null, false),
 (200, 67, 2, '질뻐기', '진흙포켓몬', '먹이가 줄어들어 개체 수가 격감했다. 멸종을 방지하기 위해 인공 진흙 연못을 만들기 시작했다.', '1.2m', '30kg', '독', 105, 105, 75, 65, 100, 50, 89, 38, false),
 (202, 68, 1, '뿔충이', '송충이포켓몬', '굉장히 예민한 후각을 지니고 있다. 좋아하는 잎사귀인지 싫어하는 잎사귀인지 크고 빨간 코로 냄새 맡아 구별한다.', '0.3m', '3.2kg', '벌레/독', 40, 35, 30, 20, 20, 50, 13, null, false),
 (203, 68, 2, '딱충이', '번데기포켓몬', '거의 움직이지 않고 나무에 매달려 있지만 내부는 진화 준비로 굉장히 바쁜 상태다. 그 증거로 몸이 뜨거워져 있다.', '0.6m', '10kg', '벌레/독', 45, 25, 50, 25, 25, 35, 14, 7, false),
 (204, 68, 3, '독침붕', '독벌포켓몬', '영역에 대한 집착이 매우 강해서 독침붕이 사는 곳에는 가까이 가지 않는 것이 신상에 좋다. 화나면 집단으로 습격해 온다.', '1m', '29.5kg', '벌레/독', 65, 90, 40, 45, 80, 75, 15, 10, false),
 (205, 69, 1, '뚜벅쵸', '잡초포켓몬', '낮에 땅속에 몸을 묻고 땅의 영양을 전신으로 빨아올린다. 비옥한 땅일수록 잎사귀에 윤이 난다고 한다.', '0.5m', '5.4kg', '풀/독', 45, 50, 55, 75, 65, 30, 43, null, false),
 (206, 69, 2, '냄새꼬', '잡초포켓몬', '위험을 느끼면 암술에서 내는 구린 냄새가 더 강해지지만 마음이 평안할 때는 구린 냄새를 내지 않는다.', '0.8m', '8.6kg', '풀/독', 60, 65, 70, 85, 75, 40, 44, 21, false),
 (207, 69, 3, '라플레시아', '꽃포켓몬', '독 꽃가루는 심한 알레르기를 일으킨다. 정글에서 아름다운 꽃을 발견해도 섣불리 다가가지 않는 것이 좋다.', '1.2m', '18.6kg', '풀/독', 75, 80, 85, 110, 90, 50, 45, null, true),
 (208, 70, 1, '모다피', '꽃포켓몬', '가늘고 유연한 몸은 아무리 강한 공격이라도 휘어져 피할 수 있다. 입에서 철도 녹일 수 있는 액체가 나온다.', '0.7m', '4kg', '풀/독', 50, 75, 35, 70, 30, 40, 69, null, false),
 (209, 70, 2, '우츠동', '파리잡이포켓몬', '밤이 되면 엉덩이의 갈고리를 나뭇가지에 걸고 매달려서 잠든다. 잠버릇이 나쁘면 아침에 떨어져 있다.', '1m', '6.4kg', '풀/독', 65, 90, 50, 85, 45, 55, 70, 21, false),
 (210, 70, 3, '우츠보트', '파리잡이포켓몬', '머리에 달린 긴 덩굴을 작은 생물처럼 움직여서 먹이를 유인한다. 가까이 왔을 때 덥석 한 번에 삼킨다.', '1.7m', '15.5kg', '풀/독', 80, 105, 65, 100, 70, 70, 71, null, true),
 (211, 71, 1, '애버라스', '바위표면포켓몬', '지하에서 태어나 흙을 먹으면서 어버이가 있는 지상을 향해 올라간다. 눈이 부셔서 빛은 좋아하지 않는다.', '0.6m', '72kg', '바위/땅', 50, 64, 50, 45, 50, 41, 246, null, false),
 (212, 71, 2, '데기라스', '탄환포켓몬', '진화를 기다리지 못하고 압축가스로 날아다니며 날뛰어 스트레스를 해소하는 성가신 포켓몬.', '1.2m', '152kg', '바위/땅', 70, 84, 70, 65, 70, 51, 247, 30, false),
 (213, 71, 3, '마기라스', '갑옷포켓몬', '싸울 상대를 찾아 산을 떠돈다. 만나도 격이 떨어지는 상대라고 무시하고 떠나간다.', '2m', '202kg', '바위/악', 100, 134, 110, 95, 100, 61, 248, 55, false),
 (214, 72, 1, '쏘드라', '드래곤포켓몬', '작은 벌레나 바위의 이끼를 먹는다. 해류가 빨라지면 꼬리로 바위나 산호를 휘감아 떠내려가지 않게 한다.', '0.4m', '8kg', '물', 30, 40, 70, 70, 25, 60, 116, null, false),
 (215, 72, 2, '시드라', '드래곤포켓몬', '산호 가지 사이로 들어가 잠잔다. 시드라가 있는 줄 모르고 산호를 잡으려다 독가시에 찔리곤 한다.', '1.2m', '25kg', '물', 55, 65, 95, 95, 45, 85, 117, 32, false),
 (216, 72, 3, '킹드라', '드래곤포켓몬', '생물이 살지 않는 심해에 서식한다. 킹드라의 하품이 해류의 소용돌이를 일으킨다고 오랫동안 믿어져 왔다.', '1.8m', '152kg', '물/드래곤', 75, 95, 95, 95, 95, 85, 230, 42, false),
 (217, 73, 1, '마자', '명랑포켓몬', '언제나 싱글벙글 미소 짓는 마자. 화났을 때는 꼬리에 주목하자. 땅을 탁탁 치고 있다.', '0.6m', '14kg', '에스퍼', 95, 23, 48, 23, 48, 23, 360, null, false),
 (218, 73, 2, '마자용', '참기포켓몬', '두 마리 이상 모이면 참기 겨루기를 시작하는데 배고픔도 참아버리기 때문에 마자용 트레이너는 주의가 필요하다.', '1.3m', '28.5kg', '에스퍼', 190, 33, 58, 33, 58, 33, 202, 15, false),
 (220, 74, 1, '포챠나', '물어뜯기포켓몬', '움직이는 것을 발견하면 바로 문다. 먹이가 기진맥진해질 때까지 쫓아다니지만 반격당하면 뒷걸음치기도 한다.', '0.5m', '13.6kg', '악', 35, 55, 35, 30, 30, 35, 261, null, false),
 (221, 74, 2, '그라에나', '물어뜯기포켓몬', '사납게 으르렁거리는 소리를 내며 자세를 낮추고 있는 것은 공격의 전조이다. 날카롭고 뾰족한 이빨로 덥석 문다.', '1m', '37kg', '악', 70, 90, 70, 60, 60, 70, 262, 18, false),
 (223, 75, 1, '리아코', '큰턱포켓몬', '몸은 작지만 턱의 힘은 강하다. 리아코 나름은 살포시 물려고 하지만 큰 상처를 입힐 정도의 힘이 있다.', '0.6m', '9.5kg', '물', 50, 65, 64, 44, 48, 43, 158, null, false),
 (224, 75, 2, '엘리게이', '큰턱포켓몬', '한 번 물고 늘어지면 절대로 놓지 않는다. 이빨 끝이 낚싯바늘처럼 휘어져 있어서 한 번 들어가면 빠지지 않는다.', '1.1m', '25kg', '물', 65, 80, 80, 59, 63, 58, 159, 18, false),
 (225, 75, 3, '장크로다일', '큰턱포켓몬', '큰 입을 열고 상대를 위협한다. 강인한 뒷다리로 땅을 차고 굉장한 스피드로 돌진해온다.', '2.3m', '88.8kg', '물', 85, 105, 100, 79, 83, 78, 160, 30, false),
 (226, 76, 1, '으랏차', '근골포켓몬', '항상 각목을 끼고 있다. 건설 현장에 나타나 공사를 도와주는 포켓몬이다.', '0.6m', '12.5kg', '격투', 75, 80, 55, 25, 35, 35, 532, null, false),
 (227, 76, 2, '토쇠골', '근골포켓몬', '단련된 근육의 소유자. 철골을 능숙하게 조종하여 집을 해체해준다.', '1.2m', '40kg', '격투', 85, 105, 85, 40, 50, 40, 533, 25, false),
 (228, 76, 3, '노보청', '근골포켓몬', '콘크리트를 만드는 기술은 2000년 전에 노보청에게 배운 것이라고 여겨지고 있다.', '1.4m', '87kg', '격투', 105, 140, 95, 55, 65, 45, 534, 40, false),
 (229, 77, 1, '제르네아스', '생명포켓몬', '영원한 생명을 나누어 준다고 한다. 수목의 모습으로 1000년 동안 잠들고 부활한다.', '3m', '215kg', '페어리', 126, 131, 95, 131, 98, 99, 716, null, false),
 (232, 78, 1, '이벨타르', '파괴포켓몬', '날개와 꼬리를 펼치고 빨갛게 빛날 때 살아 있는 생명을 빨아들이는 전설의 포켓몬.', '5.8m', '203kg', '악/비행', 126, 131, 95, 131, 98, 99, 717, null, false),
 (235, 79, 1, '볼케니온', '스팀포켓몬', '수증기를 뿜어내어 자신의 모습을 짙은 안개 속에 숨긴다. 사람이 오지 않는 산에 산다고 한다.', '1.7m', '195kg', '불꽃/물', 80, 110, 120, 130, 90, 70, 721, null, false),
 (238, 80, 1, '마나피', '회유포켓몬', '태어났을 때부터 가지고 있는 이상한 힘을 쓰면 어떤 포켓몬과도 마음이 서로 통하게 된다.', '0.3m', '1.4kg', '물', 100, 100, 100, 100, 100, 100, 490, null, false),
 (241, 81, 1, '메로엣타', '선율포켓몬', '메로엣타가 연주하는 선율에는 주위 포켓몬을 기쁘게 하거나 슬프게 할 정도의 힘이 있다.', '0.6m', '6.5kg', '노말/에스퍼', 100, 77, 77, 128, 128, 90, 648, null, false),
 (244, 82, 1, '세레비', '시간이동포켓몬', '시간을 넘어 미래에서 찾아온 포켓몬이다. 세레비가 모습을 나타내는 한 밝은 미래가 기다린다고 여겨지고 있다.', '0.6m', '5kg', '에스퍼/풀', 100, 100, 100, 100, 100, 100, 251, null, false),
 (247, 83, 1, '꼬렛', '쥐포켓몬', '평생 앞니가 계속 자란다. 너무 많이 자라면 먹이를 먹을 수 없어 굶어 죽는다.', '0.3m', '3.5kg', '노말', 30, 56, 35, 25, 35, 72, 19, null, false),
 (248, 83, 2, '레트라', '쥐포켓몬', '뒷발의 작의 물갈퀴로 바다를 헤엄쳐 섬을 건너 적을 피해 도망쳤다고 한다.', '0.7m', '18.5kg', '노말', 55, 81, 60, 50, 70, 97, 20, 20, false),
 (250, 84, 1, '아보', '뱀포켓몬', '턱을 빼 자신보다 큰 먹이를 통째로 삼킨다. 식후에는 몸을 둥글게 하고 쉰다.', '2m', '6.9kg', '독', 35, 60, 44, 40, 54, 55, 23, null, false),
 (251, 84, 2, '아보크', '코브라포켓몬', '최근 연구에서 배 모양은 20종류 이상의 패턴이 있다고 판명되었다.', '3.5m', '65kg', '독', 60, 95, 69, 65, 79, 80, 24, 22, false),
 (253, 85, 1, '모래두지', '쥐포켓몬', '비가 적은 토지에 살고 있다. 위험한 상황이 되면 몸을 웅크려 부드러운 배를 지킨다.', '0.6m', '12kg', '땅', 50, 75, 85, 20, 30, 40, 27, null, false),
 (254, 85, 2, '고지', '쥐포켓몬', '발톱과 뿔이 잘 부러진다. 부러진 발톱과 뿔은 땅을 일구는 도구로 만들어진다.', '1m', '29.5kg', '땅', 75, 100, 110, 45, 55, 65, 28, 22, false),
 (256, 86, 1, '식스테일', '여우포켓몬', '아름다운 꼬리 때문에 인기가 많다. 단 바지런히 빗질을 하지 않으면 순식간에 헝클어진다.', '0.6m', '9.9kg', '불꽃', 38, 41, 40, 50, 65, 65, 37, null, false),
 (257, 86, 2, '나인테일', '여우포켓몬', '끈질기고 집념이 강한 성질을 가졌다. 한 번 원한을 사면 자손을 포함해 1000년간 해를 입는다.', '1.1m', '19.9kg', '불꽃', 73, 76, 75, 81, 100, 100, 38, null, true),
 (259, 87, 1, '파라스', '버섯포켓몬', '습도가 낮아서인지 영양이 부족해서인지 알로라 파라스의 버섯은 성장이 그저 그렇다.', '0.3m', '5.4kg', '벌레/풀', 35, 70, 55, 45, 55, 25, 46, null, false),
 (260, 87, 2, '파라섹트', '버섯포켓몬', '벌레는 거의 죽은 상태이고 본체는 등의 버섯이다. 떨어지면 더는 움직일 수 없다.', '1m', '29.5kg', '벌레/풀', 60, 95, 80, 60, 80, 30, 47, 24, false),
 (262, 88, 1, '콘팡', '곤충포켓몬', '몸을 지키기 위해 가늘고 딱딱한 털이 전신을 둘러싸게 됐다고 전해진다. 작은 먹잇감도 놓치지 않는 눈을 가졌다.', '1m', '30kg', '벌레/독', 60, 55, 50, 40, 55, 45, 48, null, false),
 (263, 88, 2, '도나리', '독나방포켓몬', '야행성으로 밤에 활동을 시작한다. 가로등 빛에 이끌려 모여든 작은 벌레를 즐겨 먹는다.', '1.5m', '12.5kg', '벌레/독', 70, 65, 60, 90, 75, 90, 49, 31, false),
 (265, 89, 1, '디그다', '두더지포켓몬', '지하에 터널을 파서 이동한다. 빛을 싫어해서 해가 진 후에 지상으로 나온다.', '0.2m', '0.8kg', '땅', 10, 55, 25, 35, 45, 95, 50, null, false),
 (266, 89, 2, '닥트리오', '두더지포켓몬', '언제나 사이좋은 세쌍둥이지만 극히 드물게 어느 머리가 먼저 먹이를 먹을까로 큰 싸움을 한다.', '0.7m', '33.3kg', '땅', 35, 100, 50, 50, 70, 120, 51, 26, false),
 (268, 90, 1, '나옹', '요괴고양이포켓몬', '쓰레기장에 가면 빛이 나는 물건을 두고 니로우와 격렬하게 싸우는 광경을 볼 수 있다.', '0.4m', '4.2kg', '노말', 40, 45, 35, 40, 40, 90, 52, null, false),
 (269, 90, 2, '페르시온', '샴고양이포켓몬', '알로라의 페르시온과는 이마의 보석 색깔이 다르지만, 성분은 크게 다르지 않다.', '1m', '32kg', '노말', 65, 70, 60, 65, 65, 115, 53, 28, false),
 (271, 91, 1, '고라파덕', '오리포켓몬', '염동력을 사용하면 두통이 생겨서 평소에는 아무것도 하지 않고 가능한 멍하니 지낸다.', '0.8m', '19.6kg', '물', 50, 52, 48, 65, 50, 55, 54, null, false),
 (272, 91, 2, '골덕', '오리포켓몬', '빠르게 헤엄치는 물고기포켓몬이라도 사슬묶기로 꼼짝 못 하게 해서 쉽게 잡을 수 있다.', '1.7m', '76.6kg', '물', 80, 82, 78, 95, 80, 85, 55, 33, false),
 (274, 92, 1, '망키', '돈숭이포켓몬', '작은 일에도 금방 화를 낸다. 스트레스를 쌓아 두지 않아서 꽤 오래 사는 포켓몬이다.', '0.5m', '28kg', '격투', 40, 80, 35, 35, 45, 70, 56, null, false),
 (275, 92, 2, '성원숭', '돈숭이포켓몬', '화나게 한 상대를 용서하지 않고 계속 쫓아다닌다. 때려눕혀 움직일 수 없게 돼도 용서하지 않는다.', '1m', '32kg', '격투', 65, 105, 60, 60, 70, 95, 57, 28, false),
 (277, 93, 1, '가디', '강아지포켓몬', '익숙해지면 사람을 잘 따르지만, 야생에서는 암멍이와 영역을 두고 격렬히 다툰다.', '0.7m', '19kg', '불꽃', 55, 70, 45, 70, 50, 60, 58, null, false),
 (278, 93, 2, '윈디', '전설포켓몬', '아주 먼 옛날 어느 장수와 함께 싸워 나라를 다스렸다고 하는 전설이 남아 있다.', '1.9m', '155kg', '불꽃', 90, 110, 80, 100, 80, 95, 59, null, true),
 (280, 94, 1, '왕눈해', '해파리포켓몬', '해변을 떠다니며 먹이를 찾는다. 독이 있는 촉수는 끊어지기도 하지만 시간이 흐르면 다시 자란다.', '0.9m', '45.5kg', '물/독', 40, 40, 35, 50, 100, 70, 72, null, false),
 (281, 94, 2, '독파리', '해파리포켓몬', '붉은 구슬로 초음파를 발생시켜 먹이가 약해지면 80개의 촉수로 휘감는다.', '1.6m', '55kg', '물/독', 80, 70, 65, 80, 120, 100, 73, 30, false),
 (283, 95, 1, '포니타', '불의말포켓몬', '막 태어나서는 겨우 설 수 있는 정도지만 넘어지면서 부모의 뒤를 쫓아다니는 동안 하반신이 튼튼하게 자라난다.', '1m', '30kg', '불꽃', 50, 85, 55, 65, 65, 90, 77, null, false),
 (284, 95, 2, '날쌩마', '불의말포켓몬', '평상시는 느긋하게 들판을 뛰어다니지만 한 번 마음먹으면 갈기의 불꽃을 불태우며 시속 240km로 달린다.', '1.7m', '95kg', '불꽃', 65, 100, 70, 80, 80, 105, 78, 40, false),
 (286, 96, 1, '파오리', '청둥오리포켓몬', '가지고 있는 식물의 줄기에도 좋은 것과 그렇지 않은 것이 있는 듯하여 파오리들이 줄기를 둘러싸고 싸우는 일도 있다.', '0.8m', '15kg', '노말/비행', 52, 90, 55, 58, 62, 60, 83, null, false),
 (289, 97, 1, '두두', '쌍둥이새포켓몬', '2개의 머리가 동시에 잠드는 일은 없다. 자고 있을 때 적에게 습격당하지 않도록 교대로 망을 보고 있기 때문이다.', '1.4m', '39.2kg', '노말/비행', 35, 85, 45, 35, 35, 75, 84, null, false),
 (290, 97, 2, '두트리오', '세쌍둥이새포켓몬', '3개의 머리가 서로 다른 방향을 향하고 있을 때는 경계 중인 증거다. 섣불리 가까이 가면 부리에 쪼인다.', '1.8m', '85.2kg', '노말/비행', 60, 110, 70, 60, 60, 110, 85, 31, false),
 (292, 98, 1, '쥬쥬', '강치포켓몬', '차가운 바다에서만 산다고 추정되었다. 알로라에 나타나는 이유를 알 수 없다.', '1.1m', '90kg', '물', 65, 45, 55, 45, 70, 45, 86, null, false),
 (293, 98, 2, '쥬레곤', '강치포켓몬', '8노트의 속도로 바다를 헤엄쳐 먹이가 되는 포켓몬을 찾는다. 특히 약어리를 매우 좋아한다.', '1.7m', '120kg', '물/얼음', 90, 70, 80, 70, 95, 70, 87, 34, false),
 (295, 99, 1, '셀러', '두조개포켓몬', '껍질 안에 쌓인 모래는 이윽고 진주가 되지만 방해가 되기 때문에 뱉어 버린다.', '0.3m', '4kg', '물', 30, 65, 100, 45, 25, 40, 90, null, false),
 (296, 99, 2, '파르셀', '두조개포켓몬', '매우 단단한 껍질을 갖고 있다. 껍질에 생긴 상처는 점점 부풀어서 크고 날카로운 가시로 자란다.', '1.5m', '132.5kg', '물/얼음', 50, 95, 180, 85, 45, 70, 91, null, true),
 (298, 100, 1, '롱스톤', '돌뱀포켓몬', '뇌에 자석이 있어서 땅속을 파고 나가도 방향을 틀리지 않는다. 나이를 먹을수록 몸이 둥그스름해진다.', '8.8m', '210kg', '바위/땅', 35, 45, 160, 30, 45, 70, 95, null, false),
 (299, 100, 2, '강철톤', '철뱀포켓몬', '롱스톤보다 깊은 땅속에 살고 있다. 지구의 중심을 향해 파고들어 가서 깊이가 1km에 달하기도 한다.', '9.2m', '400kg', '강철/땅', 75, 85, 200, 55, 65, 30, 208, 25, false),
 (301, 101, 1, '크랩', '게포켓몬', '모래 해변에 구멍을 뚫고 거기서 살고 있다. 먹이가 적은 모래 해변에서는 자리 확보를 위해 다투는 크랩들을 볼 수 있다.', '0.4m', '6.5kg', '물', 30, 105, 90, 25, 25, 50, 98, null, false),
 (302, 101, 2, '킹크랩', '집게포켓몬', '킹크랩은 거대한 집게를 휘둘러 동료 간에 신호를 보내지만 집게가 무거워서 곧 지쳐버린다.', '1.3m', '60kg', '물', 55, 130, 115, 50, 50, 75, 99, 28, false),
 (304, 102, 1, '탕구리', '고독포켓몬', '밤이 되면 죽은 엄마를 생각하며 울부짖는데, 그 탓에 천적인 버랜지나에게 발각된다.', '0.4m', '6.5kg', '땅', 50, 50, 95, 40, 50, 35, 104, null, false),
 (305, 102, 2, '텅구리', '뼈다귀포켓몬', '뼈를 던져 버랜지나를 떨어뜨린다. 부모의 원한을 갚기 위한 것으로 추측된다.', '1m', '45kg', '땅', 60, 80, 110, 50, 80, 45, 105, 28, false),
 (307, 103, 1, '홍수몬', '펀치포켓몬', '세계 챔피언을 목표했던 복서의 혼이 깃들었다고 하는 홍수몬은 불굴의 정신으로 절대 지쳐 쓰러지지 않는다.', '1.4m', '50.2kg', '격투', 50, 105, 79, 35, 110, 76, 107, null, false),
 (310, 104, 1, '내루미', '핥기포켓몬', '긴 혀를 내밀어 몇 번이고 핥아 확인한다. 핥은 부분을 방치하면 염증이 생긴다.', '1.2m', '65.5kg', '노말', 90, 55, 75, 60, 75, 30, 108, null, false),
 (311, 104, 2, '내룸벨트', '핥기포켓몬', '혀가 어디까지 늘어나는지 콘테스트가 열린다. 현재 최고 기록은 25m다.', '1.7m', '140kg', '노말', 110, 85, 95, 80, 95, 50, 463, 25, false),
 (313, 105, 1, '또가스', '독가스포켓몬', '자극받으면 가스의 독소가 강해져 몸의 이곳저곳에서 강하게 내뿜는다. 동그랗게 부풀어 오른 후 대폭발한다.', '0.6m', '1kg', '독', 40, 65, 95, 60, 45, 35, 109, null, false),
 (314, 105, 2, '또도가스', '독가스포켓몬', '부패한 음식물 쓰레기에서 나온 가스를 매우 좋아한다. 청소하지 않는 집에서 눌러살며 가족이 모두 잠든 한밤중에 쓰레기통을 뒤진다.', '1.2m', '9.5kg', '독', 65, 90, 120, 85, 70, 60, 110, 35, false),
 (316, 106, 1, '뿔카노', '뿔포켓몬', '오로지 곧장 돌진하여 부순다. 강철 덩어리에 부딪혀도 멀쩡하지만 하루가 지나면 아픔을 조금 느낀다.', '1m', '115kg', '땅/바위', 80, 85, 95, 30, 30, 25, 111, null, false),
 (317, 106, 2, '코뿌리', '드릴포켓몬', '뿔은 다이아몬드 원석을 부수고 꼬리의 일격은 빌딩을 쓰러트린다. 단단한 피부는 대포에도 상처 입지 않는다.', '1.9m', '120kg', '땅/바위', 105, 130, 120, 45, 45, 40, 112, 42, false),
 (318, 106, 3, '거대코뿌리', '드릴포켓몬', '손바닥의 구멍에서 꼬마돌을 발사한다. 전신의 프로텍터는 화산의 분화도 견뎌낸다.', '2.4m', '282.8kg', '땅/바위', 115, 140, 130, 55, 55, 40, 464, 52, false),
 (319, 107, 1, '덩쿠리', '넝쿨포켓몬', '적에게 붙잡히면 덩굴이 뚝 하고 끊긴다. 전혀 아프지 않기 때문에 그 틈에 도망간다. 다음 날에는 새로운 덩굴이 자란다.', '1m', '35kg', '풀', 65, 55, 115, 100, 40, 60, 114, null, false),
 (320, 107, 2, '덩쿠림보', '넝쿨포켓몬', '식물의 덩굴로 이루어진 팔을 늘여서 먹이를 포박한다. 팔을 먹혀도 아무렇지도 않다.', '2m', '128.6kg', '풀', 100, 100, 125, 110, 50, 50, 465, 25, false),
 (322, 108, 1, '캥카', '가족포켓몬', '배의 주머니에 자신의 새끼를 넣어 지킨다. 새끼에게 해를 끼치는 자는 절대 용서하지 않고 때려눕힌다.', '2.2m', '80kg', '노말', 105, 95, 80, 40, 80, 90, 115, null, false),
 (325, 109, 1, '콘치', '금붕어포켓몬', '아름다운 꼬리지느러미가 특징이지만 콘치끼리는 뿔의 굵기와 날카로움을 겨루는 듯 하다.', '0.6m', '15kg', '물', 45, 67, 60, 35, 50, 63, 118, null, false),
 (326, 109, 2, '왕콘치', '금붕어포켓몬', '뿔이 드릴처럼 회전하기 때문에 단단한 바위도 쉽게 뚫는다. 수컷이 선명한 색을 띤다.', '1.3m', '39kg', '물', 80, 92, 65, 65, 80, 68, 119, 33, false),
 (328, 110, 1, '별가사리', '별포켓몬', '무수한 별들이 바다로 떨어져 별가사리가 되었다고 하는 민화가 각지에 남아 있다.', '0.8m', '34.5kg', '물', 30, 45, 55, 70, 55, 85, 120, null, false),
 (329, 110, 2, '아쿠스타', '수수께끼포켓몬', '빛나는 코어는 바다의 보석이라고 불린다. 고가의 액세서리로 만들어져 은밀히 거래된다.', '1.1m', '80kg', '물/에스퍼', 60, 75, 85, 100, 85, 115, 121, null, true),
 (331, 111, 1, '스라크', '버마재비포켓몬', '날카로운 2개의 낫은 단순한 무기가 아니다. 요령 있게 먹이를 발라 먹는다.', '1.5m', '56kg', '벌레/비행', 70, 110, 80, 55, 80, 105, 123, null, false),
 (332, 111, 2, '핫삼', '집게포켓몬', '강철 같은 몸을 가졌다. 완고하고 무거운 집게는 적을 잡기보다 때려눕히기에 적당하다.', '1.8m', '118kg', '벌레/강철', 70, 130, 100, 55, 80, 65, 212, 25, false),
 (334, 112, 1, '쁘사이저', '뿔집게포켓몬', '투구뿌논과 영역 다툼을 한다. 알로라에서는 어째서인지 헤라크로스와 사이가 좋은 듯하다.', '1.5m', '55kg', '벌레', 65, 125, 100, 55, 70, 85, 127, null, false),
 (337, 113, 1, '켄타로스', '성난소포켓몬', '집단생활을 한다. 무리 중에서 가장 굵고 길며 상처가 많은 뿔을 가진 것이 보스다.', '1.4m', '88.4kg', '노말', 75, 100, 95, 40, 70, 110, 128, null, false),
 (340, 114, 1, '잉어킹', '물고기포켓몬', '먼 옛날에는 그럭저럭 강한 편이었으나 시간이 흐르면서 점점 약해졌다.', '0.9m', '10kg', '물', 20, 10, 55, 15, 20, 80, 129, null, false),
 (341, 114, 2, '갸라도스', '흉악포켓몬', '파괴광선을 무자비하게 쏘아 주변 일대를 태워 버린다. 파괴의 신이라고 부르는 지방도 있다.', '6.5m', '235kg', '물/비행', 95, 125, 79, 60, 100, 81, 130, 20, false),
 (343, 115, 1, '라프라스', '탈것포켓몬', '사람을 태우고 헤엄치는 것을 좋아한다. 알로라지방에서는 소중한 수상 교통수단이다.', '2.5m', '220kg', '물/얼음', 130, 85, 80, 85, 95, 60, 131, null, false),
 (346, 116, 1, '메타몽', '변신포켓몬', '뭐든지 변신할 수 있지만 메타몽마다 잘하는 변신과 잘 못하는 변신이 있다고 한다.', '0.3m', '4kg', '노말', 48, 48, 48, 48, 48, 48, 132, null, false),
 (349, 117, 1, '이브이', '진화포켓몬', '이브이만 매우 불안정한 유전자를 갖고 있는 이유는 아직 해명되지 않았다.', '0.3m', '6.5kg', '노말', 55, 55, 50, 45, 65, 55, 133, null, false),
 (350, 117, 2, '샤미드', '거품뿜기포켓몬', '아름다운 물가가 주요 서식지다. 외적에게 습격당할 상황이 되면 물로 뛰어들어 모습을 감춘다.', '1m', '29kg', '물', 130, 65, 60, 110, 95, 65, 134, null, true),
 (352, 118, 1, '쥬피썬더', '번개포켓몬', '폐 안에 전기를 만드는 기관이 있다. 날숨에 섞여 탁탁하는 전기 소리가 들린다.', '0.8m', '24.5kg', '전기', 65, 65, 60, 110, 95, 130, 135, null, true),
 (355, 119, 1, '부스터', '불꽃포켓몬', '크게 공기를 들이쉬는 것은 공격 신호다. 1700도의 불꽃이 엄습해 온다.', '0.9m', '25kg', '불꽃', 65, 130, 60, 95, 110, 65, 136, null, true),
 (358, 120, 1, '암나이트', '소용돌이포켓몬', '고대의 바다에 살았던 포켓몬. 아케오스의 먹이였던 것으로 추정되며 잇자국이 있는 화석이 발견된다.', '0.4m', '7.5kg', '바위/물', 35, 40, 100, 90, 55, 35, 138, null, false),
 (359, 120, 2, '암스타', '소용돌이포켓몬', '무거운 껍질 때문에 멸종했다고 추정되는 고대 포켓몬. 대포무노의 먼 선조인 듯하다.', '1m', '35kg', '바위/물', 70, 60, 125, 115, 70, 55, 139, 40, false),
 (361, 121, 1, '투구', '껍질포켓몬', '3억 년 전에 번성했던 포켓몬. 어느 지방에서는 지금도 드물게 살아 있는 모습을 볼 수 있다고 한다.', '0.5m', '11.5kg', '바위/물', 30, 80, 90, 55, 45, 55, 140, null, false),
 (362, 121, 2, '투구푸스', '껍질포켓몬', '육지에서도 활동할 수 있도록 신체가 변화하기 시작했지만 때가 늦어서 멸종해 버렸다.', '1.3m', '40.5kg', '바위/물', 60, 115, 105, 65, 70, 80, 141, 40, false),
 (364, 122, 1, '프테라', '화석포켓몬', '호박에 남겨진 유전자로 복원시켰다. 예상 밖으로 흉포하여 희생자도 발생했다.', '1.8m', '59kg', '바위/비행', 80, 105, 65, 60, 75, 130, 142, null, false),
 (367, 123, 1, '꼬리선', '망보기포켓몬', '잠잘 때는 교대로 망을 본다. 위험을 탐지하면 동료를 깨운다. 무리에서 떨어지면 무서워서 자지 못한다.', '0.8m', '6kg', '노말', 35, 46, 34, 35, 45, 20, 161, null, false),
 (368, 123, 2, '다꼬리', '긴몸통포켓몬', '적에게 습격당해도 좁은 틈으로 쑥 들어가서 도망갈 수 있다. 팔다리는 짧지만 매우 날쌔다.', '1.8m', '32.5kg', '노말', 85, 76, 64, 45, 55, 90, 162, 15, false),
 (370, 124, 1, '레디바', '별다섯포켓몬', '추위에 매우 약한 포켓몬. 온난한 알로라에서는 매우 생기가 넘치는 모습을 볼 수 있다.', '1m', '10.8kg', '벌레/비행', 40, 20, 30, 40, 80, 55, 165, null, false),
 (371, 124, 2, '레디안', '별다섯포켓몬', '등의 모양은 밤하늘의 별과 연관이 있다고 전해지지만 자세한 것은 아직 알려지지 않았다.', '1.4m', '35.6kg', '벌레/비행', 55, 35, 50, 55, 110, 85, 166, 18, false),
 (373, 125, 1, '페이검', '실뿜기포켓몬', '실을 내뿜어 만든 둥지는 제법 튼튼하다. 10kg의 바위를 올려도 끄떡없다.', '0.5m', '8.5kg', '벌레/독', 40, 60, 40, 40, 40, 30, 167, null, false),
 (374, 125, 2, '아리아도스', '롱다리포켓몬', '밤마다 먹이를 찾아 떠돈다. 발견한 먹이에 실을 내뿜어 움직이지 못하게 하고 이빨로 갉아먹는다.', '1.1m', '33.5kg', '벌레/독', 70, 90, 70, 60, 70, 40, 168, 22, false),
 (376, 126, 1, '초라기', '아귀포켓몬', '2개의 촉수가 어렴풋이 빛나 먹이를 불러들인다. 밤낚시에 편리한 포켓몬이다.', '0.5m', '12kg', '물/전기', 75, 38, 38, 56, 56, 67, 170, null, false),
 (377, 126, 2, '랜턴', '라이트포켓몬', '촉수에 사는 박테리아가 랜턴의 체액을 빨아들일 때 강한 발광 현상이 일어난다.', '1.2m', '22.5kg', '물/전기', 125, 58, 58, 76, 76, 67, 171, 27, false),
 (379, 127, 1, '아르코', '꽃포켓몬', '태양의 빛을 잔뜩 받으면 몸의 잎사귀가 빙글빙글 돌기 시작한다. 아르코의 춤은 남쪽 나라의 명물이다.', '0.4m', '5.8kg', '풀', 75, 80, 95, 90, 100, 50, 182, null, true),
 (382, 128, 1, '왕구리', '개구리포켓몬', '고함치는 듯한 울음소리임에도 어느 작곡가는 영향을 받아 아름다운 발라드를 만들었다.', '1.1m', '33.9kg', '물', 90, 75, 75, 90, 100, 70, 186, null, false),
 (385, 129, 1, '통통코', '솜풀포켓몬', '바람을 타고 둥둥 떠다니는 포켓몬이다. 강풍의 기척을 느끼면 동료끼리 잎사귀를 휘감아 날아가지 않도록 준비한다.', '0.4m', '0.5kg', '풀/비행', 35, 35, 40, 35, 55, 50, 187, null, false),
 (386, 129, 2, '두코', '솜풀포켓몬', '기온이 18도를 넘으면 꽃이 핀다. 온도에 따라 꽃이 피는 모습이 바뀌어서 온도계 대신 쓰기도 한다.', '0.6m', '1kg', '풀/비행', 55, 45, 50, 45, 65, 80, 188, 18, false),
 (387, 129, 3, '솜솜코', '솜풀포켓몬', '따뜻한 남풍을 타고 바다를 건너 외국까지 날아가는 포켓몬이다. 차가운 공기에 닿으면 땅에 내려온다.', '0.8m', '3kg', '풀/비행', 75, 55, 70, 55, 95, 110, 189, 27, false),
 (388, 130, 1, '에이팜', '긴꼬리포켓몬', '꼬리로 이것저것 하는 사이에 손이 둔해지고 말았다. 높은 나무 위에 둥지를 만든다.', '0.8m', '11.5kg', '노말', 55, 70, 55, 40, 55, 85, 190, null, false),
 (389, 130, 2, '겟핸보숭', '긴꼬리포켓몬', '머물기 좋은 나무를 두고 내던숭이 그룹과 영역 다툼을 하고 있다. 승률은 비슷하다.', '1.2m', '20.3kg', '노말', 75, 100, 66, 60, 66, 115, 424, 25, false),
 (391, 131, 1, '해너츠', '씨앗포켓몬', '몸에 모은 영양을 진화할 때까지 간직하기 위해 거의 움직이려 하지 않는다. 아무것도 먹지 않고 아침 이슬만 마시고 있다.', '0.3m', '1.8kg', '풀', 30, 30, 30, 30, 30, 30, 191, null, false),
 (392, 131, 2, '해루미', '태양포켓몬', '태양 에너지에서 영양을 만들어낸다. 기온이 높은 낮에는 활발하게 움직이고 태양이 지면 뚝 하니 움직이지 않게 된다.', '0.8m', '8.5kg', '풀', 75, 75, 55, 105, 85, 30, 192, null, true),
 (394, 132, 1, '왕자리', '얇은날개포켓몬', '눈알을 움직이지 않고 360도를 볼 수 있다. 급브레이크나 방향 전환이 특기다. 노린 먹이를 빠르게 몰아넣는다.', '1.2m', '38kg', '벌레/비행', 65, 65, 45, 75, 45, 95, 193, null, false),
 (395, 132, 2, '메가자리', '깨비잠자리포켓몬', '고속으로 날아서 스친 상대의 목을 한순간에 물어뜯는 싸움법을 선호한다.', '1.9m', '51.5kg', '벌레/비행', 86, 76, 86, 116, 56, 95, 469, 25, false),
 (397, 133, 1, '우파', '수어포켓몬', '평상시엔 물속에서 지내지만 먹이를 찾거나 할 때는 가끔 지상에 나온다. 땅에서는 독 점액으로 몸을 둘러싼다.', '0.4m', '8.5kg', '물/땅', 55, 45, 45, 25, 25, 15, 194, null, false),
 (398, 133, 2, '누오', '수어포켓몬', '물속에서 입을 열고 우연히 먹이가 뛰어들기를 그저 기다리고 있다. 움직이지 않기에 별로 배가 안 고프다.', '1.4m', '75kg', '물/땅', 95, 85, 85, 65, 65, 35, 195, 20, false),
 (400, 134, 1, '에브이', '태양포켓몬', '원래는 아무런 능력도 없었지만 몸을 지키기 위해 예지 능력에 눈뜨게 됐다고 한다.', '0.9m', '26.5kg', '에스퍼', 65, 65, 60, 130, 95, 110, 196, null, false),
 (403, 135, 1, '블래키', '달빛포켓몬', '야행성 포켓몬. 큰 눈동자는 칠흑 같은 어둠에서도 먹이의 모습을 정확하게 찾아낸다.', '1m', '27kg', '악', 95, 65, 110, 60, 130, 65, 197, null, false),
 (406, 136, 1, '니로우', '어둠포켓몬', '반짝이는 것을 매우 좋아한다. 보물을 찾아 보석을 모으는 한바이트 둥지에 몰래 들어가기도 한다.', '0.5m', '2.1kg', '악/비행', 60, 85, 42, 85, 42, 91, 198, null, false),
 (407, 136, 2, '돈크로우', '큰형님포켓몬', '실패하거나 배신한 부하는 절대 용서하지 않는다. 무리의 질서를 지키기 위해 어쩔 수 없다.', '0.9m', '27.3kg', '악/비행', 100, 125, 52, 105, 52, 71, 430, null, true),
 (409, 137, 1, '야도킹', '임금포켓몬', '머릿속으로는 항상 세계를 바꿀 정도의 아이디어가 넘쳐 흐르지만 번뜩이는 순간 잊어버린다.', '2m', '79.5kg', '물/에스퍼', 95, 75, 80, 100, 110, 30, 199, null, true),
 (412, 138, 1, '무우마', '야명포켓몬', '놀라게 하는 것이 삶의 낙이다. 목의 빨간 구슬에 귀를 대면 안에서 비명이 들려온다.', '0.7m', '1kg', '고스트', 60, 60, 60, 85, 85, 85, 200, null, false),
 (413, 138, 2, '무우마직', '매지컬포켓몬', '닥치는 대로 재앙과 저주를 내려 두려움의 대상이었다. 변덕을 부려 사람을 돕는 주문도 사용하기도 한다.', '0.9m', '4.4kg', '고스트', 60, 60, 60, 105, 105, 105, 429, null, true),
 (415, 139, 1, '안농', '심볼포켓몬', '고대 문자를 닮은 모습의 포켓몬이다. 먼저 생겨난 것은 문자인가 안농인가. 연구 중이지만 아직도 수수께끼다.', '0.5m', '5kg', '에스퍼', 48, 72, 48, 72, 48, 48, 201, null, false),
 (418, 140, 1, '키링키', '긴목포켓몬', '꼬리의 머리에도 작은 뇌가 있다. 냄새나 소리에 반응하여 공격하기 때문에 뒤에서 접근하면 느닷없이 물린다.', '1.5m', '41.5kg', '노말/에스퍼', 70, 80, 65, 90, 65, 85, 203, null, false),
 (421, 141, 1, '피콘', '도롱이벌레포켓몬', '나무에 매달려 가만히 먹이인 벌레포켓몬이 올 때를 기다린다. 알로라에서 좋아하는 건 에블리다.', '0.6m', '7.2kg', '벌레', 50, 65, 90, 35, 35, 15, 204, null, false),
 (422, 141, 2, '쏘콘', '도롱이벌레포켓몬', '무엇이든 다가오기만 하면 강철 껍질의 파편을 쏘며 공격한다. 의지가 없는 조건 반사다.', '1.2m', '125.8kg', '벌레/강철', 75, 90, 140, 60, 60, 40, 205, 31, false),
 (424, 142, 1, '노고치', '땅뱀포켓몬', '지면을 파고 다니며 이동한다. 디그다와 서로의 터널을 사이좋게 같이 사용하고 있다.', '1.5m', '14kg', '노말', 100, 70, 70, 65, 65, 45, 206, null, false),
 (427, 143, 1, '글라이거', '날전갈포켓몬', '소리 내지 않고 미끄러지듯 활공한다. 양손의 커다란 손톱과 발의 발톱으로 먹이의 얼굴에 달라붙어 독침을 찌른다.', '1.1m', '64.8kg', '땅/비행', 65, 75, 105, 35, 65, 85, 207, null, false),
 (428, 143, 2, '글라이온', '송곳니전갈포켓몬', '꼬리로 나뭇가지에 매달려 먹이를 관찰한다. 틈을 봐서 상공에서 덮친다.', '2m', '42.5kg', '땅/비행', 75, 95, 125, 45, 75, 95, 472, 25, false),
 (430, 144, 1, '침바루', '풍선포켓몬', '들이마신 물의 힘을 이용하여 전신의 독침을 일제히 쏘아댄다. 헤엄치는 것이 조금 서툰 포켓몬이다.', '0.5m', '3.9kg', '물/독', 65, 95, 85, 55, 55, 85, 211, null, false),
 (433, 145, 1, '단단지', '발효포켓몬', '바위 밑에서 껍질 안에 비축해둔 나무열매를 먹으면서 몸을 숨기고 있다. 나무열매는 체액과 섞여 주스가 된다.', '0.6m', '20.5kg', '벌레/바위', 20, 10, 230, 10, 230, 5, 213, null, false),
 (436, 146, 1, '헤라크로스', '외뿔포켓몬', '두꺼운 뿔이 자랑거리다. 알로라에서는 투구뿌논이 최대 라이벌로 자주 싸움을 한다.', '1.5m', '54kg', '벌레/격투', 80, 125, 75, 40, 95, 85, 214, null, false),
 (439, 147, 1, '포푸니', '갈고리손톱포켓몬', '팀플레이로 새포켓몬의 둥지에서 알을 훔쳐 내지만, 누가 먹을까로 싸움이 난다.', '0.9m', '28kg', '악/얼음', 55, 95, 55, 35, 75, 115, 215, null, false),
 (440, 147, 2, '포푸니라', '갈고리손톱포켓몬', '1마리가 모래두지에게 다리를 걸어 뒤집으면 다른 1마리가 날카로운 발톱으로 처리한다.', '1.1m', '34kg', '악/얼음', 70, 120, 65, 45, 85, 125, 461, 25, false),
 (442, 148, 1, '깜지곰', '아기곰포켓몬', '꿀이 밴 손바닥을 핥고 있다. 깜지곰의 꿀은 과일과 독침붕이 모은 꽃가루가 혼합되어 만들어진다.', '0.6m', '8.8kg', '노말', 60, 80, 50, 50, 50, 40, 216, null, false),
 (443, 148, 2, '링곰', '동면포켓몬', '숲 속에는 링곰이 먹이를 수집하는 큰 나무나 시냇가가 여기저기에 있다고 한다. 매일 먹이를 모으며 숲을 걷는다.', '1.8m', '125.8kg', '노말', 90, 130, 75, 75, 75, 55, 217, 30, false),
 (445, 149, 1, '마그마그', '용암포켓몬', '몸 안에는 작열하는 용암이 소용돌이치지만 식으면 굳어지고 부서져서 몸이 작아진다.', '0.7m', '35kg', '불꽃', 40, 40, 40, 70, 40, 20, 218, null, false),
 (446, 149, 2, '마그카르고', '용암포켓몬', '껍질은 피부가 식어 굳어진 것이다. 만지기만 해도 산산이 부서져 버린다. 마그마에 들어가면 원래 크기로 돌아온다.', '0.8m', '55kg', '불꽃/바위', 60, 50, 120, 90, 80, 30, 219, 38, false),
 (448, 150, 1, '코산호', '산호포켓몬', '알로라에 사는 코산호는 핑크가 매우 선명하고 짙다. 영양이 풍부한 바다 덕분이다.', '0.6m', '5kg', '물/바위', 65, 55, 95, 65, 95, 35, 222, null, false),
 (451, 151, 1, '총어', '분사포켓몬', '만타인에 달라붙어 남긴 음식을 먹고 산다. 만타인이 습격당하면 함께 싸운다.', '0.6m', '12kg', '물', 35, 65, 35, 65, 35, 65, 223, null, false),
 (452, 151, 2, '대포무노', '분사포켓몬', '도망칠 때 내뿜는 먹물은 특별하다. 후각을 둔하게 하는 성분으로 후각이 발달한 포켓몬도 말려든다.', '0.9m', '28.5kg', '물', 75, 105, 75, 105, 75, 45, 224, 25, false),
 (454, 152, 1, '딜리버드', '배달포켓몬', '조난 당한 사람에게 자신의 먹이를 나눠준다. 잡식이어서 벌레포켓몬을 건네주기도 한다.', '0.9m', '16kg', '얼음/비행', 45, 55, 45, 65, 45, 75, 225, null, false),
 (457, 153, 1, '무장조', '갑옷새포켓몬', '빠진 날개를 가공해서 만드는 식칼은 일류 요리사도 인정할 정도로 날카롭다.', '1.7m', '50.5kg', '강철/비행', 65, 80, 140, 40, 70, 70, 227, null, false),
 (460, 154, 1, '코코리', '긴코포켓몬', '강 근처에 수직으로 구멍을 파고 산다. 사는 곳 가까이에 코의 표시를 남겨 자신의 장소라고 동료에게 알리고 있다.', '0.5m', '33.5kg', '땅', 90, 60, 60, 40, 40, 40, 231, null, false),
 (461, 154, 2, '코리갑', '갑옷포켓몬', '몸을 둥글게 말아 고속 회전하며 상대에게 돌진하는 공격이 특기다. 구르기 시작하면 어지간해서는 멈출 수 없다.', '1.1m', '120kg', '땅', 90, 120, 120, 60, 60, 50, 232, 25, false),
 (463, 155, 1, '노라키', '큰뿔포켓몬', '멋지게 생긴 뿔은 미술품으로 비싸게 팔리기 때문에 멸종 직전까지 남획됐었던 포켓몬이다.', '1.4m', '71.2kg', '노말', 73, 95, 62, 85, 65, 85, 234, null, false),
 (466, 156, 1, '루브도', '그림장이포켓몬', '꼬리 끝에서 나오는 체액은 루브도의 감정에 따라 색조가 변화한다.', '1.2m', '58kg', '노말', 55, 20, 35, 20, 45, 75, 235, null, false),
 (469, 157, 1, '카포에라', '물구나무포켓몬', '고속 회전하며 날리는 킥은 공격과 방어를 겸비한 훌륭한 기술이다. 걷는 것보다 회전하는 편이 빠르다.', '1.4m', '48kg', '격투', 50, 95, 95, 35, 110, 70, 237, null, false),
 (472, 158, 1, '뽀뽀라', '뽀뽀포켓몬', '무언가를 확인할 때는 손보다 입술을 먼저 갖다 댄다. 바지런히 핥아 더러운 것을 닦는다.', '0.4m', '6kg', '얼음/에스퍼', 45, 30, 15, 85, 65, 65, 238, null, false),
 (473, 158, 2, '루주라', '인간형태포켓몬', '독특한 리듬으로 허리를 흔든다. 알로라에 사는 루주라는 그 동작이 실로 훌륭하다.', '1.4m', '40.6kg', '얼음/에스퍼', 65, 50, 35, 115, 95, 95, 124, 30, false),
 (475, 159, 1, '에레키드', '전류포켓몬', '번개 소리를 들으면 기분이 좋아진다. 우울해질 때를 대비해서 녹음해 두면 편리하다.', '0.6m', '23.5kg', '전기', 45, 63, 37, 65, 55, 95, 239, null, false),
 (476, 159, 2, '에레브', '전기포켓몬', '온몸이 전기로 둘러싸여 있다. 팔을 빙빙 돌려 전기를 충전 후 펀치를 날린다.', '1.1m', '30kg', '전기', 65, 83, 57, 95, 85, 105, 125, 30, false),
 (477, 159, 3, '에레키블', '뇌전포켓몬', '전기를 내뿜는 꼬리를 잡고 주먹에 전기를 머금으면 있는 힘껏 때린다.', '1.8m', '138.6kg', '전기', 75, 123, 67, 95, 85, 95, 466, 40, false),
 (478, 160, 1, '마그비', '불씨포켓몬', '코에서 불꽃이 줄줄 흐른다면 감기에 걸린 것이다. 마그마에서 쉬게 해 주자.', '0.7m', '21.4kg', '불꽃', 45, 75, 37, 70, 55, 83, 240, null, false),
 (479, 160, 2, '마그마', '불뿜기포켓몬', '온몸이 불에 타고 있어서 숨을 쉬기만 해도 뜨겁다. 재채기와 동시에 불꽃을 뿜어낸다.', '1.3m', '44.5kg', '불꽃', 65, 95, 57, 100, 85, 93, 126, 30, false),
 (480, 160, 3, '마그마번', '폭염포켓몬', '지금도 금속을 가공할 때 마그마번의 불꽃에 의존하는 공장이 적지 않다.', '1.6m', '68kg', '불꽃', 75, 95, 67, 125, 95, 83, 467, 40, false),
 (481, 161, 1, '밀탱크', '젖소포켓몬', '하루에 20리터의 젖을 짠다. 목초의 질이 좋은 산지일수록 밀크는 진해서 맛있다.', '1.2m', '75.5kg', '노말', 95, 80, 105, 40, 70, 100, 241, null, false),
 (484, 162, 1, '라이코', '우뢰포켓몬', '번개의 스피드가 깃들어 있는 포켓몬이다. 그 울음소리는 번개가 내리쳤을 때처럼 공기를 떨리게 하며 대지를 흔든다.', '1.9m', '178kg', '전기', 90, 85, 75, 115, 100, 115, 243, null, false),
 (487, 163, 1, '앤테이', '화산포켓몬', '마그마의 정열이 깃들어 있는 포켓몬이다. 화산 분화 속에서 태어났다고 여겨지며 모든 것을 태워버리는 불꽃을 뿜어 올린다.', '2.1m', '198kg', '불꽃', 115, 115, 85, 90, 75, 100, 244, null, false),
 (490, 164, 1, '스이쿤', '오로라포켓몬', '솟아나는 물의 부드러움이 깃들어 있는 포켓몬이다. 흐르는 듯한 몸놀림으로 대지를 달려 탁해진 물을 맑게 하는 힘을 지녔다.', '2m', '187kg', '물', 100, 75, 115, 90, 115, 85, 245, null, false),
 (493, 165, 1, '루기아', '잠수포켓몬', '가벼운 날갯짓만으로도 민가를 날려버릴 만한 파괴력을 지니고 있어서 해저에서 사람들 몰래 살게 됐다.', '5.2m', '216kg', '에스퍼/비행', 106, 90, 130, 90, 154, 110, 249, null, false),
 (496, 166, 1, '칠색조', '무지개색포켓몬', '빛이 닿는 각도에 따라 일곱 빛깔로 반짝이는 깃털은 행복을 가져다준다고 한다. 무지개 끝에 산다고 전해진다.', '3.8m', '199kg', '불꽃/비행', 106, 130, 90, 110, 154, 90, 250, null, false),
 (499, 167, 1, '나무지기', '숲도마뱀포켓몬', '다리 뒤의 작은 가시를 박아 수직인 벽을 올라갈 수 있다. 굵은 꼬리로 힘껏 쳐서 공격한다.', '0.5m', '5kg', '풀', 40, 45, 35, 65, 55, 70, 252, null, false),
 (500, 167, 2, '나무돌이', '숲도마뱀포켓몬', '몸에서 난 잎사귀는 숲 속에서 적으로부터 몸을 숨길 때 편리하다. 밀림에 사는 나무 타기의 명수다.', '0.9m', '21.6kg', '풀', 50, 65, 45, 85, 65, 95, 253, 16, false),
 (501, 167, 3, '나무킹', '밀림포켓몬', '몸에 난 잎사귀는 예리한 칼과 같다. 빠른 몸놀림으로 나뭇가지를 뛰어다니며 적의 머리 위나 배후에서 덮친다.', '1.7m', '52.2kg', '풀', 70, 85, 65, 105, 85, 120, 254, 36, false),
 (502, 168, 1, '아차모', '풋내기포켓몬', '트레이너에게 바짝 붙어 아장아장 걷는다. 입에서 날리는 불꽃은 섭씨 1000도다. 상대를 새까맣게 태우는 작열하는 불덩이다.', '0.4m', '2.5kg', '불꽃', 45, 60, 40, 70, 50, 45, 255, null, false),
 (503, 168, 2, '영치코', '꼬마닭포켓몬', '산과 들을 뛰어다니며 하반신을 단련한다. 스피드와 파워를 겸비한 다리는 1초에 10번 킥을 날린다.', '0.9m', '19.5kg', '불꽃/격투', 60, 85, 60, 85, 60, 55, 256, 16, false),
 (504, 168, 3, '번치코', '맹화포켓몬', '싸우게 되면 손목에서 작열하는 불꽃을 뿜어 올려 용감히 덤벼든다. 상대가 버거울수록 강렬히 불타오른다.', '1.9m', '52kg', '불꽃/격투', 80, 120, 70, 110, 70, 80, 257, 36, false),
 (505, 169, 1, '물짱이', '늪물고기포켓몬', '머리의 지느러미는 매우 민감한 레이더다. 물이나 공기의 움직임을 통해 눈을 쓰지 않고 주변의 상황을 알아낼 수 있다.', '0.4m', '7.6kg', '물', 50, 70, 50, 50, 50, 40, 258, null, false),
 (506, 169, 2, '늪짱이', '늪물고기포켓몬', '지상에서도 생활할 수 있도록 몸의 표면을 얇은 점막이 둘러싸고 있다. 썰물이 된 해안에서 흙놀이를 한다.', '0.7m', '28kg', '물/땅', 70, 85, 70, 60, 70, 50, 259, 16, false),
 (507, 169, 3, '대짱이', '늪물고기포켓몬', '무게 1톤 이상인 바위 덩어리를 가볍게 잡아당기는 파워를 지닌 포켓몬이다. 탁해진 물속도 들여다볼 수 있는 시력을 지녔다.', '1.5m', '81.9kg', '물/땅', 100, 110, 90, 85, 90, 60, 260, 36, false),
 (508, 170, 1, '지그제구리', '앙증너구리포켓몬', '항상 이쪽저쪽 지그재그로 걷는 것은 호기심이 매우 강해서 눈에 비친 여러 가지 것들에 흥미를 느끼기 때문이다.', '0.4m', '17.5kg', '노말', 38, 30, 41, 30, 41, 60, 263, null, false),
 (509, 170, 2, '직구리', '돌진포켓몬', '똑바로 힘껏 달리며 장애물이 있을 때는 직각으로 꺾어서 피한다. 완만하게 굽은 길은 달리는 데 매우 서툴다.', '0.5m', '32.5kg', '노말', 78, 70, 61, 50, 61, 100, 264, 20, false),
 (511, 171, 1, '개무소', '애벌레포켓몬', '엉덩이의 가시로 나무의 껍질을 벗기고 배어 나온 수액을 식량으로 삼는다. 흡반이 달린 다리는 유리에서도 미끄러지지 않는다.', '0.3m', '3.6kg', '벌레', 45, 45, 35, 20, 30, 20, 265, null, false),
 (512, 171, 2, '실쿤', '번데기포켓몬', '떨어지지 않도록 실을 가지에 휘감아서 몸을 지탱하며 진화를 기다리고 있다. 작은 구멍을 통해 밖의 상황을 살핀다.', '0.6m', '10kg', '벌레', 50, 35, 55, 25, 25, 15, 266, 7, false),
 (513, 171, 3, '뷰티플라이', '나비포켓몬', '달콤한 꽃가루를 매우 좋아하는 포켓몬이다. 꽃이 핀 화분을 창가에 두면 꽃가루를 모으려고 반드시 날아온다.', '1m', '28.4kg', '벌레/비행', 60, 70, 50, 100, 50, 65, 267, 10, false),
 (514, 172, 1, '카스쿤', '번데기포켓몬', '카스쿤의 몸은 입에서 나온 가는 실이 몸을 둘러싸 딱딱해진 것이다. 고치 안에서 진화의 준비를 하고 있다.', '0.7m', '11.5kg', '벌레', 50, 35, 55, 25, 25, 15, 268, null, false),
 (515, 172, 2, '독케일', '독나방포켓몬', '불빛에 이끌리는 습성을 지녔다. 거리의 불빛에 유인된 독케일 무리가 가로수의 잎을 어지르며 먹어버린다.', '1.2m', '31.6kg', '벌레/독', 60, 50, 70, 50, 90, 65, 269, 10, false),
 (517, 173, 1, '연꽃몬', '개구리밥포켓몬', '연못이나 호수의 수면에 떠서 산다. 잎사귀가 마르면 약해지지만 깨끗한 물을 찾아 가끔 육지로 이동한다.', '0.5m', '2.6kg', '물/풀', 40, 30, 30, 40, 50, 30, 270, null, false),
 (518, 173, 2, '로토스', '명랑함포켓몬', '해 질 무렵이 되면 활동하는 야행성이다. 낚시꾼을 발견하면 물속에서 줄을 당겨 방해하고선 기뻐한다.', '1.2m', '32.5kg', '물/풀', 60, 50, 50, 60, 70, 50, 271, 14, false),
 (519, 173, 3, '로파파', '행복하기포켓몬', '경쾌한 음악을 들으면 춤춘다. 하이킹하는 아이들의 합창에 이끌려 모습을 나타낸다고 전해진다.', '1.5m', '55kg', '물/풀', 80, 70, 70, 90, 100, 70, 272, null, true),
 (520, 174, 1, '도토링', '도토리포켓몬', '머리의 정수리를 나뭇가지에 붙이고 매달려 수분을 빨아들이고 있다. 물을 마실수록 몸이 반들반들 빛난다.', '0.5m', '4kg', '풀', 40, 40, 50, 30, 30, 30, 273, null, false),
 (521, 174, 2, '잎새코', '꾀부리기포켓몬', '울창하게 우거진 숲에 사는 포켓몬이다. 가끔 숲을 나와 사람들을 놀라게 한다. 긴 코가 잡히는 걸 매우 싫어한다.', '1m', '28kg', '풀/악', 70, 70, 40, 60, 40, 60, 274, 14, false),
 (522, 174, 3, '다탱구', '부정하기포켓몬', '수령 1000년을 넘은 큰 나무 꼭대기에 산다고 전해지는 불가사의한 포켓몬이다. 잎사귀 부채로 강풍을 일으킨다.', '1.3m', '59.6kg', '풀/악', 90, 100, 60, 90, 60, 80, 275, null, true),
 (523, 175, 1, '갈모매', '괭이갈매기포켓몬', '가늘고 긴 날개다. 상승 기류를 타고 글라이더처럼 넓은 하늘로 높이 떠오른다.', '0.6m', '9.5kg', '물/비행', 40, 30, 30, 55, 30, 85, 278, null, false),
 (524, 175, 2, '패리퍼', '물새포켓몬', '부풀린 부리 안에 작은 포켓몬을 넣어 운반한다. 어디로 데려가는지는 알 수 없다.', '1.2m', '28kg', '물/비행', 60, 50, 100, 95, 70, 65, 279, 25, false),
 (526, 176, 1, '비구술', '소금쟁이포켓몬', '위기를 맞으면 돌기에서 달콤한 액체가 나온다. 이것을 모은 시럽을 빵에 바르면 맛있다.', '0.5m', '1.7kg', '벌레/물', 40, 30, 32, 50, 52, 65, 283, null, false),
 (527, 176, 2, '비나방', '안구포켓몬', '눈알 모양으로 적을 위협한다. 그래도 안 되면 4장의 날개를 사용해 재빠르게 도망친다.', '0.8m', '3.6kg', '벌레/비행', 70, 60, 62, 100, 82, 80, 284, 22, false),
 (529, 177, 1, '버섯꼬', '버섯포켓몬', '깊은 숲의 축축한 땅에 서식한다. 낙엽 밑에서 꼼짝하지 않고 있을 때가 많다. 낙엽이 쌓여 만들어진 부엽토를 먹는다.', '0.4m', '4.5kg', '풀', 60, 40, 60, 40, 60, 35, 285, null, false),
 (530, 177, 2, '버섯모', '버섯포켓몬', '경쾌한 풋워크로 적에게 다가가 늘었다 줄었다 하는 팔로 펀치를 날린다. 복서가 무색할 만할 테크닉의 소유자다.', '1.2m', '39.2kg', '풀/격투', 60, 130, 80, 60, 60, 70, 286, 23, false),
 (532, 178, 1, '게을로', '게으름뱅이포켓몬', '하루에 20시간 이상 엎드려 누워 있다. 거의 몸을 움직이지 않아서 잎사귀를 3장 먹으면 하루 식사가 끝난다.', '0.8m', '24kg', '노말', 60, 60, 60, 35, 35, 30, 287, null, false),
 (533, 178, 2, '발바로', '성난원숭이포켓몬', '항상 날뛰고 싶어서 근질근질해 한다. 1분도 앉아 있지를 못한다. 움직이지 않으면 스트레스가 쌓인다.', '1.4m', '46.5kg', '노말', 80, 80, 80, 55, 55, 90, 288, 18, false),
 (534, 178, 3, '게을킹', '나태함포켓몬', '온종일 엎드려 누워 지내는 포켓몬이다. 손이 닿는 장소에 난 풀을 먹으며 풀이 없어지면 마지못해 장소를 옮긴다.', '2m', '130.5kg', '노말', 150, 160, 100, 95, 65, 100, 289, 36, false),
 (535, 179, 1, '토중몬', '신참포켓몬', '몇 년을 캄캄한 땅속에서 산다. 나무의 뿌리에서 영양을 흡수하며 가만히 움직이지 않고 진화의 때를 기다리고 있다.', '0.5m', '5.5kg', '벌레/땅', 31, 45, 90, 30, 30, 40, 290, null, false),
 (536, 179, 2, '아이스크', '시노비포켓몬', '고속으로 움직여서 모습이 보이지 않는다. 울음소리만 들려서 오랫동안 투명한 포켓몬이라고 여겨져 왔다.', '0.8m', '12kg', '벌레/비행', 61, 90, 45, 50, 50, 160, 291, 20, false),
 (538, 180, 1, '껍질몬', '허물포켓몬', '단단한 몸은 꿈쩍도 하지 않는다. 등을 통해 몸의 구멍을 들여다보면 혼이 빨려 들어간다고 믿어지고 있다.', '0.8m', '1.2kg', '벌레/고스트', 1, 90, 45, 30, 30, 40, 292, null, false),
 (541, 181, 1, '소곤룡', '속삭임포켓몬', '평소에는 주의를 기울여야 들릴 만큼 작은 목소리지만 위험을 감지하면 두통을 일으킬 만큼 큰 소리로 울어댄다.', '0.6m', '16.3kg', '노말', 64, 51, 23, 51, 23, 28, 293, null, false),
 (542, 181, 2, '노공룡', '큰목소리포켓몬', '나무로 만든 집을 산산조각 내 날려버릴 만큼 큰 소리를 내어 상대를 혼내준다. 둥근 귀가 스피커 역할을 한다.', '1m', '40.5kg', '노말', 84, 71, 43, 71, 43, 48, 294, 20, false),
 (543, 181, 3, '폭음룡', '소음포켓몬', '큰 소리의 진동으로 지진을 일으킨다. 몸에 난 구멍으로 공기를 세차게 빨아들이기 시작하면 큰 소리를 낼 조짐이다.', '1.5m', '84kg', '노말', 104, 91, 63, 91, 73, 68, 295, 40, false),
 (544, 182, 1, '마크탕', '근성포켓몬', '나무줄기에 손바닥 치기를 하며 단련한다. 나시에게 손바닥 치기를 해서 내던져지기도 한다.', '1m', '86.4kg', '격투', 72, 60, 30, 20, 30, 25, 296, null, false),
 (545, 182, 2, '하리뭉', '손바닥치기포켓몬', '힘겨루기를 좋아하지만, 선한 성품도 겸비하여 대결 상대를 치하하는 등 예의를 중시한다.', '2.3m', '253.8kg', '격투', 144, 120, 60, 40, 60, 50, 297, 24, false),
 (547, 183, 1, '루리리', '물방울포켓몬', '올가미를 쓰듯 꼬리를 휘휘 돌려 던질 때의 힘으로 날아간다. 최고 10m를 날아간 기록이 있다.', '0.2m', '2kg', '노말/페어리', 50, 20, 40, 20, 40, 20, 298, null, false),
 (548, 183, 2, '마릴', '물쥐포켓몬', '기름이 가득한 꼬리는 튜브 대용이다. 수면에 꼬리만 떠 있을 때는 잠수하여 물풀을 먹고 있다는 표시다.', '0.4m', '8.5kg', '물/페어리', 70, 20, 50, 20, 50, 40, 183, 25, false),
 (549, 183, 3, '마릴리', '물토끼포켓몬', '긴 귀는 마릴리의 중요한 센서다. 귀를 기울이면 물살이 격한 강에서도 그곳에 있는 먹이의 종류를 안다.', '0.8m', '28.5kg', '물/페어리', 100, 50, 80, 60, 80, 50, 184, 26, false),
 (550, 184, 1, '코코파스', '콤파스포켓몬', '1년에 1cm밖에 움직이지 않지만 위기에 처하면 회전하여 순식간에 땅속으로 파고든다.', '1m', '97kg', '바위', 30, 45, 135, 45, 90, 30, 299, null, false),
 (551, 184, 2, '대코파스', '콤파스포켓몬', '꼬마코파스라고 불리는 유닛을 조종하지만 가끔 미아가 되어 돌아오지 않는 경우도 있는 듯하다.', '1.4m', '340kg', '바위/강철', 60, 55, 145, 75, 150, 40, 476, null, true),
 (553, 185, 1, '에나비', '작은고양이포켓몬', '움직이는 것을 발견하면 푹 빠져서 뒤쫓아 가는 습성을 지닌 포켓몬이다. 자기 꼬리를 쫓다 현기증을 일으킨다.', '0.6m', '11kg', '노말', 50, 45, 45, 35, 35, 50, 300, null, false),
 (554, 185, 2, '델케티', '새침떼기포켓몬', '자기 방식대로 자유로운 삶을 즐긴다. 마음 내키는 대로 먹이를 먹고 잠을 자기 때문에 하루의 리듬이 제각각이다.', '1.1m', '32.6kg', '노말', 70, 65, 65, 55, 55, 90, 301, null, true),
 (556, 186, 1, '깜까미', '어둠포켓몬', '딱딱한 발톱으로 땅에 구멍을 파고 굵은 이빨로 보석을 북북 갉는다. 멜리시를 매우 좋아한다.', '0.5m', '11kg', '악/고스트', 50, 75, 75, 65, 65, 50, 302, null, false),
 (559, 187, 1, '입치트', '배반포켓몬', '약삭빠르고 무서운 포켓몬. 귀여운 행동으로 방심하게 한 후 느닷없이 큰 턱으로 통째로 삼켜 버린다.', '0.6m', '11.5kg', '강철/페어리', 50, 85, 85, 55, 55, 50, 303, null, false),
 (562, 188, 1, '요가랑', '명상포켓몬', '산속에서 요가 수행을 한다. 명상을 하고 있어도 집중력이 떨어지기 때문에 수행이 끝나지 않는다.', '0.6m', '11.2kg', '격투/에스퍼', 30, 40, 55, 40, 55, 60, 307, null, false),
 (563, 188, 2, '요가램', '명상포켓몬', '명상을 하면 몸의 에너지가 높아지고 여섯 번째 감각이 예리해진다고 한다. 산야와 일체화되어 기척을 지운다.', '1.3m', '31.5kg', '격투/에스퍼', 60, 60, 75, 60, 75, 80, 308, 37, false),
 (565, 189, 1, '썬더라이', '천둥번개포켓몬', '공기와 털의 마찰로 정전기가 발생한다. 썬더라이가 달리면 탁탁 소리가 난다.', '0.6m', '15.2kg', '전기', 40, 45, 40, 65, 40, 65, 309, null, false),
 (566, 189, 2, '썬더볼트', '방전포켓몬', '이상한 번개 구름 아래에는 썬더볼트가 있다. 번개와 같은 스피드로 달린다고 한다.', '1.5m', '40.2kg', '전기', 70, 75, 60, 105, 60, 105, 310, 26, false),
 (568, 190, 1, '플러시', '응원포켓몬', '항상 동료를 응원하고 있는 포켓몬이다. 동료가 힘을 내면 몸을 합선시켜 타다닥 불꽃 소리를 내며 기뻐한다.', '0.4m', '4.2kg', '전기', 60, 50, 40, 85, 75, 95, 311, null, false),
 (571, 191, 1, '마이농', '응원포켓몬', '자신보다 동료를 응원하는 것이 중요하다. 몸에서 나오는 전기를 합선시켜 화려한 불꽃을 내며 응원한다.', '0.4m', '4.2kg', '전기', 60, 40, 50, 75, 85, 95, 312, null, false),
 (574, 192, 1, '볼비트', '반딧불포켓몬', '날이 저물면 꼬리에서 빛을 내어 밝기나 점멸로 동료와 대화한다. 네오비트의 달콤한 향기에 유인된다.', '0.7m', '17.7kg', '벌레', 65, 73, 75, 47, 85, 85, 313, null, false),
 (577, 193, 1, '네오비트', '반딧불포켓몬', '달콤한 향기로 볼비트를 유인한다. 많이 모인 볼비트를 유도하여 밤하늘에 기하학적인 도형을 그린다.', '0.6m', '17.7kg', '벌레', 65, 47, 75, 73, 85, 85, 314, null, false),
 (580, 194, 1, '꼴깍몬', '밥통포켓몬', '몸 대부분이 위로 되어 있어 자신과 크기가 같은 것도 삼킨다. 특수한 위액으로 무엇이든 소화한다.', '0.4m', '10.3kg', '독', 70, 43, 53, 43, 53, 40, 316, null, false),
 (581, 194, 2, '꿀꺽몬', '독봉지포켓몬', '먹이를 발견하면 모공에서 맹독의 체액을 뿜어내어 끼얹는다. 약해지면 커다란 입으로 한입에 먹는다.', '1.7m', '80kg', '독', 100, 73, 83, 73, 83, 55, 317, 26, false),
 (583, 195, 1, '샤프니아', '사나움포켓몬', '겁이 많아 1마리일 때는 사냥도 하지 않는다. 5마리 정도 모이면 갑자기 흉포해진다.', '0.8m', '20.8kg', '물/악', 45, 90, 20, 65, 20, 65, 318, null, false),
 (584, 195, 2, '샤크니아', '난폭포켓몬', '빠진 이빨을 지니고 있으면 바다에서 사고를 당하지 않는다고 믿어 액세서리 등으로 가공된다.', '1.8m', '88.8kg', '물/악', 70, 120, 40, 95, 40, 95, 319, 30, false),
 (586, 196, 1, '고래왕자', '둥근고래포켓몬', '입을 열고 헤엄쳐서 해수와 함께 먹이를 먹는다. 필요없는 물은 코로 내뿜는다.', '2m', '130kg', '물', 130, 70, 35, 70, 35, 60, 320, null, false),
 (587, 196, 2, '고래왕', '뜸고래포켓몬', '너무 많은 물고기포켓몬을 먹기 때문에 개체 수가 많이 늘어나면 어부들에게 내쫓긴다.', '14.5m', '398kg', '물', 170, 90, 45, 90, 45, 60, 321, 40, false),
 (589, 197, 1, '둔타', '둔감포켓몬', '맞아도 알아채지 못할 정도로 둔하지만 배고픔은 단 1초도 참지 못한다. 몸 안에는 마그마가 끓어오르고 있다.', '0.7m', '24kg', '불꽃/땅', 60, 60, 40, 65, 45, 35, 322, null, false),
 (590, 197, 2, '폭타', '분화포켓몬', '몸 안에 화산을 지닌 포켓몬이다. 몸에 모은 섭씨 1만 도의 마그마를 가끔 등의 혹에서 뿜어 올리고 있다.', '1.9m', '220kg', '불꽃/땅', 70, 100, 70, 105, 75, 40, 323, 33, false),
 (592, 198, 1, '코터스', '석탄포켓몬', '등껍질에서 내뿜는 연기로 몸 상태를 알 수 있다. 기세가 격렬할 때는 건강하다는 증거다.', '0.5m', '80.4kg', '불꽃', 70, 85, 140, 85, 70, 20, 324, null, false),
 (595, 199, 1, '피그점프', '튀다포켓몬', '꼬리로 뿅뿅 뛰어오르는 포켓몬이다. 뛰어오르는 진동으로 심장을 움직이기 때문에 뛰어오르는 것을 멈출 수 없다.', '0.7m', '30.6kg', '에스퍼', 60, 25, 35, 70, 80, 60, 325, null, false),
 (596, 199, 2, '피그킹', '조작포켓몬', '사이코 파워의 파동을 흑진주로 강화해 자유자재로 상대를 조종하는 포켓몬이다. 힘을 사용할 때 콧김이 거칠어진다.', '0.9m', '71.5kg', '에스퍼', 80, 45, 65, 90, 110, 80, 326, 32, false),
 (598, 200, 1, '얼루기', '얼룩팬더포켓몬', '걸음걸이가 비틀비틀 불안하다. 긴 시간 계속 걸으면 기분이 나빠진다.', '1.1m', '5kg', '노말', 60, 60, 60, 60, 60, 60, 327, null, false),
 (601, 201, 1, '톱치', '개미지옥포켓몬', '턱은 바위도 부수지만 무거워서 뒤집히면 일어나지 못한다. 깜눈크는 그 틈을 노린다.', '0.7m', '15kg', '땅', 45, 100, 45, 45, 45, 10, 328, null, false),
 (602, 201, 2, '비브라바', '진동포켓몬', '날개를 진동시켜 초음파를 발산한다. 기절한 먹이를 모래 속에 산 채로 묻어 저장한다.', '1.1m', '15.3kg', '땅/드래곤', 50, 70, 50, 50, 50, 70, 329, 35, false),
 (603, 201, 3, '플라이곤', '정령포켓몬', '날갯짓으로 모래바람을 일으켜 그곳에 악비아르를 숨긴다. 잡은 먹이는 나누어 갖는다.', '2m', '82kg', '땅/드래곤', 80, 100, 80, 80, 80, 100, 330, 45, false),
 (604, 202, 1, '선인왕', '선인장포켓몬', '사막같이 건조한 지역에 서식한다. 강한 꽃의 향기로 먹이를 유인하고 몸에 난 날카로운 가시를 날려 잡는다.', '0.4m', '51.3kg', '풀', 50, 85, 40, 85, 40, 35, 331, null, false),
 (605, 202, 2, '밤선인', '허수아비포켓몬', '사막의 햇빛에 수분을 빼앗기지 않도록 낮에는 가만히 계속하여 서 있다. 기온이 떨어지는 밤에 활동을 시작한다.', '1.3m', '77.4kg', '풀/악', 70, 115, 60, 115, 60, 55, 332, 32, false),
 (607, 203, 1, '쟝고', '고양이족제비포켓몬', '숙적 세비퍼와 대결했던 기억이 전신의 세포에 새겨져 있다. 민첩한 몸동작으로 공격을 피한다.', '1.3m', '40.3kg', '노말', 73, 115, 60, 60, 60, 90, 335, null, false),
 (610, 204, 1, '세비퍼', '송곳뱀포켓몬', '조상 대대로 쟝고와 싸워왔다. 몸의 상처는 격렬한 싸움의 증거다. 날카롭고 예리한 꼬리로 공격한다.', '2.7m', '52.5kg', '독', 73, 100, 60, 100, 60, 65, 336, null, false),
 (613, 205, 1, '루나톤', '별똥별포켓몬', '운석이 떨어진 장소에서 발견되어 우주에서 온 포켓몬이라는 설도 있지만 아직 증명되지 않았다.', '1m', '168kg', '바위/에스퍼', 90, 55, 65, 95, 85, 70, 337, null, false),
 (616, 206, 1, '솔록', '별똥별포켓몬', '우주에서 떨어졌다고 전해지는 새로운 종이다. 공중에 떠서 소리 없이 이동한다. 싸울 때는 강한 빛을 발산한다.', '1.2m', '154kg', '바위/에스퍼', 90, 95, 85, 55, 65, 70, 338, null, false),
 (619, 207, 1, '미꾸리', '수염물고기포켓몬', '전신이 미끈미끈하다. 새포켓몬이 쪼아도 미끄덩 미끄러져 도망칠 수 있다.', '0.4m', '1.9kg', '물/땅', 50, 48, 43, 46, 41, 60, 339, null, false),
 (620, 207, 2, '메깅', '수염물고기포켓몬', '격렬하게 지면을 흔들어 상대를 위협한다. 늪 바닥의 먹이는 진흙과 함께 통째로 삼켜 버린다.', '0.9m', '23.6kg', '물/땅', 110, 78, 73, 76, 71, 60, 340, 30, false),
 (622, 208, 1, '가재군', '건달포켓몬', '트레이너가 기를 수 없게 되어 놓아 주었던 개체가 늘어나서 알로라에서도 흔해졌다.', '0.6m', '11.5kg', '물', 43, 80, 65, 50, 35, 35, 341, null, false),
 (623, 208, 2, '가재장군', '불량배포켓몬', '기질이 거칠고 싸움을 좋아하지만, 집게가 떨어지면 바로 약해진다. 재생될 때까지 벌벌 떤다.', '1.1m', '32.8kg', '물/악', 63, 120, 85, 90, 55, 55, 342, 30, false),
 (625, 209, 1, '릴링', '바다나리포켓몬', '고대의 따듯한 바다에 살았다. 해초로 둔갑해 먹이를 기다리다가 다가오면 통째로 삼킨다.', '1m', '23.8kg', '바위/풀', 66, 41, 77, 61, 87, 23, 345, null, false),
 (626, 209, 2, '릴리요', '바위단지포켓몬', '평소에는 얕은 여울 바다 밑에 살고 물이 빠지면 그대로 지상으로 올라가 먹이를 찾았다.', '1.5m', '60.4kg', '바위/풀', 86, 81, 97, 81, 107, 43, 346, 40, false),
 (628, 210, 1, '아노딥스', '고대새우포켓몬', '화석에서 복원한 아노딥스를 바다에 놓아줘도 기운이 없다. 당시와 수질이 다르기 때문이다.', '0.7m', '12.5kg', '바위/벌레', 45, 95, 50, 40, 50, 75, 347, null, false),
 (629, 210, 2, '아말도', '갑주포켓몬', '지상에 살며 먹이를 찾아 바다로 사냥을 나갔다. 날카로운 발톱이 최대 무기다.', '1.5m', '68.2kg', '바위/벌레', 75, 125, 100, 70, 80, 45, 348, 40, false),
 (631, 211, 1, '빈티나', '물고기포켓몬', '모습이 초라해서 아무도 잡지 않는다. 맛없어 보여서 아무도 먹지 않는다. 결과적으로 개체 수만 점점 늘어난다.', '0.6m', '7.4kg', '물', 20, 15, 20, 10, 55, 80, 349, null, false),
 (632, 211, 2, '밀로틱', '사랑포켓몬', '가장 아름답다고 하지만 빈티나가 좋아서 기른 트레이너에게는 미묘한 듯하다.', '6.2m', '162kg', '물', 95, 60, 79, 100, 125, 81, 350, 25, false),
 (634, 212, 1, '캐스퐁', '날씨포켓몬', '날씨에 따라 모습이 바뀌지만, 화학 반응의 결과일 뿐 자신의 의지는 아닌 듯하다.', '0.3m', '0.8kg', '노말', 70, 70, 70, 70, 70, 70, 351, null, false),
 (637, 213, 1, '켈리몬', '색변화포켓몬', '몸의 색을 바꿔 경치에 녹아든다. 오랫동안 방치하면 토라져서 모습을 볼 수 없게 된다.', '1m', '22kg', '노말', 60, 90, 70, 60, 120, 40, 352, null, false),
 (640, 214, 1, '어둠대신', '인형포켓몬', '원한, 시샘, 질투 같은 감정을 먹기 때문에 사람에게는 고마운 존재다.', '0.6m', '2.3kg', '고스트', 44, 75, 35, 63, 33, 45, 353, null, false),
 (641, 214, 2, '다크펫', '봉제인형포켓몬', '버려진 인형에 원념이 깃들었다. 자신을 버린 자를 찾아내 복수할 셈이다.', '1.1m', '12.5kg', '고스트', 64, 115, 65, 83, 63, 65, 354, 37, false),
 (643, 215, 1, '해골몽', '마중포켓몬', '아무리 두꺼운 벽이라도 통과한다. 한 번 노려지면 아침 해가 뜰 때까지 계속 쫓겨 다니게 된다.', '0.8m', '15kg', '고스트', 20, 40, 90, 30, 90, 25, 355, null, false),
 (644, 215, 2, '미라몽', '손짓포켓몬', '몸 안에는 텅 비어서 아무것도 없다. 블랙홀처럼 무엇이든 빨아들이며 빨려 들어가면 되돌아 올 수 없다고 전해진다.', '1.6m', '30.6kg', '고스트', 40, 70, 130, 60, 130, 25, 356, 37, false),
 (645, 215, 3, '야느와르몽', '움켜쥠포켓몬', '탄력 있는 몸 안에 갈 곳 없는 영혼을 가두어 저승으로 데려간다고 전해진다.', '2.2m', '106.6kg', '고스트', 45, 100, 135, 65, 135, 45, 477, 47, false),
 (646, 216, 1, '트로피우스', '후르츠포켓몬', '알로라에 사는 트로피우스는 다른 지방에 비해 목에 열리는 송이가 특히 달콤하고 맛있다.', '2m', '100kg', '풀/비행', 99, 68, 83, 72, 87, 51, 357, null, false),
 (649, 217, 1, '앱솔', '재난포켓몬', '비록 겉모습은 불길하지만 논밭을 지키거나 이변을 사람에게 알려 주는 고마운 존재다.', '1.2m', '47kg', '악', 65, 130, 60, 75, 60, 75, 359, null, false),
 (652, 218, 1, '대굴레오', '손뼉포켓몬', '걷는 것보다 구르는 편이 단연 빠르다. 식사 시간에는 모두가 일제히 손뼉을 치며 기뻐하기 때문에 꽤 시끄럽다.', '0.8m', '39.5kg', '얼음/물', 70, 40, 50, 55, 50, 25, 363, null, false),
 (653, 218, 2, '씨레오', '공돌리기포켓몬', '처음 본 것은 반드시 코로 빙글빙글 돌려보는 습성을 지녔다. 대굴레오를 돌리며 놀기도 한다.', '1.1m', '87.6kg', '얼음/물', 90, 60, 70, 75, 70, 45, 364, 32, false),
 (654, 218, 3, '씨카이저', '얼음깨기포켓몬', '발달한 2개의 이빨은 10톤이나 되는 빙산을 일격에 분쇄한다. 지방이 두꺼워서 영하의 기온에서도 끄떡없다.', '1.4m', '150.6kg', '얼음/물', 110, 80, 90, 95, 90, 65, 365, 44, false),
 (655, 219, 1, '진주몽', '두조개포켓몬', '보기와는 다르게 육식이다. 2개의 껍질로 먹이를 꽉 물고 움직이지 않을 때까지 놓지 않는다.', '0.4m', '52.5kg', '물', 35, 64, 85, 74, 55, 32, 366, null, false),
 (656, 219, 2, '헌테일', '깊은바다포켓몬', '헤엄치는 힘은 그다지 강하지 않다. 꼬리를 흔들어 먹이를 유인해 다가오면 덥석 문다.', '1.7m', '27kg', '물', 55, 104, 105, 94, 75, 52, 367, 25, false),
 (658, 220, 1, '분홍장이', '남해포켓몬', '몸의 색깔은 물의 온도로 변화한다. 알로라의 분홍장이는 눈부실 정도로 선명한 빛깔을 지녔다.', '1.8m', '22.6kg', '물', 55, 84, 105, 114, 75, 52, 368, null, false),
 (661, 221, 1, '시라칸', '장수포켓몬', '멸종되었고 여겨져 왔다. 시라칸의 이름은 발견한 사람의 이름을 따서 만들어졌다.', '1m', '23.4kg', '물/바위', 100, 90, 130, 45, 65, 55, 369, null, false),
 (664, 222, 1, '사랑동이', '랑데부포켓몬', '하트 모양의 비늘을 갖고 있으면 연인이 생긴다는 소문이 돌아 남획된 시대도 있었다.', '0.6m', '8.7kg', '물', 43, 30, 55, 40, 65, 97, 370, null, false),
 (667, 223, 1, '레지락', '바위산포켓몬', '오래전 사람에게 봉인된 포켓몬이다. 싸움으로 몸이 부서지면 스스로 새로운 바위를 찾아서 고친다고 한다.', '1.7m', '230kg', '바위', 80, 100, 200, 50, 100, 50, 377, null, false),
 (670, 224, 1, '레지아이스', '빙산포켓몬', '빙하시대에 만들어진 얼음으로 된 몸은 불꽃으로도 녹일 수가 없다. 영하 200도의 냉기를 다룬다.', '1.8m', '175kg', '얼음', 80, 50, 100, 100, 200, 50, 378, null, false),
 (673, 225, 1, '레지스틸', '쇠철포켓몬', '어떤 금속보다도 단단한 몸을 지녔다. 몸 안은 비어 있는 듯하며 먹는 것도 알려지지 않은 포켓몬이다.', '1.9m', '205kg', '강철', 80, 75, 150, 75, 150, 50, 379, null, false),
 (676, 226, 1, '라티아스', '무한포켓몬', '인간의 마음을 민감히 감지해낸다. 적의를 느끼면 전신의 깃털을 곤두세우고 격렬한 울음소리로 위협한다.', '1.4m', '40kg', '드래곤/에스퍼', 80, 80, 90, 110, 130, 110, 380, null, false),
 (679, 227, 1, '라티오스', '무한포켓몬', '본 것이나 생각한 이미지를 상대에게 영상으로 보여주는 능력을 지녔다. 인간의 말을 이해할 수 있다.', '2m', '60kg', '드래곤/에스퍼', 80, 90, 80, 130, 110, 110, 381, null, false),
 (682, 228, 1, '가이오가', '해저포켓몬', '자연의 힘에 의해 원시회귀하여 원래의 모습을 되찾는다. 그 힘은 폭풍을 불러들이며 바다를 확장한다.', '4.5m', '352kg', '물', 100, 100, 90, 150, 140, 90, 382, null, false),
 (685, 229, 1, '그란돈', '대륙포켓몬', '대지의 화신이라 전해지는 포켓몬. 자연의 힘을 갈구하여 가이오가와 사투를 반복한다는 전설이 있다.', '3.5m', '950kg', '땅', 100, 150, 140, 100, 90, 90, 383, null, false),
 (688, 230, 1, '레쿠쟈', '천공포켓몬', '몇억 년 동안 계속 살고 있다고 한다. 그란돈과 가이오가의 사투를 진정시켰다는 전설이 남아 있다.', '7m', '206.5kg', '드래곤/비행', 105, 150, 90, 150, 90, 95, 384, null, false),
 (691, 231, 1, '지라치', '희망사항포켓몬', '깨어났을 때 머리에 있는 종이에 적힌 소원을 이루어준다는 전설을 가졌다. 위험을 느끼면 잠든 채로 싸운다.', '0.3m', '1.1kg', '강철/에스퍼', 100, 100, 100, 100, 100, 100, 385, null, false),
 (694, 232, 1, '테오키스', 'DNA포켓몬', '레이저를 쬔 우주 바이러스의 DNA가 돌연변이를 일으켜 태어난 포켓몬이다. 가슴의 수정체가 뇌인 것 같다.', '1.7m', '60.8kg', '에스퍼', 50, 150, 50, 150, 50, 150, 386, null, false),
 (697, 233, 1, '모부기', '어린잎포켓몬', '태양의 빛을 쬐어 전신으로 광합성을 한다. 등껍질은 흙이 딱딱해진 것이다.', '0.4m', '10.2kg', '풀', 55, 68, 64, 45, 55, 31, 387, null, false),
 (698, 233, 2, '수풀부기', '나무숲포켓몬', '숲 속의 물가에서 산다. 낮에는 숲 밖으로 나와서 등껍질의 나무에 빛을 쬔다.', '1.1m', '97kg', '풀', 75, 89, 85, 55, 65, 36, 388, 18, false),
 (699, 233, 3, '토대부기', '대륙포켓몬', '오랜 옛날 사람들은 대지 밑에 거대한 토대부기가 있다고 공상했었다.', '2.2m', '310kg', '풀/땅', 95, 109, 105, 75, 85, 56, 389, 32, false),
 (700, 234, 1, '불꽃숭이', '꼬마원숭이포켓몬', '엉덩이의 불꽃은 배에서 만들어진 가스가 연료다. 비에 젖어도 꺼지지 않는다.', '0.5m', '6.2kg', '불꽃', 44, 58, 44, 58, 44, 61, 390, null, false),
 (701, 234, 2, '파이숭이', '개구쟁이포켓몬', '꼬리의 불꽃 세기를 잘 컨트롤하여 자신에게 맞는 거리를 두고 싸운다.', '0.9m', '22kg', '불꽃/격투', 64, 78, 52, 78, 52, 81, 391, 14, false),
 (702, 234, 3, '초염몽', '화염포켓몬', '머리에서 타오르는 불꽃처럼 과격한 성격의 포켓몬이다. 스피드는 누구에게도 지지 않는다.', '1.2m', '55kg', '불꽃/격투', 76, 104, 71, 104, 71, 108, 392, 36, false),
 (703, 235, 1, '팽도리', '펭귄포켓몬', '신세를 지는 것을 싫어한다. 트레이너의 지시를 듣지 않아 친해지기 어렵다.', '0.4m', '5.2kg', '물', 53, 51, 53, 61, 56, 40, 393, null, false),
 (704, 235, 2, '팽태자', '펭귄포켓몬', '무리를 만들지 않고 혼자 생활한다. 어떤 팽태자라도 자신이 제일 훌륭하다고 생각하는 듯하다.', '0.8m', '23kg', '물', 64, 66, 68, 81, 76, 50, 394, 16, false),
 (705, 235, 3, '엠페르트', '황제포켓몬', '제트스키와 맞먹는 속도로 헤엄친다. 날개 가장자리는 날카롭게 유빙을 절단한다.', '1.7m', '84.5kg', '물/강철', 84, 86, 88, 111, 101, 60, 395, 36, false),
 (706, 236, 1, '비버니', '둥글쥐포켓몬', '어떤 것에도 동요하지 않는 대담한 신경의 소유자다. 보기보다는 기민하게 활동한다.', '0.5m', '20kg', '노말', 59, 45, 40, 35, 40, 31, 399, null, false),
 (707, 236, 2, '비버통', '비버포켓몬', '예리한 앞니로 갉아 얻은 나뭇가지나 뿌리를 쌓아 물가에 부지런히 보금자리를 만든다.', '1m', '31.5kg', '노말/물', 79, 85, 60, 55, 60, 71, 400, 15, false),
 (709, 237, 1, '귀뚤뚜기', '귀뚜라미포켓몬', '더듬이를 서로 부딪쳐 내는 소리로 동료와 대화한다. 음색은 가을밤의 정취를 잘 나타낸다.', '0.3m', '2.2kg', '벌레', 37, 25, 41, 25, 41, 25, 401, null, false),
 (710, 237, 2, '귀뚤톡크', '귀뚜라미포켓몬', '울 때는 나이프 같은 팔을 가슴 앞에서 교차시킨다. 즉흥으로 멜로디를 만든다.', '1m', '25.5kg', '벌레', 77, 85, 51, 55, 51, 65, 402, 10, false),
 (712, 238, 1, '꼬몽울', '꽃봉오리포켓몬', '따뜻한 햇볕을 쬐면 봉오리를 펴서 꽃가루를 날린다. 깨끗한 물 가까이에 거처가 있다.', '0.2m', '1.2kg', '풀/독', 40, 30, 35, 50, 70, 55, 406, null, false),
 (713, 238, 2, '로젤리아', '가시포켓몬', '양손의 꽃을 노리는 상대에게는 날카로운 가시를 날려 공격한다. 꽃의 향기는 기분을 누그러트린다.', '0.3m', '2kg', '풀/독', 50, 60, 45, 100, 80, 65, 315, 25, false),
 (714, 238, 3, '로즈레이드', '부케포켓몬', '달콤한 향기로 먹이를 유인해 양팔의 독 채찍을 사용하여 찌르거나 조여서 꼼짝 못하게 한다.', '0.9m', '14.5kg', '풀/독', 60, 70, 65, 125, 105, 90, 407, null, true),
 (715, 239, 1, '두개도스', '박치기포켓몬', '태곳적 포켓몬. 딱딱하고 튼튼한 두개골을 가졌지만 머리는 정말 나빴다.', '0.9m', '31.5kg', '바위', 67, 125, 40, 30, 30, 58, 408, null, false),
 (716, 239, 2, '램펄드', '박치기포켓몬', '먼 옛날 사람은 화석을 발굴하여 강철보다 딱딱한 두개골로 투구를 만들었다.', '1.6m', '102.5kg', '바위', 97, 165, 60, 65, 50, 58, 409, 30, false),
 (718, 240, 1, '방패톱스', '실드포켓몬', '온순한 초식 포켓몬. 튼튼한 얼굴 피부로 지면을 파고들어 나무 뿌리도 먹었다.', '0.5m', '57kg', '바위/강철', 30, 42, 118, 42, 88, 30, 410, null, false),
 (719, 240, 2, '바리톱스', '실드포켓몬', '얼굴의 뼈가 크고 딱딱해서 복원에 성공할 때까지 등뼈라고 잘못 알려져 있었다.', '1.3m', '149.5kg', '바위/강철', 60, 52, 168, 47, 138, 30, 411, 30, false),
 (721, 241, 1, '도롱충이', '도롱이벌레포켓몬', '차가운 초겨울 바람을 막으려고 작은 가지나 낙엽을 재료로 도롱이를 만들어 몸을 감싼다.', '0.2m', '3.4kg', '벌레', 40, 29, 45, 29, 45, 36, 412, null, false),
 (722, 241, 2, '도롱마담', '도롱이벌레포켓몬', '진화한 장소에 따라 모습이 바뀐다. 가까이 있는 재료가 몸의 일부가 된다.', '0.5m', '6.5kg', '벌레/풀', 60, 59, 85, 79, 105, 36, 413, 20, false),
 (724, 242, 1, '나메일', '나방포켓몬', '꽃의 꿀을 매우 좋아한다. 세꿀버리가 모아둔 꿀을 가로채어 먹어 버린다.', '0.9m', '23.3kg', '벌레/비행', 70, 94, 50, 94, 50, 66, 414, null, false),
 (727, 243, 1, '세꿀버리', '꼬마벌포켓몬', '태어났을 때부터 3마리가 함께한다. 비퀸을 기쁘게 하기 위해 항상 꽃의 꿀을 모으고 있다.', '0.3m', '5.5kg', '벌레/비행', 30, 30, 42, 30, 42, 70, 415, null, false),
 (728, 243, 2, '비퀸', '벌집포켓몬', '몸통은 새끼들의 둥지다. 여러 페로몬을 내어 새끼들을 자유롭게 조종한다.', '1.2m', '38.5kg', '벌레/비행', 70, 80, 102, 80, 102, 40, 416, 21, false),
 (730, 244, 1, '파치리스', '전기다람쥐포켓몬', '정전기가 모여 톡톡 튀는 솜털을 자신이 좋아하는 나무열매와 함께 나무줄기의 구멍에 숨긴다.', '0.4m', '3.9kg', '전기', 60, 45, 70, 45, 90, 95, 417, null, false),
 (733, 245, 1, '브이젤', '바다족제비포켓몬', '2개의 꼬리를 스크루처럼 돌려서 헤엄친다. 잠수할 때는 부낭이 오그라든다.', '0.7m', '29.5kg', '물', 55, 65, 35, 60, 30, 85, 418, null, false),
 (734, 245, 2, '플로젤', '바다족제비포켓몬', '발달한 부낭으로 뜬다. 물에 빠진 사람을 구조하는 것을 돕는 포켓몬이다.', '1.1m', '33.5kg', '물', 85, 105, 55, 85, 50, 115, 419, 26, false),
 (736, 246, 1, '체리버', '버찌포켓몬', '햇빛으로 빨갛게 물들었다. 영양분이 흡수되어 작은 구슬이 시들면 곧 진화한다는 뜻이다.', '0.4m', '3.3kg', '풀', 45, 35, 45, 62, 53, 35, 420, null, false),
 (737, 246, 2, '체리꼬', '벚꽃포켓몬', '봉오리가 태양의 빛을 쬐어 꽃잎이 피면 활발하게 움직일 수 있게 된다.', '0.5m', '9.3kg', '풀', 70, 60, 70, 87, 78, 85, 421, 25, false),
 (739, 247, 1, '깝질무', '갯민숭달팽이포켓몬', '평소에는 바닷속에서 지내지만, 피부가 마르기 전까지는 육지에서도 활동할 수 있다.', '0.3m', '6.3kg', '물', 76, 48, 48, 57, 62, 34, 422, null, false),
 (740, 247, 2, '트리토돈', '갯민숭달팽이포켓몬', '옛날에는 껍질을 등에 지고 있었다. 그 흔적이 남아 등 안에 딱딱하고 얇은 접시가 있다.', '0.9m', '29.9kg', '물/땅', 111, 83, 68, 92, 82, 39, 423, 30, false),
 (742, 248, 1, '흔들풍손', '풍선포켓몬', '둥근 몸 안에는 많은 혼으로 가득 차 있다. 누군가를 길동무로 삼을 때마다 부풀어 오른다.', '0.4m', '1.2kg', '고스트/비행', 90, 50, 34, 60, 44, 70, 425, null, false),
 (743, 248, 2, '둥실라이드', '기구포켓몬', '땅거미 진 후 바람을 타며 날아다니는 둥실라이드에게 잡히면 저세상으로 데려간다는 소문이다.', '1.2m', '15kg', '고스트/비행', 150, 80, 44, 90, 54, 80, 426, 28, false),
 (745, 249, 1, '이어롤', '토끼포켓몬', '손발의 힘은 약하지만, 단단하게 만 귀를 힘껏 뻗으면 큰 바위도 산산조각 낸다.', '0.4m', '5.5kg', '노말', 55, 66, 44, 44, 56, 85, 427, null, false),
 (746, 249, 2, '이어롭', '토끼포켓몬', '연 2회 털갈이를 한다. 그 털로 만든 머플러나 모자는 매우 따듯하다.', '1.2m', '33.3kg', '노말', 65, 76, 84, 54, 96, 105, 428, 25, false),
 (748, 250, 1, '나옹마', '내숭포켓몬', '마음에 안 들면 발톱을 세우지만 가끔 울음소리로 응석을 부리는 성격이 일부에게 매우 인기가 있다.', '0.5m', '3.9kg', '노말', 49, 55, 42, 42, 37, 85, 431, null, false),
 (749, 250, 2, '몬냥이', '얼룩고양이포켓몬', '다른 포켓몬의 거처라 할지라도 편안하면 눌러앉아 자신의 거처로 삼아버린다.', '1m', '43.8kg', '노말', 71, 82, 64, 64, 59, 112, 432, 38, false),
 (751, 251, 1, '랑딸랑', '방울포켓몬', '뛸 때마다 딸랑딸랑 소리를 낸다. 높은 주파수의 울음소리로 상대의 귀를 들리지 않게 한다.', '0.2m', '0.6kg', '에스퍼', 45, 30, 50, 65, 50, 45, 433, null, false),
 (752, 251, 2, '치렁', '풍경포켓몬', '목소리를 몸의 빈 곳에 메아리치게 한다. 화가 났을 때의 울음소리는 적을 날려버릴 위력을 지닌 초음파가 된다.', '0.6m', '1kg', '에스퍼', 75, 50, 80, 95, 90, 65, 358, 25, false),
 (754, 252, 1, '스컹뿡', '스컹크포켓몬', '엉덩이에서 뿜어지는 역한 분비액의 냄새는 반경 2km까지 멀리 퍼져 주변의 포켓몬이 자리를 뜨게 한다.', '0.4m', '19.2kg', '독/악', 63, 63, 47, 41, 41, 74, 434, null, false),
 (755, 252, 2, '스컹탱크', '스컹크포켓몬', '꼬리 끝에서 심한 냄새가 나는 액체를 뿌려 공격한다. 사정거리는 50m 이상이다.', '1m', '38kg', '독/악', 103, 93, 67, 71, 61, 84, 435, 34, false),
 (757, 253, 1, '꼬지지', '분재포켓몬', '눈동자에서 수분을 방출한다. 울고 있는 것처럼 보이기 때문에 적을 방심시키는 효과도 있는 듯하다.', '0.5m', '15kg', '바위', 50, 80, 95, 10, 45, 10, 438, null, false),
 (758, 253, 2, '꼬지모', '흉내포켓몬', '노인에게 인기로 전문지가 있을 정도다. 애호가는 팔의 길이와 각도에 신경 쓴다.', '1.2m', '38kg', '바위', 70, 100, 115, 30, 65, 30, 185, 25, false),
 (760, 254, 1, '흉내내', '따라하기포켓몬', '상대의 움직임과 표정을 열심히 흉내 낸다. 아직 잘한다고는 할 수 없다.', '0.6m', '13kg', '에스퍼/페어리', 20, 25, 45, 70, 90, 60, 439, null, false),
 (761, 254, 2, '마임맨', '배리어포켓몬', '팬터마임 실력이 굉장하다. 넋을 놓고 보다 보면 어느새 진짜 벽이 나타난다.', '1.3m', '54.5kg', '에스퍼/페어리', 40, 45, 65, 100, 120, 90, 122, 25, false),
 (763, 255, 1, '핑복', '소꿉놀이포켓몬', '온순한 포켓몬이지만 배의 둥근 돌을 빼내면 울고불고 난폭해진다.', '0.6m', '24.4kg', '노말', 100, 5, 5, 15, 65, 30, 440, null, false),
 (764, 255, 2, '럭키', '알포켓몬', '맛있고 영양 많은 알을 다른 포켓몬들이 자꾸 노려서 도망치는 속도가 빨라진 듯하다.', '1.1m', '34.6kg', '노말', 250, 5, 5, 35, 105, 50, 113, 25, false),
 (765, 255, 3, '해피너스', '행복포켓몬', '알을 먹으면 행복해진다고 전해질 정도로 맛이 일품이다. 시장에서 제일 가격이 비싸다.', '1.5m', '46.8kg', '노말', 255, 10, 10, 75, 135, 55, 242, 40, false),
 (766, 256, 1, '페라페', '음표포켓몬', '상대와 같은 울음소리를 내서 동료라고 굳게 믿게 하여 습격당하지 않도록 하고 있다.', '0.5m', '1.9kg', '노말/비행', 76, 65, 45, 92, 42, 91, 441, null, false),
 (769, 257, 1, '화강돌', '봉인포켓몬', '108개의 영혼이 모여서 태어난 포켓몬이다. 쐐기돌의 균열과 연결되어 있다.', '1m', '108kg', '고스트/악', 50, 92, 108, 92, 108, 35, 442, null, false),
 (772, 258, 1, '먹고자', '대식가포켓몬', '긴 털 아래에 음식을 숨기지만 숨긴 것을 잊어 고약한 냄새가 난다며 소동이 날 때도 있다.', '0.6m', '105kg', '노말', 135, 85, 40, 40, 85, 5, 446, null, false),
 (773, 258, 2, '잠만보', '졸음포켓몬', '먹거나 자는 것밖에 안 하지만 일단 진심을 다하게 되면 굉장한 파워를 발휘하는 듯하다.', '2.1m', '460kg', '노말', 160, 110, 65, 65, 110, 30, 143, 25, false),
 (775, 259, 1, '히포포타스', '하마포켓몬', '건조한 땅에서 산다. 땀 대신 모래알을 몸에서 분비하는 포켓몬이다.', '0.8m', '49.5kg', '땅', 68, 72, 78, 38, 42, 32, 449, null, false),
 (776, 259, 2, '하마돈', '중량포켓몬', '크게 입을 벌려 자신의 강함을 어필한다. 대량의 모래를 일으켜 공격한다.', '2m', '300kg', '땅', 108, 112, 118, 68, 72, 47, 450, 34, false),
 (778, 260, 1, '스콜피', '전갈포켓몬', '꼬리의 발톱으로 먹이를 집어 독을 주입한다. 독이 퍼질 때까지 절대 놓치지 않는 집념이 있다.', '0.8m', '12kg', '독/벌레', 40, 50, 90, 30, 55, 65, 451, null, false),
 (779, 260, 2, '드래피온', '요괴전갈포켓몬', '자랑거리인 파워로 상대를 조각조각 낼 수 있으며 게다가 맹독으로 마무리한다.', '1.3m', '61.5kg', '독/악', 70, 90, 110, 60, 75, 95, 452, 40, false),
 (781, 261, 1, '삐딱구리', '독설포켓몬', '볼에 독주머니를 가지고 있다. 상대의 틈을 노려 맹독이 밴 손가락을 꿰찌른다.', '0.7m', '23kg', '독/격투', 48, 61, 40, 61, 40, 50, 453, null, false),
 (782, 261, 2, '독개굴', '독설포켓몬', '목 주변에 독주머니를 지녔다. 목을 울리면 모여진 독이 잘 섞여져서 강력해진다.', '1.3m', '44.4kg', '독/격투', 83, 106, 65, 86, 65, 85, 454, 37, false),
 (784, 262, 1, '무스틈니', '벌레잡이포켓몬', '달콤한 냄새의 타액으로 먹이를 끌어들여 큰 턱으로 꿀꺽한다. 하루에 걸쳐 먹이를 먹는다.', '1.4m', '27kg', '풀', 74, 100, 72, 90, 72, 46, 455, null, false),
 (787, 263, 1, '형광어', '비어포켓몬', '핑크색 모양은 밤이 되면 빛이 난다. 다이버에게 인기여서 리조트에서 길들여지기도 한다.', '0.4m', '7kg', '물', 49, 49, 56, 49, 61, 66, 456, null, false),
 (788, 263, 2, '네오라이트', '네온포켓몬', '깊은 바다 밑은 먹이가 적다. 귀한 먹이를 두고 랜턴과 격렬히 싸운다.', '1.2m', '24kg', '물', 69, 69, 76, 69, 86, 91, 457, 31, false),
 (790, 264, 1, '타만타', '연포켓몬', '매우 사람을 잘 따른다. 타만타 체험 투어는 인기가 많은 비치 액티비티다.', '1m', '65kg', '물/비행', 45, 20, 50, 60, 120, 50, 458, null, false),
 (791, 264, 2, '만타인', '연포켓몬', '우아하게 파도 위를 튀어 오르는 만타인을 그린 그림엽서나 포스터는 인기 있는 알로라 특산품이다.', '2.1m', '220kg', '물/비행', 85, 40, 70, 80, 140, 70, 226, 25, false),
 (793, 265, 1, '리피아', '심록포켓몬', '다툼을 좋아하지 않지만 동료를 지키기 위해서라면 꼬리의 잎사귀를 날카로운 칼날로 만들어 싸운다.', '1m', '25.5kg', '풀', 65, 110, 130, 60, 65, 95, 470, null, true),
 (796, 266, 1, '글레이시아', '신설포켓몬', '몸의 털을 얼려 예리한 바늘로 만들어 몸을 지킨다. 체온은 마이너스 60도까지 내릴 수 있다.', '0.8m', '25.9kg', '얼음', 65, 60, 110, 130, 95, 65, 471, null, true),
 (799, 267, 1, '엘레이드', '검포켓몬', '상대의 생각을 민감하게 포착하는 능력을 가졌기 때문에 먼저 공격할 수 있다.', '1.6m', '52kg', '에스퍼/격투', 68, 125, 65, 65, 115, 80, 475, null, true),
 (802, 268, 1, '눈여아', '설국포켓몬', '설산에 등산 온 남자를 얼려버려 집으로 가지고 간다. 미남만 노린다.', '1.3m', '26.6kg', '얼음/고스트', 70, 80, 70, 80, 70, 110, 478, null, true),
 (805, 269, 1, '로토무', '플라스마포켓몬', '특수한 모터를 움직이는 동력원으로서 긴 시간 동안 연구되었던 포켓몬이다.', '0.3m', '0.3kg', '전기/고스트', 50, 50, 77, 95, 77, 91, 479, null, false),
 (808, 270, 1, '유크시', '지식포켓몬', '지식의 신이라 불리고 있다. 눈을 마주친 사람의 기억을 지워 버리는 힘을 가지고 있다고 한다.', '0.3m', '0.3kg', '에스퍼', 75, 75, 130, 75, 130, 95, 480, null, false),
 (811, 271, 1, '엠라이트', '감정포켓몬', '슬픔의 괴로움과 즐거움의 소중함을 사람들에게 가르쳐 주었다. 감정의 신이라 불리고 있다.', '0.3m', '0.3kg', '에스퍼', 80, 105, 105, 105, 105, 80, 481, null, false),
 (814, 272, 1, '아그놈', '의지포켓몬', '의지의 신이라 불리고 있다. 호수의 밑바닥에서 계속 잠을 자며 세계의 균형을 지키고 있다.', '0.3m', '0.3kg', '에스퍼', 75, 125, 70, 125, 70, 115, 482, null, false),
 (817, 273, 1, '디아루가', '시간포켓몬', '디아루가가 태어남으로써 시간이 움직이기 시작했다는 전설이 내려오는 포켓몬이다.', '5.4m', '683kg', '강철/드래곤', 100, 120, 120, 150, 100, 90, 483, null, false),
 (820, 274, 1, '펄기아', '공간포켓몬', '평행으로 늘어선 공간의 틈새에 산다고 전해진다. 신화에 등장하는 포켓몬이다.', '4.2m', '336kg', '물/드래곤', 90, 120, 100, 150, 120, 100, 484, null, false),
 (823, 275, 1, '히드런', '화구포켓몬', '화산의 동굴에서 서식한다. 십자형의 발톱을 박아서 벽이나 천장을 돌아다닌다.', '1.7m', '430kg', '불꽃/강철', 91, 90, 106, 130, 106, 77, 485, null, false),
 (826, 276, 1, '레지기가스', '거대포켓몬', '특수한 빙산이나 암석, 마그마에서 자신의 모습과 닮은 포켓몬을 만들었다고 전해진다.', '3.7m', '420kg', '노말', 110, 160, 110, 80, 110, 100, 486, null, false),
 (829, 277, 1, '크레세리아', '초승달포켓몬', '비행할 때는 베일 같은 날개에서 빛나는 입자를 낸다. 초승달의 화신으로 불리고 있다.', '1.5m', '85.6kg', '에스퍼', 120, 70, 110, 75, 120, 85, 488, null, false),
 (832, 278, 1, '피오네', '해양포켓몬', '바다 온도가 높아지면 머리의 부낭을 부풀려서 해수면을 집단으로 떠돈다.', '0.4m', '3.1kg', '물', 80, 80, 80, 80, 80, 80, 489, null, false),
 (835, 279, 1, '다크라이', '암흑포켓몬', '깊은 잠으로 끌어들이는 힘으로 사람과 포켓몬에게 악몽을 꾸게 해 자신의 영역에서 쫓아낸다.', '1.5m', '50.5kg', '악', 70, 90, 90, 135, 90, 125, 491, null, false),
 (838, 280, 1, '쉐이미', '감사포켓몬', '대기의 독소를 분해해서 거칠어진 대지를 일순간에 꽃밭으로 만드는 힘을 가지고 있다.', '0.2m', '2.1kg', '풀', 100, 100, 100, 100, 100, 100, 492, null, false),
 (841, 281, 1, '비크티니', '승리포켓몬', '승리를 부르는 포켓몬이다. 비크티니와 함께하는 트레이너는 그 어떤 승부에서도 승리한다고 한다.', '0.4m', '4kg', '에스퍼/불꽃', 100, 100, 100, 100, 100, 100, 494, null, false),
 (844, 282, 1, '주리비얀', '풀뱀포켓몬', '태양의 빛을 받으면 평소보다 빨리 움직일 수 있다. 손보다 덩굴을 잘 사용한다.', '0.6m', '8.1kg', '풀', 45, 45, 55, 45, 55, 63, 495, null, false),
 (845, 282, 2, '샤비', '풀뱀포켓몬', '땅을 미끄러지듯 달린다. 빠른 움직임으로 상대를 혼란시키고 덩굴채찍으로 꼼짝 못하게 한다.', '0.8m', '16kg', '풀', 60, 60, 75, 60, 75, 83, 496, 17, false),
 (846, 282, 3, '샤로다', '로열포켓몬', '샤로다의 고상한 눈동자로 쏘아보아도 태연할 정도로 강한 상대에게만 진정한 실력을 발휘한다.', '3.3m', '63kg', '풀', 75, 75, 95, 75, 95, 113, 497, 36, false),
 (847, 283, 1, '뚜꾸리', '불돼지포켓몬', '적의 공격을 가볍게 피하고 코로 불구슬을 쏘아댄다. 불꽃으로 나무열매를 구워 먹는다.', '0.5m', '9.9kg', '불꽃', 65, 63, 45, 45, 45, 45, 498, null, false),
 (848, 283, 2, '차오꿀', '불돼지포켓몬', '먹을수록 태울 것이 많아져 위 속의 불꽃이 강해지고 파워도 점점 넘치게 된다.', '1m', '55.5kg', '불꽃/격투', 90, 93, 55, 70, 55, 55, 499, 17, false),
 (849, 283, 3, '염무왕', '큰불돼지포켓몬', '턱의 화염으로 주먹을 불태워 불꽃펀치를 날린다. 동료애가 깊은 포켓몬이다.', '1.6m', '150kg', '불꽃/격투', 110, 123, 65, 100, 65, 65, 500, 36, false),
 (850, 284, 1, '수댕이', '해달포켓몬', '배에 생기는 가리비칼은 싸울 때뿐 아니라 딱딱한 나무열매를 쪼갤 때도 사용한다.', '0.5m', '5.9kg', '물', 55, 55, 45, 63, 45, 45, 501, null, false),
 (851, 284, 2, '쌍검자비', '수행포켓몬', '물 흐르는 듯한 칼 솜씨로 2개의 가리비칼을 사용하는 기술은 엄격한 수련을 통해 익힌 것이다.', '0.8m', '24.5kg', '물', 75, 75, 60, 83, 60, 60, 502, 17, false),
 (852, 284, 3, '대검귀', '관록포켓몬', '상대가 눈을 깜빡이는 동안에 앞다리에 붙어 있는 각검으로 상대를 베고 원래대로 되돌린다.', '1.5m', '94.6kg', '물', 95, 100, 85, 108, 70, 70, 503, 36, false),
 (853, 285, 1, '보르쥐', '망보기포켓몬', '볼의 주머니에 먹이를 모아두고 며칠이고 망보기를 계속한다. 꼬리로 동료에게 신호한다.', '0.5m', '11.6kg', '노말', 45, 55, 39, 35, 39, 42, 504, null, false),
 (854, 285, 2, '보르그', '경계포켓몬', '체내의 발광 물질로 눈이나 몸을 빛나게 하여 습격해 온 상대를 풀이 죽게 만든다.', '1.1m', '27kg', '노말', 60, 85, 69, 60, 69, 77, 505, 20, false),
 (856, 286, 1, '요테리', '강아지포켓몬', '판단력이 뛰어난 포켓몬. 이길 수 없는 상대라고 판단되면 바로 꼬리를 내리고 도망친다.', '0.4m', '4.1kg', '노말', 45, 60, 45, 25, 45, 55, 506, null, false),
 (857, 286, 2, '하데리어', '충견포켓몬', '검은 털은 자랄수록 딱딱하고 튼튼해져 발톱이나 이빨로도 쉽게 뚫을 수 없다.', '0.9m', '14.7kg', '노말', 65, 80, 65, 35, 65, 60, 507, 16, false),
 (858, 286, 3, '바랜드', '관대포켓몬', '길고 따듯한 털 덕분에 추위는 걱정 없다. 알로라의 바랜드는 조금 괴로운 것 같다.', '1.2m', '61kg', '노말', 85, 110, 90, 45, 90, 80, 508, 32, false),
 (859, 287, 1, '쌔비냥', '성악포켓몬', '귀여운 행동으로 방심하게 한 후 그 틈에 지닌 물건을 빼앗아 간다. 화가 나면 손톱을 세워서 반격한다.', '0.4m', '10.1kg', '악', 41, 50, 37, 50, 37, 66, 509, null, false),
 (860, 287, 2, '레파르다스', '냉혹포켓몬', '아름다운 스타일은 전신의 발달한 근육 덕분이다. 소리도 내지 않고 밤을 달린다.', '1.1m', '37.5kg', '악', 64, 88, 50, 88, 50, 106, 510, 20, false),
 (862, 288, 1, '야나프', '풀원숭이포켓몬', '기운이 없는 포켓몬에게 머리의 잎사귀를 나눠준다. 피로를 풀어주는 효과가 있다.', '0.6m', '10.5kg', '풀', 50, 53, 48, 53, 48, 64, 511, null, false),
 (863, 288, 2, '야나키', '가시원숭이포켓몬', '가시가 잔뜩 박힌 꼬리를 상대에게 힘껏 쳐서 공격한다. 기질이 격한 포켓몬이다.', '1.1m', '30.5kg', '풀', 75, 98, 63, 98, 63, 101, 512, null, true),
 (865, 289, 1, '바오프', '고온포켓몬', '지능이 높고 나무열매는 구운 뒤 먹는 습성이 있다. 사람 도와주기를 좋아한다.', '0.6m', '11kg', '불꽃', 50, 53, 48, 53, 48, 64, 513, null, false),
 (866, 289, 2, '바오키', '불티포켓몬', '몸속에서 태운 불꽃을 머리나 꼬리로 흩뿌려서 상대를 태운다.', '1m', '28kg', '불꽃', 75, 98, 63, 98, 63, 101, 514, null, true),
 (868, 290, 1, '앗차프', '물뿌리기포켓몬', '머리 송아리에 모은 물은 영양 듬뿍. 꼬리를 사용해서 그 물을 초목에 뿌린다.', '0.6m', '13.5kg', '물', 50, 53, 48, 53, 48, 64, 515, null, false),
 (869, 290, 2, '앗차키', '방수포켓몬', '꼬리에서 발사하는 고압의 물은 콘크리트 벽도 파괴할 수 있는 위력을 지녔다.', '1m', '29kg', '물', 75, 98, 63, 98, 63, 101, 516, null, true),
 (871, 291, 1, '줄뮤마', '하전포켓몬', '번개 구름이 하늘을 뒤덮으면 나타난다. 갈기로 번개를 붙잡아 전기를 모은다.', '0.8m', '29.8kg', '전기', 45, 60, 32, 50, 32, 76, 522, null, false),
 (872, 291, 2, '제브라이카', '뇌전포켓몬', '격렬한 기질의 소유자. 날뛰면 갈기에서 번개를 사방팔방으로 방전한다.', '1.6m', '79.5kg', '전기', 75, 100, 63, 80, 63, 116, 523, 27, false),
 (874, 292, 1, '단굴', '맨틀포켓몬', '육각형의 구멍은 귀다. 귀 안에 에너지 코어가 있어서 손을 넣으면 화를 낸다.', '0.4m', '18kg', '바위', 55, 75, 85, 25, 25, 15, 524, null, false),
 (875, 292, 2, '암트르', '광석포켓몬', '몸에서 넘쳐흐르는 에너지가 오렌지색 결정이 되었다. 다이아몬드도 부술 정도로 견고하다.', '0.9m', '102kg', '바위', 70, 105, 105, 50, 40, 20, 525, 25, false),
 (876, 292, 3, '기가이어스', '고압포켓몬', '전력으로 에너지를 쏘면 그 파워로 자신의 몸에 무수한 균열이 생긴다.', '1.7m', '260kg', '바위', 85, 135, 130, 60, 80, 25, 526, 40, false),
 (877, 293, 1, '또르박쥐', '박쥐포켓몬', '어두운 숲이나 동굴에서 산다. 콧구멍에서 초음파를 쏘아 주변의 모습을 살핀다.', '0.4m', '2.1kg', '에스퍼/비행', 65, 45, 43, 55, 43, 72, 527, null, false),
 (878, 293, 2, '맘박쥐', '구애포켓몬', '콘크리트도 부술 정도로 강한 초음파를 낼 때 꼬리가 심하게 흔들린다.', '0.9m', '10.5kg', '에스퍼/비행', 67, 57, 55, 77, 55, 114, 528, 25, false),
 (880, 294, 1, '두더류', '두더지포켓몬', '양손의 손톱을 서로 겹치고 몸을 고속 회전시키면서 맹렬한 속도로 땅속을 헤쳐나간다.', '0.3m', '8.5kg', '땅', 60, 85, 40, 30, 45, 68, 529, null, false),
 (881, 294, 2, '몰드류', '땅밑포켓몬', '강철로 진화한 드릴은 철판을 뚫는 파괴력을 가졌다. 터널 공사에서 크게 활약한다.', '0.7m', '40.4kg', '땅/강철', 110, 135, 60, 50, 65, 88, 530, 31, false),
 (883, 295, 1, '다부니', '히어링포켓몬', '귀의 더듬이로 상대의 컨디션이나 알에서 포켓몬이 언제 나올지도 알 수 있다.', '1.1m', '31kg', '노말', 103, 60, 86, 60, 86, 50, 531, null, false),
 (886, 296, 1, '동챙이', '올챙이포켓몬', '볼의 진동막을 떨어 사람에게는 들리지 않는 음파를 내어 동료에게 위험을 전달한다.', '0.5m', '4.5kg', '물', 50, 50, 40, 50, 40, 64, 535, null, false),
 (887, 296, 2, '두까비', '진동포켓몬', '머리의 혹을 진동시키면 물속에 파동이 일어나며 땅마저 지진처럼 흔들린다.', '0.8m', '17kg', '물/땅', 75, 65, 55, 65, 55, 69, 536, 25, false),
 (888, 296, 3, '두빅굴', '진동포켓몬', '주먹의 혹을 진동시켜 펀치의 위력을 배가시킨다. 일격에 큰 바위를 부스러뜨린다.', '1.5m', '62kg', '물/땅', 105, 95, 75, 85, 75, 74, 537, 36, false),
 (889, 297, 1, '던지미', '유도포켓몬', '띠를 매면 파워가 올라간다. 야생 던지미는 덩굴풀을 엮어 자신의 띠를 만든다.', '1.3m', '55.5kg', '격투', 120, 100, 85, 30, 85, 45, 538, null, false),
 (892, 298, 1, '타격귀', '태권도포켓몬', '최강의 태권당수를 목표로 산속에 틀어박혀 잠도 없이 수행한다.', '1.4m', '51kg', '격투', 75, 125, 75, 30, 75, 85, 539, null, false),
 (895, 299, 1, '두르보', '재봉포켓몬', '잎사귀를 물어뜯어 입에서 뱉어낸 점착실로 꿰맨다. 스스로 옷을 만드는 포켓몬이다.', '0.3m', '2.5kg', '벌레/풀', 45, 53, 70, 40, 60, 42, 540, null, false),
 (896, 299, 2, '두르쿤', '잎숨기포켓몬', '두르쿤이 사는 숲은 초목이 잘 자란다. 두르쿤이 낙엽을 영양분으로 바꾸기 때문이다.', '0.5m', '7.3kg', '벌레/풀', 55, 63, 90, 50, 80, 42, 541, 20, false),
 (897, 299, 3, '모아머', '육아포켓몬', '어린 포켓몬을 보면 입에서 내뿜는 점착실로 잎사귀의 옷을 지어 준다.', '1.2m', '20.5kg', '벌레/풀', 75, 103, 80, 70, 80, 92, 542, 40, false),
 (898, 300, 1, '마디네', '지네포켓몬', '머리와 꼬리의 더듬이로 주변 상황을 살핀다. 성격이 매우 난폭하다.', '0.4m', '5.3kg', '벌레/독', 30, 45, 59, 30, 39, 57, 543, null, false),
 (899, 300, 2, '휠구', '눈썹지네포켓몬', '단단한 껍질로 보호되고 있다. 타이어처럼 회전하여 상대에게 격렬히 몸통박치기를 날린다.', '1.2m', '58.5kg', '벌레/독', 40, 55, 99, 40, 79, 47, 544, 22, false),
 (900, 300, 3, '펜드라', '메가지네포켓몬', '먹이를 목의 가시에 끼워 넣어 움직이지 못하게 한 후 맹독을 퍼뜨려 마무리한다.', '2.5m', '200.5kg', '벌레/독', 60, 100, 89, 55, 69, 112, 545, 30, false),
 (901, 301, 1, '소미안', '솜뭉치포켓몬', '솜을 날려 몸을 지킨다. 비에 젖으면 솜이 축축하고 무거워져 움직일 수 없게 된다.', '0.3m', '0.6kg', '풀/페어리', 40, 27, 60, 37, 50, 66, 546, null, false),
 (902, 301, 2, '엘풍', '바람숨기포켓몬', '민가에 몰래 들어가 소중한 물건을 감추거나 솜을 방 안에 여기저기 흩트러 놓는 성가신 존재이다.', '0.7m', '6.6kg', '풀/페어리', 60, 67, 85, 77, 75, 116, 547, null, true),
 (904, 302, 1, '치릴리', '뿌리포켓몬', '머리의 잎을 햇볕에 말려 달여 마시면 젊은 시절의 기력이 돌아온다며 노인에게 큰 인기다.', '0.5m', '6.6kg', '풀', 45, 35, 50, 70, 50, 30, 548, null, false),
 (905, 302, 2, '드레디어', '꽃장식포켓몬', '자란 흙의 성분에 따라 꽃향기는 조금씩 다르다. 냄새를 맡으면 마음이 치유되고 평온해진다.', '1.1m', '16.3kg', '풀', 70, 60, 75, 110, 75, 90, 549, null, true),
 (907, 303, 1, '배쓰나이', '흉포포켓몬', '난폭하고 사나운 포켓몬. 빨강과 파랑의 배쓰나이는 영역을 두고 언제나 싸운다.', '1m', '18kg', '물', 70, 92, 65, 80, 55, 98, 550, null, false),
 (910, 304, 1, '달막화', '달마포켓몬', '달막화의 배설물은 뜨거워서 옛날 사람은 품에 넣고 몸을 따뜻하게 하는 데 사용했다.', '0.6m', '37.5kg', '불꽃', 70, 90, 45, 15, 45, 50, 554, null, false),
 (911, 304, 2, '불비달마', '염상포켓몬', '격렬한 싸움으로 상처 입으면 바위처럼 굳어져 묵상하며 마음을 연마한다.', '1.3m', '92.9kg', '불꽃', 105, 140, 55, 30, 55, 95, 555, 35, false),
 (913, 305, 1, '마라카치', '선인장포켓몬', '템포가 빠른 춤과 소리로 꽃씨를 노리는 천적인 새포켓몬을 쫓아버린다.', '1m', '28kg', '풀', 75, 86, 67, 106, 67, 60, 556, null, false),
 (916, 306, 1, '돌살이', '돌집포켓몬', '적당한 돌을 찾아 구멍을 뚫어 살 곳을 만든다. 부서지면 대신할 돌을 찾을 때까지 불안해한다.', '0.3m', '14.5kg', '벌레/바위', 50, 65, 85, 35, 35, 55, 557, null, false),
 (917, 306, 2, '암팰리스', '바위집포켓몬', '무거운 바위를 등에 지고 며칠이고 건조한 땅을 이동할 수 있는 다릿심을 가지고 있다.', '1.4m', '200kg', '벌레/바위', 70, 105, 125, 65, 75, 45, 558, 34, false),
 (919, 307, 1, '곤율랭', '탈피포켓몬', '여러 마리 그룹으로 행동한다. 굼뜨게 다니다 눈이 마주친 상대에게 느닷없이 박치기를 한다.', '0.6m', '11.8kg', '악/격투', 50, 75, 70, 35, 70, 48, 559, null, false),
 (920, 307, 2, '곤율거니', '악당포켓몬', '거칠고 난폭하지만, 자신의 가족과 무리 동료의 영역을 매우 소중히 여기는 포켓몬이다.', '1.1m', '30kg', '악/격투', 65, 90, 115, 45, 115, 58, 560, 39, false),
 (922, 308, 1, '심보러', '흡사새포켓몬', '고대 도시의 수호신이었다. 자기 영역을 침범한 상대를 사이코 파워로 공격한다.', '1.4m', '14kg', '에스퍼/비행', 72, 58, 80, 103, 80, 97, 561, null, false),
 (925, 309, 1, '데스마스', '영혼포켓몬', '무덤에 매장된 사람의 영혼이 포켓몬으로 변했다. 죽기 전 기억이 남아 있다.', '0.5m', '1.5kg', '고스트', 38, 30, 85, 55, 65, 30, 562, null, false),
 (926, 309, 2, '데스니칸', '관포켓몬', '가까이 다가온 인간을 삼켜서 미라로 만든다는 소문이 있다. 금괴를 즐겨 먹는다.', '1.7m', '76.5kg', '고스트', 58, 50, 145, 95, 105, 30, 563, 34, false),
 (928, 310, 1, '프로토가', '옛날거북포켓몬', '고대 화석에서 부활했다. 바다에 살고 있었지만, 먹이를 찾아 지상으로 올라왔다.', '0.7m', '16.5kg', '물/바위', 54, 78, 103, 53, 45, 22, 564, null, false),
 (929, 310, 2, '늑골라', '옛날거북포켓몬', '턱의 힘이 무시무시하다. 암스타나 암나이트의 껍질도 아무렇지 않게 통째로 먹었다.', '1.2m', '81kg', '물/바위', 74, 108, 133, 83, 65, 32, 565, 37, false),
 (931, 311, 1, '아켄', '최초새포켓몬', '모든 새포켓몬의 선조라고 여겨져 왔지만 최근 연구에서는 아니라는 설도 대두되었다.', '0.5m', '9.5kg', '바위/비행', 55, 112, 45, 74, 45, 70, 566, null, false),
 (932, 311, 2, '아케오스', '최초새포켓몬', '깃털이 매우 가늘어 숙련된 장인이 아니면 복원에 실패한다고 전해지는 고대의 포켓몬.', '1.4m', '32kg', '바위/비행', 75, 140, 65, 112, 65, 110, 567, 37, false),
 (934, 312, 1, '깨봉이', '쓰레기봉투포켓몬', '숨을 쉬면 독가스가 새어 나온다. 냄새를 맡고 질뻐기가 침을 흘리며 찾아온다.', '0.6m', '31kg', '독', 50, 50, 62, 40, 62, 65, 568, null, false),
 (935, 312, 2, '더스트나', '쓰레기장포켓몬', '왼쪽 팔로 적을 꼭 붙들고 독액을 온몸에 퍼부어 움직임을 막는다.', '1.9m', '107.3kg', '독', 80, 95, 82, 60, 82, 75, 569, 36, false),
 (937, 313, 1, '조로아', '나쁜여우포켓몬', '겁이 많은 포켓몬으로 동료와 있을 때 말고는 거의 다른 누군가로 둔갑하고 있다.', '0.7m', '12.5kg', '악', 40, 65, 40, 80, 40, 65, 570, null, false),
 (938, 313, 2, '조로아크', '요괴여우포켓몬', '둔갑술이 가능할 뿐만 아니라 수백 명의 사람에게 환상을 보여줄 수 있는 힘을 가졌다.', '1.6m', '81.1kg', '악', 60, 105, 60, 120, 60, 105, 571, 30, false),
 (940, 314, 1, '치라미', '친칠라포켓몬', '결벽증이 있어서 조금의 더러움도 용서하지 않는다. 꼬리를 걸레 삼아 꼼꼼히 더러운 것을 닦아 낸다.', '0.4m', '5.8kg', '노말', 55, 50, 40, 40, 40, 75, 572, null, false),
 (941, 314, 2, '치라치노', '스카프포켓몬', '하얀 털은 몸에서 나오는 기름으로 코팅되어 적의 공격도 매끄럽게 피한다.', '0.5m', '7.5kg', '노말', 75, 95, 60, 65, 60, 115, 573, null, true),
 (943, 315, 1, '고디탱', '응시포켓몬', '리본 모양의 더듬이로 사이코 파워를 증폭시킨다. 무언가를 가만히 바라보고 있다.', '0.4m', '5.8kg', '에스퍼', 45, 30, 50, 55, 65, 45, 574, null, false),
 (944, 315, 2, '고디보미', '조작포켓몬', '별빛이 힘의 원천이다. 밤이 되면 사이코 파워로 돌을 띄워 별의 배치를 표시한다.', '0.7m', '18kg', '에스퍼', 60, 45, 70, 75, 85, 55, 575, 32, false),
 (945, 315, 3, '고디모아젤', '천체포켓몬', '강력한 사이코 파워의 영향으로 고디모아젤 주변 공간이 비틀어져 몇만 광년이나 떨어진 하늘의 별이 비친다.', '1.5m', '44kg', '에스퍼', 70, 55, 95, 95, 110, 65, 576, 41, false),
 (946, 316, 1, '유니란', '세포포켓몬', '몸이 특수한 액체로 둘러싸여 있어 어떤 곤란한 상황이라도 문제없다.', '0.3m', '1kg', '에스퍼', 45, 30, 40, 105, 50, 20, 577, null, false),
 (947, 316, 2, '듀란', '분할포켓몬', '둘로 분열된 뇌를 가지고 있어서 갑자기 다른 행동을 취할 때가 있다.', '0.6m', '8kg', '에스퍼', 65, 40, 50, 125, 60, 30, 578, 32, false),
 (948, 316, 3, '란쿨루스', '증폭포켓몬', '발휘한 사이코 파워를 사용해 특수한 액체로 만들어진 팔을 조종해서 바위를 부순다.', '1m', '20.1kg', '에스퍼', 110, 65, 75, 125, 85, 30, 579, 41, false),
 (949, 317, 1, '꼬지보리', '물새포켓몬', '상대에게 공격당하면 전신의 깃털에서 물보라를 내뿜는다. 물안개에 숨어들어 도망친다.', '0.5m', '5.5kg', '물/비행', 62, 44, 50, 44, 50, 55, 580, null, false),
 (950, 317, 2, '스완나', '백조포켓몬', '우아한 외모와 다르게 힘찬 날갯짓으로 수천 km를 계속 날 수 있다.', '1.3m', '24.2kg', '물/비행', 75, 87, 63, 87, 63, 98, 581, 35, false),
 (952, 318, 1, '사철록', '계절포켓몬', '계절이 바뀌었을 때뿐 아니라 기온이나 습도에 따라서도 몸의 색깔은 조금 변한다.', '0.6m', '19.5kg', '노말/풀', 60, 60, 50, 40, 50, 75, 585, null, false),
 (953, 318, 2, '바라철록', '계절포켓몬', '계절에 따라 거처를 바꾼다. 사람들은 바라철록의 뿔에서 계절의 변화를 느낀다.', '1.9m', '92.5kg', '노말/풀', 80, 100, 70, 60, 70, 95, 586, 34, false),
 (955, 319, 1, '에몽가', '하늘다람쥐포켓몬', '전기를 모아 하늘을 난다. 천둥이 치는 한밤중에는 하늘을 가득 메울 정도로 많다.', '0.4m', '5kg', '전기/비행', 55, 75, 60, 75, 60, 103, 587, null, false),
 (958, 320, 1, '딱정곤', '덥석물기포켓몬', '쪼마리와 함께 있을 때 전기적인 자극을 받으면 진화하는 이상한 포켓몬이다.', '0.5m', '5.9kg', '벌레', 50, 75, 45, 40, 45, 60, 588, null, false),
 (959, 320, 2, '슈바르고', '기병포켓몬', '쪼마리에게서 뺏은 껍질로 몸을 에워싸 가드하면서 2개의 창으로 찔러온다.', '1m', '33kg', '벌레/강철', 70, 135, 105, 60, 105, 20, 589, 25, false),
 (961, 321, 1, '깜놀버슬', '버섯포켓몬', '몬스터볼을 닮은 무늬로 유인한 후 독 포자를 뿌려댄다. 왜 닮았는지는 불가사의다.', '0.2m', '1kg', '풀/독', 69, 55, 45, 55, 55, 15, 590, null, false),
 (962, 321, 2, '뽀록나', '버섯포켓몬', '몬스터볼 무늬의 삿갓을 보여주며 먹이를 유인하려 하지만 속아 넘어가는 포켓몬은 드물다.', '0.6m', '10.5kg', '풀/독', 114, 85, 70, 85, 80, 30, 591, 39, false),
 (964, 322, 1, '탱그릴', '부유포켓몬', '베일 같은 손발을 휘감아 헤엄치는 먹이를 심해로 끌고 간다.', '1.2m', '33kg', '물/고스트', 55, 40, 50, 65, 85, 40, 592, null, false),
 (965, 322, 2, '탱탱겔', '부유포켓몬', '여객선이나 유조선 주위를 맴돌며 먹이를 끌어들이기 위해 노리고 있다.', '2.2m', '135kg', '물/고스트', 100, 60, 70, 85, 105, 60, 593, 40, false),
 (967, 323, 1, '맘복치', '돌보기포켓몬', '어부가 긴 항해를 할 때 데려간다. 맘복치가 있으면 의사도 약도 필요 없기 때문이다.', '1.2m', '31.6kg', '물', 165, 75, 80, 40, 45, 65, 594, null, false),
 (970, 324, 1, '철시드', '가시열매포켓몬', '위험을 감지하면 가시를 일제히 발사하여 반격한다. 그 틈에 몸을 굴려 도망간다.', '0.6m', '18.8kg', '풀/강철', 44, 50, 91, 24, 86, 10, 597, null, false),
 (971, 324, 2, '너트령', '가시공포켓몬', '3개의 촉수를 세게 내리치고 거기에 가시를 날려 상대를 흔적도 없이 분쇄한다.', '1m', '110kg', '풀/강철', 74, 94, 131, 54, 116, 20, 598, 40, false),
 (973, 325, 1, '리그레', '브레인포켓몬', '무시무시한 사이코 파워를 조종한다. 우주인 목격 정보의 대부분은 리그레를 보고 착각한 것이다.', '0.5m', '9kg', '에스퍼', 55, 55, 55, 85, 55, 30, 605, null, false),
 (974, 325, 2, '벰크', '브레인포켓몬', '사이코 파워로 상대 기억을 바꿔 버린다. 당신도 이미 바뀐 기억일지도 모른다.', '1m', '34.5kg', '에스퍼', 75, 75, 75, 125, 95, 40, 606, 42, false),
 (976, 326, 1, '불켜미', '양초포켓몬', '빛을 밝혀 길 안내를 하는 것처럼 가장하여 생명력을 빨아들이고 있다.', '0.3m', '3.1kg', '고스트/불꽃', 50, 30, 55, 65, 55, 20, 607, null, false),
 (977, 326, 2, '램프라', '램프포켓몬', '영혼을 빨아들여 불을 밝힌다. 사람이 죽는 것을 기다리기 위해 병원을 서성거리게 되었다.', '0.6m', '13kg', '고스트/불꽃', 60, 40, 60, 95, 60, 55, 608, 41, false),
 (978, 326, 3, '샹델라', '권유포켓몬', '샹델라의 불꽃에 둘러싸이면 영혼이 빨려가 불타버린다. 빈 껍데기인 몸만 남는다.', '1m', '34.3kg', '고스트/불꽃', 60, 55, 90, 145, 90, 80, 609, null, true),
 (979, 327, 1, '터검니', '이빨포켓몬', '나무열매를 이빨로 깨물어 먹는다. 이빨이 몇 차례에 걸쳐 새로 나면 강하고 날카로워진다.', '0.6m', '18kg', '드래곤', 46, 87, 60, 30, 40, 57, 610, null, false),
 (980, 327, 2, '액슨도', '도끼턱포켓몬', '큰 바위를 부수는 이빨을 가지고 있다. 액슨도들의 영역 싸움은 매우 격렬하다.', '1m', '36kg', '드래곤', 66, 117, 70, 40, 50, 67, 611, 38, false),
 (981, 327, 3, '액스라이즈', '도끼턱포켓몬', '상냥한 성격이지만 영역을 어지럽히는 자는 용서하지 않는다. 철을 자르는 이빨로 덤벼든다.', '1.8m', '105.5kg', '드래곤', 76, 147, 90, 60, 70, 97, 612, 48, false),
 (982, 328, 1, '프리지오', '결정포켓몬', '눈구름 속에서 태어났다. 얼음 결정으로 만들어진 사슬로 먹이를 잡는다.', '1.1m', '148kg', '얼음', 80, 50, 50, 95, 135, 105, 615, null, false),
 (985, 329, 1, '쪼마리', '달팽이포켓몬', '딱정곤과 함께 있을 때 전기적인 자극을 받으면 서로의 몸이 진화한다.', '0.4m', '7.7kg', '벌레', 50, 40, 85, 40, 65, 25, 616, null, false),
 (986, 329, 2, '어지리더', '탈껍질포켓몬', '무거운 껍데기를 벗었기 때문에 몸이 가벼워졌다. 마치 닌자 같은 몸놀림으로 싸운다.', '0.8m', '25.3kg', '벌레', 80, 70, 40, 100, 60, 145, 617, 25, false),
 (988, 330, 1, '메더', '트랩포켓몬', '피부가 단단해서 씨름꾼에게 밟혀도 아무렇지 않다. 전기를 흘려보낼 때 웃는 얼굴이 된다.', '0.7m', '11kg', '땅/전기', 109, 66, 84, 81, 99, 32, 618, null, false),
 (991, 331, 1, '비조푸', '무술포켓몬', '아침에 느릿느릿 움직이며 여러 포즈를 취하는 무리의 모습을 볼 수 있다.', '0.9m', '20kg', '격투', 45, 85, 50, 55, 50, 65, 619, null, false),
 (992, 331, 2, '비조도', '무술포켓몬', '연속 공격으로 상대를 압도한다. 마무리는 느긋하게 힘을 모아 일격을 가한다.', '1.4m', '35.5kg', '격투', 65, 125, 60, 95, 60, 105, 620, 50, false),
 (994, 332, 1, '크리만', '동굴포켓몬', '빨간 얼굴의 피부는 바위보다 딱딱하다. 좁은 동굴 안에서 적을 향해 얼굴로 돌격한다.', '1.6m', '139kg', '드래곤', 77, 120, 90, 60, 90, 48, 621, null, false),
 (997, 333, 1, '골비람', '골렘포켓몬', '수수께끼의 에너지로 활동한다. 고대부터 계속 움직였기 때문에 슬슬 파워가 다할 때가 됐을지도 모른다.', '1m', '92kg', '땅/고스트', 59, 74, 50, 35, 50, 35, 622, null, false),
 (998, 333, 2, '골루그', '골렘포켓몬', '고대인이 노동력으로 활용하기 위해 골루그를 발명했다고 전해진다. 주인의 명령에 충실하다.', '2.8m', '330kg', '땅/고스트', 89, 124, 80, 55, 80, 55, 623, 43, false),
 (1000, 334, 1, '자망칼', '날붙이포켓몬', '먹이를 베어 가른 후에는 기와 돌로 칼날을 간다. 자망칼마다 좋아하는 돌이 있다.', '0.5m', '10.2kg', '악/강철', 45, 85, 70, 40, 40, 60, 624, null, false),
 (1001, 334, 2, '절각참', '도인포켓몬', '아무리 강한 절각참이라도 머리의 칼날의 이가 빠지면 보스의 자리를 은퇴한다고 한다.', '1.6m', '70kg', '악/강철', 65, 125, 100, 60, 70, 70, 625, 52, false),
 (1003, 335, 1, '버프론', '박치기소포켓몬', '무작정 돌진하여 박치기를 한다. 달리고 있는 열차를 탈선시킬 정도의 파괴력이다.', '1.6m', '94.6kg', '노말', 95, 110, 95, 40, 95, 55, 626, null, false),
 (1006, 336, 1, '벌차이', '기저귀포켓몬', '해골은 버랜지나가 준다. 날개가 짧아 아직 날지 못하지만, 넓은 하늘을 꿈꾸며 뛰어오른다.', '0.5m', '9kg', '악/비행', 70, 55, 75, 45, 65, 60, 629, null, false),
 (1007, 336, 2, '버랜지나', '뼈독수리포켓몬', '먹은 먹이의 뼈를 사용해 솜씨 좋게 둥지를 만든다. 대부분의 뼈는 탕구리의 것이다.', '1.2m', '39.5kg', '악/비행', 110, 65, 105, 55, 95, 80, 630, 54, false),
 (1009, 337, 1, '앤티골', '개미핥기포켓몬', '뜨겁게 타오르는 불꽃의 혀로 아이앤트의 강철 몸을 녹여서 알맹이를 먹어치운다.', '1.4m', '58kg', '불꽃', 85, 97, 66, 105, 66, 65, 631, null, false),
 (1012, 338, 1, '아이앤트', '철개미포켓몬', '천적인 앤티골에 대해서 모두와 역할 분담을 하면서 반격해 둥지에서 쫓아낸다.', '0.3m', '33kg', '벌레/강철', 58, 109, 112, 48, 48, 109, 632, null, false),
 (1015, 339, 1, '모노두', '폭거포켓몬', '눈이 보이지 않아서 몸통박치기나 물기로 주변을 살핀다. 몸에 상처가 끊이지 않는다.', '0.8m', '17.3kg', '악/드래곤', 52, 65, 50, 45, 50, 38, 633, null, false),
 (1016, 339, 2, '디헤드', '흉포포켓몬', '2개의 머리는 사이가 나빠서 상대보다 많이 먹는 것으로 주도권을 잡으려고 한다.', '1.4m', '50kg', '악/드래곤', 72, 85, 70, 65, 70, 58, 634, 50, false),
 (1017, 339, 3, '삼삼드래', '난폭포켓몬', '양팔에 있는 머리에는 뇌가 없다. 3개의 머리로 모든 것을 먹어치워 파괴해 버린다.', '1.8m', '160kg', '악/드래곤', 92, 105, 90, 125, 90, 98, 635, 64, false),
 (1018, 340, 1, '활화르바', '횃불포켓몬', '5개의 뿔에서 불꽃을 뿜어내 상대와 싸운다. 그 온도는 최대 3000도에 달한다.', '1.1m', '28.8kg', '벌레/불꽃', 55, 85, 55, 50, 55, 60, 636, null, false),
 (1019, 340, 2, '불카모스', '태양포켓몬', '불꽃의 인분을 흩뿌리며 날아다닌다. 고대 사람들은 태양의 분노라고 부르며 두려워했다.', '1.6m', '46kg', '벌레/불꽃', 85, 60, 65, 135, 105, 100, 637, 59, false),
 (1021, 341, 1, '코바르온', '철심포켓몬', '강철의 몸과 마음을 지녔다. 째려보기만 해도 난폭한 포켓몬마저도 따르게 된다.', '2.1m', '250kg', '강철/격투', 91, 90, 129, 90, 72, 108, 638, null, false),
 (1024, 342, 1, '테라키온', '암굴포켓몬', '거대한 성벽을 일격에 돌파할 만한 돌진력을 가졌다. 전설로 전해지는 포켓몬이다.', '1.9m', '260kg', '바위/격투', 91, 129, 90, 72, 90, 108, 639, null, false),
 (1027, 343, 1, '비리디온', '초원포켓몬', '머리의 뿔은 날카로운 칼날이다. 회오리바람과 같은 움직임으로 상대를 농락하여 재빠르게 벤다.', '2m', '200kg', '풀/격투', 91, 90, 72, 90, 129, 108, 640, null, false),
 (1030, 344, 1, '토네로스', '선풍포켓몬', '구름처럼 생긴 에너지체에 하반신이 둘러싸여 있다. 시속 300km로 하늘을 난다.', '1.5m', '63kg', '비행', 79, 115, 70, 125, 80, 111, 641, null, false),
 (1033, 345, 1, '볼트로스', '뇌격포켓몬', '꼬리의 가시에서 전격을 날린다. 하나지방의 하늘을 날아다니며 번개를 내리친다.', '1.5m', '61kg', '전기/비행', 79, 115, 70, 125, 80, 111, 642, null, false),
 (1036, 346, 1, '레시라무', '백양포켓몬', '불꽃으로 세상을 태워버릴 수 있는 전설의 포켓몬. 진실의 세계를 구축하는 사람을 도와준다.', '3.2m', '330kg', '드래곤/불꽃', 100, 120, 100, 150, 120, 90, 643, null, false),
 (1039, 347, 1, '제크로무', '흑음포켓몬', '번개로 세상을 태워버릴 수 있는 전설의 포켓몬. 이상의 세계를 구축하는 사람을 보좌한다.', '2.9m', '345kg', '드래곤/전기', 100, 150, 120, 120, 100, 90, 644, null, false),
 (1042, 348, 1, '랜드로스', '풍요포켓몬', '랜드로스가 찾아온 땅에는 작물에 열매가 많이 열리기 때문에 농지의 신이라고 전해진다.', '1.5m', '68kg', '땅/비행', 89, 125, 90, 115, 80, 101, 645, null, false),
 (1045, 349, 1, '큐레무', '경계포켓몬', '잃어버린 몸을 진실과 이상으로 채워줄 영웅을 기다리는 얼음의 전설 포켓몬.', '3m', '325kg', '드래곤/얼음', 125, 130, 90, 130, 90, 95, 646, null, false),
 (1048, 350, 1, '케르디오', '망아지포켓몬', '바다나 강 등의 수면을 달려 세계 곳곳을 뛰어다닌다. 아름다운 물가에 나타난다.', '1.4m', '48.5kg', '물/격투', 91, 72, 90, 129, 90, 108, 647, null, false),
 (1051, 351, 1, '게노세크트', '고생대포켓몬', '플라스마단에게 개조당한 고대의 벌레포켓몬이다. 등에 있는 대포의 파워가 올라갔다.', '1.5m', '82.5kg', '벌레/강철', 71, 120, 95, 120, 95, 99, 649, null, false),
 (1054, 352, 1, '도치마론', '밤송이포켓몬', '머리의 가시는 평소에는 부드럽지만 힘을 주면 뾰족하고 날카로워지며 바위를 뚫어 버릴 정도로 단단해진다.', '0.4m', '9kg', '풀', 56, 61, 65, 48, 45, 38, 650, null, false),
 (1055, 352, 2, '도치보구', '가시갑옷포켓몬', '몸을 둘러싼 단단한 껍질이 적의 공격을 튕겨내고 날카로운 가시로 반격한다.', '0.7m', '29kg', '풀', 61, 78, 95, 56, 58, 57, 651, 16, false),
 (1056, 352, 3, '브리가론', '가시갑옷포켓몬', '몸통박치기로 50톤 전차를 뒤집는 파워를 지녔다. 자신이 방패가 되어 동료를 지킨다.', '1.6m', '90kg', '풀/격투', 88, 107, 122, 74, 75, 64, 652, 36, false),
 (1057, 353, 1, '푸호꼬', '여우포켓몬', '잔가지를 먹으면 힘이 나서 섭씨 200도가 넘는 열기를 커다란 귀에서 내뿜는다.', '0.4m', '9.4kg', '불꽃', 40, 45, 40, 62, 60, 60, 653, null, false),
 (1058, 353, 2, '테르나', '여우포켓몬', '나뭇가지를 꼬리에 꽂고 있다. 꼬리털의 마찰열로 가지에 불을 붙여 싸운다.', '1m', '14.5kg', '불꽃', 59, 59, 58, 90, 70, 73, 654, 16, false),
 (1059, 353, 3, '마폭시', '여우포켓몬', '지팡이 끝의 타오르는 불꽃을 바라보며 정신을 통일하면 미래에 일어날 일을 내다볼 수 있다.', '1.5m', '39kg', '불꽃/에스퍼', 75, 69, 72, 114, 100, 104, 655, 36, false),
 (1060, 354, 1, '개구마르', '거품개구리포켓몬', '가슴과 등에서 거품을 내뿜는다. 탄력 있는 거품으로 공격을 막아내고 데미지를 줄인다.', '0.3m', '7kg', '물', 41, 56, 40, 62, 44, 71, 656, null, false),
 (1061, 354, 2, '개굴반장', '거품개구리포켓몬', '거품으로 싸인 돌멩이를 던지는 기술을 쓴다. 30m 앞에 있는 빈 캔을 맞힐 정도로 컨트롤이 좋다.', '0.6m', '10.9kg', '물', 54, 63, 52, 83, 56, 97, 657, 16, false),
 (1062, 354, 3, '개굴닌자', '시노비포켓몬', '물을 압축시켜 수리검을 만들어 낸다. 고속으로 회전시키며 던지면 금속도 두 동강이 난다.', '1.5m', '40kg', '물/악', 72, 95, 67, 103, 71, 122, 658, 36, false),
 (1063, 355, 1, '파르빗', '땅구멍파기포켓몬', '커다란 귀로 땅을 파고 보금자리를 만든다. 하룻밤 동안 쉬지 않고 계속 팔 수 있다.', '0.4m', '5kg', '노말', 38, 36, 38, 32, 36, 57, 659, null, false),
 (1064, 355, 2, '파르토', '땅구멍파기포켓몬', '커다란 귀에는 무게가 1톤을 넘는 바위를 가뿐히 들어 올릴 만한 파워가 있다. 공사 현장에서 대활약한다.', '1m', '42.4kg', '노말/땅', 85, 56, 77, 50, 77, 78, 660, 20, false),
 (1066, 356, 1, '화살꼬빈', '울새포켓몬', '사람을 잘 따르는 포켓몬이지만, 억지로 만지면 몸을 단숨에 발열시켜 화상을 입는다.', '0.3m', '1.7kg', '노말/비행', 45, 50, 43, 40, 38, 62, 661, null, false),
 (1067, 356, 2, '불화살빈', '불티포켓몬', '풀숲에 불꽃을 흩뿌린다. 불꽃에 놀라 뛰쳐나온 벌레포켓몬을 덥석 먹어 치운다.', '0.7m', '16kg', '불꽃/비행', 62, 73, 55, 56, 52, 84, 662, 17, false),
 (1068, 356, 3, '파이어로', '열화포켓몬', '날개는 불이 붙지 않고 튼튼하다. 옛날에는 소방관들의 옷을 파이어로의 날개로 만들었다.', '1.2m', '24.5kg', '불꽃/비행', 78, 81, 71, 74, 69, 126, 663, 35, false),
 (1069, 357, 1, '분이벌레', '가루뿜기포켓몬', '새포켓몬에게 습격당하면 검은 가루를 흩뿌린다. 만지면 마비되는 독가루다.', '0.3m', '2.5kg', '벌레', 38, 35, 40, 27, 25, 35, 664, null, false),
 (1070, 357, 2, '분떠도리', '가루뿜기포켓몬', '수풀의 그늘에 숨어 산다. 적에게 공격당하면 몸의 털을 뾰족하게 곤두세우며 위협한다.', '0.3m', '8.4kg', '벌레', 45, 22, 60, 27, 30, 29, 665, 9, false),
 (1071, 357, 3, '비비용', '인분포켓몬', '세계에는 다양한 무늬의 날개를 가진 비비용이 있다. 살고 있는 곳의 기후에 영향을 받는 것 같다.', '1.2m', '17kg', '벌레/비행', 80, 52, 50, 90, 50, 89, 666, 12, false),
 (1072, 358, 1, '레오꼬', '어린사자포켓몬', '어릴 때는 동료와 무리를 이룬다. 스스로 먹이를 사냥할 수 있게 되면 무리에서 쫓겨나 독립한다.', '0.6m', '13.5kg', '불꽃/노말', 62, 50, 58, 73, 54, 72, 667, null, false),
 (1073, 358, 2, '화염레오', '임금포켓몬', '수컷은 평소에 빈둥거리지만, 강적이 덤벼들면 자신을 돌보지 않고 동료를 지킨다.', '1.5m', '81.5kg', '불꽃/노말', 86, 68, 72, 109, 66, 106, 668, 35, false),
 (1075, 359, 1, '플라베베', '한송이포켓몬', '꽃의 힘이 없으면 위험하다. 그래도 좋아하는 색과 형태를 찾을 때까지 여행을 계속한다.', '0.1m', '0.1kg', '페어리', 44, 38, 39, 61, 79, 42, 669, null, false),
 (1076, 359, 2, '플라엣테', '한송이포켓몬', '꽃을 길러 자신의 무기로 이용한다. 아름답게 핀 꽃일수록 강력한 파워를 간직하고 있다.', '0.2m', '0.9kg', '페어리', 54, 45, 47, 75, 98, 52, 670, 19, false),
 (1077, 359, 3, '플라제스', '가든포켓몬', '기른 꽃들을 조종한다. 플라제스가 발산하는 꽃보라는 아름다움도 파워도 압도적이다.', '1.1m', '10kg', '페어리', 78, 65, 68, 112, 154, 75, 671, null, true),
 (1078, 360, 1, '메이클', '라이드포켓몬', '사람과 살기 시작한 최초의 포켓몬이라고 한다. 온화한 성격의 포켓몬이다.', '0.9m', '31kg', '풀', 66, 65, 48, 62, 57, 52, 672, null, false),
 (1079, 360, 2, '고고트', '라이드포켓몬', '뿔을 잡을 때 느껴지는 작은 차이로 트레이너의 마음을 읽어낼 수 있기에 하나가 되어 달릴 수 있는 것이다.', '1.7m', '91kg', '풀', 123, 100, 62, 97, 81, 68, 673, 32, false),
 (1081, 361, 1, '판짱', '개구쟁이포켓몬', '부란다의 뒤를 부하처럼 따라다닌다. 큰 실패를 하면 잎사귀를 빼앗겨 버린다.', '0.6m', '8kg', '격투', 67, 82, 62, 46, 48, 43, 674, null, false),
 (1082, 361, 2, '부란다', '무서운얼굴포켓몬', '완력을 뽐내는 와일드한 포켓몬. 호쾌한 성질에 반하는 트레이너도 많다.', '2.1m', '136kg', '격투/악', 95, 124, 78, 69, 71, 58, 675, 32, false),
 (1084, 362, 1, '트리미앙', '푸들포켓몬', '털을 얼마나 아름답게 커트하는지 귀족들 사이에서 경쟁하던 시대가 있었다.', '1.2m', '28kg', '노말', 75, 80, 60, 65, 90, 102, 676, null, false),
 (1087, 363, 1, '냐스퍼', '자제포켓몬', '강력한 사이코 파워가 새어 나가지 않도록 방출되는 기관을 귀로 막고 있다.', '0.3m', '3.5kg', '에스퍼', 62, 48, 54, 63, 60, 68, 677, null, false),
 (1088, 363, 2, '냐오닉스', '억제포켓몬', '위험이 다가오면 귀를 들어 올리고 10톤 트럭을 눌러 부술 정도의 사이코 파워를 방출한다.', '0.6m', '8.5kg', '에스퍼', 74, 48, 76, 83, 81, 104, 678, 25, false),
 (1090, 364, 1, '단칼빙', '도검포켓몬', '죽은 자의 혼이 고대의 검에 깃들어 태어났다고 한다. 사람에게 씌어 생명을 빨아들인다.', '0.8m', '2kg', '강철/고스트', 45, 80, 100, 35, 37, 28, 679, null, false),
 (1091, 364, 2, '쌍검킬', '도검포켓몬', '진화하여 2자루로 분열되었다. 텔레파시로 서로 대화하며 연계 공격으로 적을 조각낸다.', '0.8m', '4.5kg', '강철/고스트', 59, 110, 150, 45, 49, 35, 680, 35, false),
 (1092, 364, 3, '킬가르도', '왕검포켓몬', '역대 왕들이 데리고 있었다. 영험한 힘으로 사람이나 포켓몬의 마음을 조종하여 복종하게 한다.', '1.7m', '53kg', '강철/고스트', 60, 50, 140, 50, 140, 60, 681, null, true),
 (1093, 365, 1, '나룸퍼프', '솜사탕포켓몬', '솜사탕 같은 달고 끈적끈적한 하얀 실을 내뿜어 상대를 휘감고 움직이지 못하게 한다.', '0.4m', '3.5kg', '페어리', 62, 48, 66, 59, 57, 49, 684, null, false),
 (1094, 365, 2, '나루림', '휩포켓몬', '아주 약간의 냄새도 구별할 수 있는 민감한 후각을 살려 파티시에를 돕고 있다.', '0.8m', '5kg', '페어리', 82, 80, 86, 85, 75, 72, 685, 25, false),
 (1096, 366, 1, '오케이징', '회전포켓몬', '빛을 깜박여 먹이를 꾀어내고 긴 촉수로 포박하여 움직이지 못하게 한다.', '0.4m', '3.5kg', '악/에스퍼', 53, 54, 53, 37, 46, 45, 686, null, false),
 (1097, 366, 2, '칼라마네로', '역전포켓몬', '강력한 최면술을 사용한다. 그것을 이용해 못된 짓을 하는 자들이 끊이지 않는다.', '1.5m', '47kg', '악/에스퍼', 86, 92, 88, 68, 75, 73, 687, 30, false),
 (1099, 367, 1, '거북손손', '두손포켓몬', '2마리의 거북손손이 하나의 바위에서 산다. 서로 싸우면 한쪽이 다른 바위로 옮겨 간다.', '0.5m', '31kg', '바위/물', 42, 52, 67, 39, 56, 50, 688, null, false),
 (1100, 367, 2, '거북손데스', '집합포켓몬', '진화할 때 2마리의 거북손손이 7마리로 분열된 포켓몬이다. 7마리분의 파워로 싸운다.', '1.3m', '96kg', '바위/물', 72, 105, 115, 54, 86, 68, 689, 39, false),
 (1102, 368, 1, '수레기', '풀모방포켓몬', '수초 찌꺼기로 뒤범벅을 하고 큰 포켓몬에게 공격당하지 않도록 가만히 있다. 썩은 해초가 주요 먹이다.', '0.5m', '7.3kg', '독/물', 50, 60, 60, 60, 60, 30, 690, null, false),
 (1103, 368, 2, '드래캄', '풀모방포켓몬', '매우 흉포해서, 다가온 상대에게 독액을 내뿜는다. 무슨 이유에서인지 타타륜과만 매우 사이가 좋다.', '1.8m', '81.5kg', '독/드래곤', 65, 75, 90, 97, 123, 44, 691, 48, false),
 (1105, 369, 1, '완철포', '물대포포켓몬', '가끔 집게가 떨어지면 재생할 때까지 몰래 숨어 다닌다. 집게 속살은 매우 맛있다.', '0.5m', '8.3kg', '물', 50, 53, 62, 58, 63, 44, 692, null, false),
 (1106, 369, 2, '블로스터', '런처포켓몬', '빨아들인 물을 압축해 쏜다. 두꺼운 철판에 구멍을 뚫을 정도로 위력적이다.', '1.3m', '35.3kg', '물', 71, 73, 88, 120, 89, 59, 693, 37, false),
 (1108, 370, 1, '목도리키텔', '발전포켓몬', '사막에서 생활한다. 태양의 빛을 쬐고 발전하면 먹이를 먹지 않아도 괜찮다.', '0.5m', '6kg', '전기/노말', 44, 38, 33, 61, 43, 70, 694, null, false),
 (1109, 370, 2, '일레도리자드', '발전포켓몬', '목의 깃을 펼쳐 발전한다. 일레도리자드 1마리로 고층 빌딩에 필요한 전기를 만들어 낼 수 있다.', '1m', '21kg', '전기/노말', 62, 55, 52, 109, 94, 109, 695, null, true),
 (1111, 371, 1, '티고라스', '유군포켓몬', '큰 턱은 무시무시한 파괴력을 지녔다. 복원시켜도 당시와 같은 모습은 아니라는 설도 있다.', '0.8m', '26kg', '바위/드래곤', 58, 89, 77, 45, 45, 48, 696, null, false),
 (1112, 371, 2, '견고라스', '폭군포켓몬', '완전한 복원은 불가능해서 사실은 전신에 깃털 같은 털이 있을 것이라는 설도 있다.', '2.5m', '270kg', '바위/드래곤', 82, 121, 119, 69, 59, 71, 697, 39, false),
 (1114, 372, 1, '아마루스', '툰드라포켓몬', '고대에 차가운 토지에서 살았다. 아마루스가 울면 밤하늘에 오로라가 나타난다고 한다.', '1.3m', '25.2kg', '바위/얼음', 77, 59, 50, 67, 63, 46, 698, null, false),
 (1115, 372, 2, '아마루르가', '툰드라포켓몬', '빙산 안에 당시의 모습 그대로 얼어붙은 아마루르가가 발견되어 화제를 모았다.', '2.7m', '225kg', '바위/얼음', 123, 77, 72, 99, 92, 58, 699, 39, false),
 (1117, 373, 1, '님피아', '연결포켓몬', '한번 싸움이 나면 자신보다 몇 배나 큰 드래곤포켓몬에게도 전혀 기죽지 않고 덤벼든다.', '1m', '23.5kg', '페어리', 95, 65, 65, 110, 130, 60, 700, null, false),
 (1120, 374, 1, '루차불', '레슬링포켓몬', '빠른 기술로 상대를 압도한다. 필살기를 쓰기 위한 어필이 너무 길어서 위기에 처하기도 한다.', '0.8m', '21.5kg', '격투/비행', 78, 92, 75, 74, 63, 118, 701, null, false),
 (1123, 375, 1, '데덴네', '안테나포켓몬', '민가에 숨어들어 콘센트에서 전기를 훔친다. 전기료가 이상할 때는 이 녀석의 소행이다.', '0.2m', '2.2kg', '전기/페어리', 67, 58, 57, 81, 67, 101, 702, null, false),
 (1126, 376, 1, '멜리시', '보석포켓몬', '땅속 깊숙한 곳에는 멜리시의 무리와 그들의 여왕이 사는 보석의 나라가 있다고 한다.', '0.3m', '5.7kg', '바위/페어리', 50, 50, 150, 50, 150, 50, 703, null, false),
 (1129, 377, 1, '미끄메라', '연체포켓몬', '뿔로 주변의 상황을 살핀다. 매우 민감하여 잡으면 쇼크로 움직일 수 없게 된다.', '0.3m', '2.8kg', '드래곤', 45, 50, 35, 55, 75, 40, 704, null, false),
 (1130, 377, 2, '미끄네일', '연체포켓몬', '느릿느릿 기어서 이동한다. 나선의 돌기는 뇌와 내장으로 꽉 차 있다.', '0.8m', '17.5kg', '드래곤', 68, 75, 53, 83, 113, 60, 705, 40, false),
 (1131, 377, 3, '미끄래곤', '드래곤포켓몬', '매우 사람을 잘 따른다. 친밀해지면 끈적끈적한 점액투성이인 몸으로 끌어안으려 하지만 참아야 한다.', '2m', '150.5kg', '드래곤', 90, 100, 70, 110, 150, 80, 706, 50, false),
 (1132, 378, 1, '클레피', '열쇠꾸러미포켓몬', '왜 열쇠를 모으는지 알 수 없지만 주면 매우 기뻐한다. 단 마스터키만 좋아하는 것 같다.', '0.2m', '3kg', '강철/페어리', 57, 80, 91, 80, 87, 75, 707, null, false),
 (1135, 379, 1, '나목령', '그루터기포켓몬', '아이 목소리를 흉내 내어 사람을 숲 깊숙이 유인해 길을 잃게 한다. 자신의 동료로 삼을 생각이다.', '0.4m', '7kg', '고스트/풀', 43, 70, 48, 50, 60, 38, 708, null, false),
 (1136, 379, 2, '대로트', '고목포켓몬', '숲의 요괴라고 두려워했다. 나무꾼들은 대로트가 싫어하는 불꽃타입을 데리고 숲에 들어간다.', '1.5m', '71kg', '고스트/풀', 85, 110, 76, 65, 82, 56, 709, 25, false),
 (1138, 380, 1, '호바귀', '호박포켓몬', '성불하지 못한 혼을 호박으로 된 몸속에 담고 있다. 해가 지면 활동하기 시작한다.', '0.4m', '5kg', '고스트/풀', 49, 66, 70, 44, 55, 51, 710, null, false),
 (1139, 380, 2, '펌킨인', '호박포켓몬', '초승달이 뜬 밤에 기분 나쁜 목소리로 노래를 부르며 마을 안을 헤맨다. 그 노래를 들으면 저주를 받는다.', '0.9m', '12.5kg', '고스트/풀', 65, 90, 122, 58, 75, 84, 711, 25, false),
 (1141, 381, 1, '꽁어름', '얼음덩이포켓몬', '몸을 둘러싼 얼음이 적의 공격을 막는다. 깨져도 냉기로 재빨리 얼음을 얼린다.', '1m', '99.5kg', '얼음', 55, 69, 85, 32, 35, 28, 712, null, false),
 (1142, 381, 2, '크레베이스', '빙산포켓몬', '얼어붙은 몸은 강철처럼 단단하다. 앞을 가로막는 것을 커다란 몸으로 파괴하며 이동한다.', '2m', '505kg', '얼음', 95, 117, 184, 44, 46, 28, 713, 37, false),
 (1144, 382, 1, '음뱃', '음파포켓몬', '과일을 좋아한다. 초음파를 이용해서 잘 익은 것만 골라내 먹는 미식가다.', '0.5m', '8kg', '비행/드래곤', 40, 30, 35, 45, 40, 55, 714, null, false),
 (1145, 382, 2, '음번', '음파포켓몬', '성질은 난폭하지만 좋아하는 잘 익은 과일을 주면 언제 그랬냐는 듯이 잘 따른다.', '1.5m', '85kg', '비행/드래곤', 85, 70, 80, 97, 80, 123, 715, 48, false),
 (1147, 383, 1, '디안시', '보석포켓몬', '멜리시의 돌연변이다. 분홍빛으로 빛나는 몸은 세계에서 가장 아름답다고 일컬어진다.', '0.7m', '8.8kg', '바위/페어리', 50, 100, 150, 100, 150, 50, 719, null, false),
 (1150, 384, 1, '후파', '장난포켓몬', '진정한 모습일 때는 거대한 힘을 가지고 있다. 원하는 재물을 손에 넣기 위해 그것이 숨겨진 성을 통째로 빼돌려 사라졌다는 전설이 있다.', '0.5m', '9kg', '에스퍼/고스트', 80, 110, 60, 150, 130, 70, 720, null, false),
 (1153, 385, 1, '나몰빼미', '풀깃포켓몬', '칼같이 날카로운 날개를 날려 공격한다. 발의 힘도 강해 킥도 무시할 수 없다.', '0.3m', '1.5kg', '풀/비행', 68, 55, 55, 50, 50, 42, 722, null, false),
 (1154, 385, 2, '빼미스로우', '칼날깃포켓몬', '나르시스트로 깔끔한 걸 좋아한다. 자주 관리해 주지 않으면 말을 안 듣기도 한다.', '0.7m', '16kg', '풀/비행', 78, 75, 75, 70, 70, 52, 723, 17, false),
 (1155, 385, 3, '모크나이퍼', '화살깃포켓몬', '살깃을 시위에 메겨서 상대에게 날린다. 반드시 명중시켜야 할 때는 머리의 시위를 당겨 집중한다.', '1.6m', '36.6kg', '풀/고스트', 78, 107, 75, 100, 100, 70, 724, 34, false),
 (1156, 386, 1, '냐오불', '불고양이포켓몬', '집요하게 따라다니면 마음을 열지 않는다. 친밀해져도 과도한 스킨십은 금물이다.', '0.4m', '4.3kg', '불꽃', 45, 65, 40, 60, 40, 70, 725, null, false),
 (1157, 386, 2, '냐오히트', '불고양이포켓몬', '친해지면 트레이너에게도 응석 부리지만, 힘은 강하고 발톱도 날카롭다. 온몸을 상처투성이로 만든다.', '0.7m', '25kg', '불꽃', 65, 85, 50, 80, 50, 90, 726, 17, false),
 (1158, 386, 3, '어흥염', '힐포켓몬', '거칠고 제멋대로지만 약한 상대를 괴롭히는 것은 재미없어서 싫어한다. 강한 상대에게 의욕을 보인다.', '1.8m', '83kg', '불꽃/악', 95, 115, 90, 80, 90, 60, 727, 34, false),
 (1159, 387, 1, '누리공', '강치포켓몬', '코로 부풀리는 벌룬은 매일 연습을 반복하면서 조금씩 커진다.', '0.4m', '7.5kg', '물', 50, 54, 54, 66, 56, 40, 728, null, false),
 (1160, 387, 2, '키요공', '아이돌포켓몬', '모르는 댄스를 보면 흥분한다. 출 수 있을 때까지 열심히 연습하는 노력가다.', '0.6m', '17.5kg', '물', 60, 69, 69, 91, 81, 50, 729, 17, false),
 (1161, 387, 3, '누리레느', '솔리스트포켓몬', '누리레느에게 싸움은 스테이지다. 화려하게 노래하고 춤을 추며 먹이의 숨통을 끊는다.', '1.8m', '44kg', '물/페어리', 80, 74, 74, 126, 116, 60, 730, 34, false),
 (1162, 388, 1, '콕코구리', '딱따구리포켓몬', '딱딱한 부리로 나무를 쫀다. 쪼는 리듬으로 그때의 기분이나 상태를 대강 알 수 있다.', '0.3m', '1.2kg', '노말/비행', 35, 75, 30, 30, 30, 65, 731, null, false),
 (1163, 388, 2, '크라파', '나팔입포켓몬', '부리의 끝을 뒤로 젖혀 100가지 이상의 울음소리를 자유롭게 낼 수 있다.', '0.6m', '14.8kg', '노말/비행', 55, 85, 50, 40, 50, 75, 732, 14, false),
 (1164, 388, 3, '왕큰부리', '대포포켓몬', '동료와 부리를 부딪히며 커뮤니케이션한다. 부딪히는 강도나 횟수로 기분을 전달한다.', '1.1m', '26kg', '노말/비행', 80, 120, 75, 75, 75, 60, 733, 28, false),
 (1165, 389, 1, '영구스', '순회포켓몬', '긴 몸통은 거의 위장으로 이루어져 있다. 대식가여서 식비를 무시할 수 없다.', '0.4m', '6kg', '노말', 48, 70, 30, 30, 30, 45, 734, null, false),
 (1166, 389, 2, '형사구스', '잠복포켓몬', '원래 알로라에 없었지만, 옛날 꼬렛이 대량으로 발생했을 때 데려왔다.', '0.7m', '14.2kg', '노말', 88, 110, 60, 55, 60, 45, 735, 20, false),
 (1168, 390, 1, '턱지충이', '유충포켓몬', '혹시 소굴을 발견하더라도 손을 넣으면 안 된다. 싫어하는 턱지충이에게 물린다.', '0.4m', '4.4kg', '벌레', 47, 62, 45, 55, 45, 46, 736, null, false),
 (1169, 390, 2, '전지충이', '배터리포켓몬', '낙엽에 묻혀 거의 움직이지 않고 그저 부엽토만 먹는다. 잘못 밟으면 찌릿찌릿하다.', '0.5m', '10.5kg', '벌레/전기', 57, 82, 95, 55, 75, 36, 737, 20, false),
 (1170, 390, 3, '투구뿌논', '뿔집게포켓몬', '복부에 발전 기관을 갖고 있다. 큰 턱에 에너지를 모아 굉장한 전격을 쏜다.', '1.5m', '45kg', '벌레/전기', 77, 70, 90, 145, 75, 43, 738, null, true),
 (1171, 391, 1, '오기지게', '권투포켓몬', '딱딱한 집게는 공격과 수비에 모두 능하다. 오기지게끼리의 싸움은 복싱 같다.', '0.6m', '7kg', '격투', 47, 82, 57, 42, 47, 63, 739, null, false),
 (1172, 391, 2, '모단단게', '털게포켓몬', '집게 안에 냉기를 모아 때려눕힌다. 두꺼운 얼음벽도 가루로 만들어 버린다.', '1.7m', '180kg', '격투/얼음', 97, 132, 77, 62, 67, 43, 740, null, true),
 (1174, 392, 1, '춤추새', '댄스포켓몬', '정열적인 댄스로 적의 마음을 사로잡아 방심하게 한 후 타오르는 불꽃으로 태워버린다.', '0.6m', '3.4kg', '불꽃/비행', 75, 70, 70, 98, 70, 93, 741, null, false),
 (1177, 393, 1, '에블리', '재니등에포켓몬', '꽃의 꿀과 화분을 좋아한다. 꽃밭에서 먹이를 두고 버터플과 옥신각신한다.', '0.1m', '0.2kg', '벌레/페어리', 40, 45, 40, 55, 40, 84, 742, null, false),
 (1178, 393, 2, '에리본', '재니등에포켓몬', '화분이 축축해져서 비를 싫어한다. 구름의 움직임이 수상해지면 나무 구멍에서 움직이지 않는다.', '0.2m', '0.5kg', '벌레/페어리', 60, 55, 60, 95, 70, 124, 743, 25, false),
 (1180, 394, 1, '암멍이', '강아지포켓몬', '자라면서 거칠고 공격적으로 변한다. 감당이 안 돼서 버리는 트레이너도 적지 않다.', '0.5m', '9.2kg', '바위', 45, 65, 40, 30, 40, 60, 744, null, false),
 (1181, 394, 2, '루가루암', '늑대포켓몬', '바위로 된 갈기는 날카로운 나이프처럼 잘 잘린다. 천천히 먹이를 궁지로 몰아 약하게 만든 후 숨통을 끊는다.', '0.8m', '25kg', '바위', 75, 115, 65, 55, 65, 112, 745, 25, false),
 (1183, 395, 1, '약어리', '잔물고기포켓몬', '약해서 무리 지어 행동한다. 하지만 혼자 떨어져서 헤엄치는 모습도 자주 볼 수 있다.', '0.2m', '0.3kg', '물', 45, 20, 20, 25, 25, 40, 746, null, false),
 (1186, 396, 1, '시마사리', '깨비사리포켓몬', '코산호의 가지를 먹기 때문에 자연스럽게 떨어지는 가지를 모아 가공하는 장인들의 미움을 받고 있다.', '0.4m', '8kg', '독/물', 50, 53, 62, 43, 52, 45, 747, null, false),
 (1187, 396, 2, '더시마사리', '깨비사리포켓몬', '맹독의 가시를 날려서 적을 공격한다. 다가온 상대는 발톱으로 쓸어버린다.', '0.7m', '14.5kg', '독/물', 50, 63, 152, 53, 142, 35, 748, 38, false),
 (1189, 397, 1, '머드나기', '당나귀포켓몬', '진흙 놀이를 매우 좋아한다. 매일 진흙을 뒤집어쓰지 않으면 스트레스가 쌓여 말을 듣지 않게 된다.', '1m', '110kg', '땅', 70, 100, 70, 45, 55, 45, 749, null, false),
 (1190, 397, 2, '만마드', '만마포켓몬', '어떤 일에도 동요하지 않고 차분하다. 입에 머금은 흙과 침을 섞어 특수한 진흙을 만든다.', '2.5m', '920kg', '땅', 100, 125, 100, 55, 85, 35, 750, 30, false),
 (1192, 398, 1, '물거미', '수포포켓몬', '물거미끼리 만나면 머리의 수포를 자랑하며 어필한다. 작은 쪽이 뒤로 물러난다.', '0.3m', '4kg', '물/벌레', 38, 40, 52, 40, 72, 27, 751, null, false),
 (1193, 398, 2, '깨비물거미', '수포포켓몬', '평소에는 물 안에서 지낸다. 배가 부를 때는 숨통을 끊은 먹이를 머리의 수포에 넣어 둔다.', '1.8m', '82kg', '물/벌레', 68, 70, 92, 50, 132, 42, 752, 22, false),
 (1195, 399, 1, '짜랑랑', '풀사마귀포켓몬', '해가 뜨면 4장의 잎을 펼치고 일광욕한다. 머리끝에서 좋은 냄새가 난다.', '0.3m', '1.5kg', '풀', 40, 55, 35, 50, 35, 35, 753, null, false),
 (1196, 399, 2, '라란티스', '꽃사마귀포켓몬', '벌레포켓몬인 척하는 것은 몸을 지키기 위해서다. 양팔의 꽃잎은 예리해서 잘 자른다.', '0.9m', '18.5kg', '풀', 70, 105, 90, 80, 90, 45, 754, 34, false),
 (1198, 400, 1, '자마슈', '발광포켓몬', '빛이 나는 포자를 주변에 흩뿌린다. 위험하지만 자마슈가 사는 숲의 밤 여행 투어는 인기가 있다.', '0.2m', '1.5kg', '풀/페어리', 40, 35, 55, 65, 75, 15, 755, null, false),
 (1199, 400, 2, '마셰이드', '발광포켓몬', '먹이를 잠들게 하고 팔 끝으로 생기를 빼앗는다. 동료가 약해지면 생기를 보내 도와준다.', '1m', '11.5kg', '풀/페어리', 60, 45, 80, 90, 100, 30, 756, 24, false),
 (1201, 401, 1, '야도뇽', '독도마뱀포켓몬', '수컷은 거의 암컷의 지시에 따른다. 잡아 온 먹이도 거의 바치기 때문에 영양 부족으로 진화할 수 없다.', '0.6m', '4.8kg', '독/불꽃', 48, 44, 40, 71, 40, 77, 757, null, false),
 (1202, 401, 2, '염뉴트', '독도마뱀포켓몬', '동굴 깊은 곳에서 살며 페로몬으로 헤롱헤롱하게 만들어 야도뇽을 시중들게 한다.', '1.2m', '22.2kg', '독/불꽃', 68, 64, 60, 111, 60, 117, 758, 33, false),
 (1204, 402, 1, '포곰곰', '바둥바둥포켓몬', '큰 나무도 꺽을 만큼 힘이 세다. 엉덩이의 기관에서 냄새를 풍겨 동료와 커뮤니케이션을 한다.', '0.5m', '6.8kg', '노말/격투', 70, 75, 50, 45, 50, 50, 759, null, false),
 (1205, 402, 2, '이븐곰', '강한완력포켓몬', '손을 크게 휘두르는 것은 위협과 경계의 신호다. 재빨리 도망치지 않으면 목숨을 보장할 수 없다.', '2.1m', '135kg', '노말/격투', 120, 125, 80, 55, 60, 60, 760, 27, false),
 (1207, 403, 1, '달콤아', '후르츠포켓몬', '달고 맛있는 냄새 때문에 새포켓몬이 타깃으로 삼지만 영리하지 않아 신경 쓰지 않는다.', '0.3m', '3.2kg', '풀', 42, 30, 38, 30, 38, 32, 761, null, false),
 (1208, 403, 2, '달무리나', '후르츠포켓몬', '딱딱한 꼭지로 보호되기 때문에 새포켓몬과도 문제없이 논다. 쪼여도 신경 쓰지 않는다.', '0.7m', '8.2kg', '풀', 52, 40, 48, 40, 48, 62, 762, 18, false),
 (1209, 403, 3, '달코퀸', '후르츠포켓몬', '아름다운 발차기의 전문가다. 킥복싱의 챔피언도 일격으로 녹아웃시킨다.', '1.2m', '21.4kg', '풀', 72, 120, 98, 50, 98, 72, 763, 40, false),
 (1210, 404, 1, '큐아링', '꽃따기포켓몬', '머리에서 끈적거리는 시위를 늘려서 꽃을 따서 치장한다. 꽃이 없으면 불안하다.', '0.1m', '0.3kg', '페어리', 51, 52, 90, 82, 110, 100, 764, null, false),
 (1213, 405, 1, '하랑우탄', '현자포켓몬', '평소에는 나무 위에서 명상하며 지낸다. 제멋대로 몬스터볼을 던져 포켓몬에게 명령한다.', '1.5m', '76kg', '노말/에스퍼', 90, 60, 80, 90, 110, 60, 765, null, false),
 (1216, 406, 1, '내던숭이', '연계포켓몬', '침으로 어깨에 잎사귀를 붙여서 마킹한다. 잎사귀의 위치로 어느 무리인지 알 수 있다.', '2m', '82.8kg', '격투', 100, 120, 90, 40, 60, 80, 766, null, false),
 (1219, 407, 1, '꼬시레', '주행포켓몬', '떨어져 있는 것은 뭐든지 줍는다. 동전을 갖고 있을 때도 있어 니로우나 나옹이 노리고 있다.', '0.5m', '12kg', '벌레/물', 25, 35, 40, 20, 30, 80, 767, null, false),
 (1220, 407, 2, '갑주무사', '장갑포켓몬', '몸을 덮고 있는 두꺼운 껍질은 다이아몬드 정도의 강도다. 이기기 위해서는 수단을 가리지 않는다.', '2m', '108kg', '벌레/물', 75, 125, 140, 60, 90, 40, 768, 30, false),
 (1222, 408, 1, '모래꿍', '모래산포켓몬', '머리의 삽을 마음에 들어한다. 되찾으러 온 아이와 싸우다가 열을 올리면서 치고 받고 싸운다.', '0.5m', '70kg', '고스트/땅', 55, 55, 80, 70, 45, 15, 769, null, false),
 (1223, 408, 2, '모래성이당', '모래성포켓몬', '한 알의 모래에도 의지가 있다. 작은 포켓몬을 산 채로 삼켜서 생기를 뺏는다.', '1.3m', '250kg', '고스트/땅', 85, 75, 110, 100, 75, 35, 770, 42, false),
 (1225, 409, 1, '해무기', '해삼포켓몬', '해무기던지기라는 문화는 육지로 밀려온 해무기를 바다로 던져 돌려보내는 습관에서 시작되었다.', '0.3m', '1.2kg', '물', 55, 60, 130, 30, 130, 5, 771, null, false),
 (1228, 410, 1, '타입:널', '인공포켓몬', '특정 임무를 위해 개발된 포켓몬 병기다. 실험 중에 폭주해서 중단되었다.', '1.9m', '120.5kg', '노말', 95, 95, 95, 95, 95, 59, 772, null, false),
 (1229, 410, 2, '실버디', '인공포켓몬', '각성으로 진화한 모습이다. 무거운 마스크에서 벗어나 스피드가 크게 올라갔다.', '2.3m', '100.5kg', '노말', 95, 95, 95, 95, 95, 95, 773, 25, false),
 (1231, 411, 1, '메테노', '유성포켓몬', '오존층에 살며 더 강한 포켓몬의 먹이가 된다. 도망치다 지상으로 떨어진다.', '0.3m', '40kg', '바위/비행', 60, 60, 100, 60, 100, 60, 774, null, false),
 (1234, 412, 1, '자말라', '꿈결포켓몬', '태어날 때부터 계속 자고 있다. 깊은 수면에 빠져 있을 때는 일체 움직이지 않는다.', '0.4m', '19.9kg', '노말', 65, 115, 65, 75, 95, 65, 775, null, false),
 (1237, 413, 1, '폭거북스', '폭발거북포켓몬', '화산에 살며 황이나 광물을 먹는다. 먹은 먹이의 성분이 폭발하는 등껍질의 바탕이 된다.', '2m', '212kg', '불꽃/드래곤', 60, 78, 135, 91, 85, 36, 776, null, false),
 (1240, 414, 1, '토게데마루', '동글동글포켓몬', '등에 난 14개의 바늘 털은 놀라거나 흥분했을 때 멋대로 곤두선다.', '0.3m', '3.3kg', '전기/강철', 65, 98, 63, 40, 73, 96, 777, null, false),
 (1243, 415, 1, '따라큐', '탈포켓몬', '얌전하고 외로움을 잘 타지만, 넝마 조각의 속을 보려고 하면 격렬하게 싫어하며 저항한다.', '0.2m', '0.7kg', '고스트/페어리', 55, 90, 80, 50, 105, 96, 778, null, false),
 (1246, 416, 1, '치갈기', '이갈기포켓몬', '모래로 숨어들어 머리의 돌기에서 사이코 파워를 방사한다. 주변의 상태를 탐지하면서 먹이를 기다린다.', '0.9m', '19kg', '물/에스퍼', 68, 105, 70, 70, 70, 92, 779, null, false),
 (1249, 417, 1, '할비롱', '느긋누긋포켓몬', '친구가 된 아이가 괴롭힘을 당하면 괴롭힌 아이의 집에 찾아가서 태워버린다.', '3m', '185kg', '노말/드래곤', 78, 60, 85, 135, 91, 36, 780, null, false),
 (1252, 418, 1, '타타륜', '해초조각포켓몬', '녹색의 해초를 휘감아 생기를 빨아들인다. 주로 고래왕처럼 몸집이 큰 것을 노린다.', '3.9m', '210kg', '고스트/풀', 70, 131, 100, 86, 90, 40, 781, null, false),
 (1255, 419, 1, '짜랑꼬', '비늘포켓몬', '머리의 비늘로 바위나 지면을 마구 두드려 상대를 위협한다. 소리로 동료와 연락도 취한다.', '0.6m', '29.7kg', '드래곤', 45, 55, 65, 45, 45, 45, 782, null, false),
 (1256, 419, 2, '짜랑고우', '비늘포켓몬', '비늘을 부딪히며 소리를 낸다. 리듬이 최고조에 달할 때 공격해 온다.', '1.2m', '47kg', '드래곤/격투', 55, 75, 90, 65, 70, 65, 783, 35, false),
 (1257, 419, 3, '짜랑고우거', '비늘포켓몬', '먹이의 숨통을 끊고 포효하면 여기저기에서 축하하는 동료의 금속음이 메아리친다.', '1.6m', '78.2kg', '드래곤/격투', 75, 110, 125, 100, 105, 85, 784, 45, false),
 (1258, 420, 1, '카푸꼬꼬꼭', '토속신포켓몬', '수호신이라고 불리지만 기분을 해치는 사람이나 포켓몬을 공격하는 난폭한 신이기도 하다.', '1.8m', '20.5kg', '전기/페어리', 70, 115, 85, 95, 75, 130, 785, null, false),
 (1261, 421, 1, '카푸나비나', '토속신포켓몬', '빛나는 인분을 흩뿌려 사람이나 포켓몬의 상처를 치료한다. 아칼라에서 모시는 수호신이다.', '1.2m', '18.6kg', '에스퍼/페어리', 70, 85, 75, 130, 115, 95, 786, null, false),
 (1264, 422, 1, '카푸브루루', '토속신포켓몬', '수호신으로 불리지만 적이라고 간주한 자는 철저하게 때려 부수는 격렬함을 갖고 있다.', '1.9m', '45.5kg', '풀/페어리', 70, 130, 115, 85, 95, 75, 787, null, false),
 (1267, 423, 1, '카푸느지느', '토속신포켓몬', '짙은 안개 속에 살고 있다고 두려움과 존경을 받아 왔다. 물을 조종하는 포니의 수호신이다.', '1.3m', '21.2kg', '물/페어리', 70, 75, 115, 95, 130, 85, 788, null, false),
 (1270, 424, 1, '코스모그', '성운포켓몬', '의지할 곳 없는 가스 상태의 몸은 약한 바람에도 휩쓸리지만, 전혀 신경 쓰지 않는 듯하다.', '0.2m', '0.1kg', '에스퍼', 43, 29, 31, 29, 31, 37, 789, null, false),
 (1271, 424, 2, '코스모움', '원시성포켓몬', '먼 옛날 알로라를 지배하던 왕은 별의 고치라고 부르며 숭상하기 위한 제단을 만들었다.', '0.1m', '999.9kg', '에스퍼', 43, 29, 131, 29, 131, 37, 790, 43, false),
 (1272, 424, 3, '솔가레오', '일륜포켓몬', '울트라홀을 연 결과 다른 세계의 에너지나 생명을 이 세계로 부르기도 한다.', '3.4m', '230kg', '에스퍼/강철', 137, 137, 107, 113, 89, 97, 791, 53, false),
 (1273, 425, 1, '루나아라', '월륜포켓몬', '먼 옛날 문헌에 달을 현혹하는 짐승이라는 이름으로 기록되어 있다.', '4m', '120kg', '에스퍼/고스트', 137, 113, 89, 137, 107, 97, 792, null, false),
 (1276, 426, 1, '텅비드', '기생포켓몬', 'UB라고 불리는 다른 세계의 생명체다. 강한 신경독을 갖고 있을 것으로 추정된다.', '1.2m', '55.5kg', '바위/독', 109, 53, 47, 127, 131, 103, 793, null, false),
 (1279, 427, 1, '매시붕', '팽창포켓몬', '이 세계와는 성질이 다르고 위험하지만 원래 살던 세계에서는 흔히 볼 수 있는 생물인 듯하다.', '2.4m', '333.6kg', '벌레/격투', 107, 139, 139, 53, 53, 79, 794, null, false),
 (1282, 428, 1, '페로코체', '염미포켓몬', '다른 세계에 사는 생명체다. 가늘고 부드러운 몸이지만, 강한 파워를 간직하고 있는 듯하다.', '1.8m', '25kg', '벌레/격투', 71, 137, 37, 137, 37, 151, 795, null, false),
 (1285, 429, 1, '전수목', '전기장식포켓몬', '이 세계와는 성질이 다르고 위험하지만 원래 살던 세계에서는 흔히 볼 수 있는 생물인 듯하다.', '3.8m', '100kg', '전기', 83, 89, 71, 173, 71, 83, 796, null, false),
 (1288, 430, 1, '철화구야', '쏴올리기포켓몬', '위험한 UB의 일종이다. 거대한 두 팔에서 에너지 반응이 강하게 검출된다.', '9.2m', '999.9kg', '강철/비행', 97, 101, 103, 107, 101, 61, 797, null, false),
 (1291, 431, 1, '종이신도', '발도포켓몬', '종이와 같은 얇은 몸에서 연마한 칼 같은 예리함이 느껴지는 울트라비스트다.', '0.3m', '0.1kg', '풀/강철', 59, 181, 131, 59, 31, 109, 798, null, false),
 (1294, 432, 1, '악식킹', '악식성포켓몬', '이 세계와는 성질이 다르고 위험하지만 원래 살던 세계에서는 흔히 볼 수 있는 생물인 듯하다.', '5.5m', '888kg', '악/드래곤', 223, 101, 53, 97, 53, 43, 799, null, false),
 (1297, 433, 1, '네크로즈마', '프리즘포켓몬', '에너지인 빛을 찾아 날뛰는 모습은 어딘지 모르게 괴로워 보인다. 다른 세계의 존재인 듯하다.', '2.4m', '230kg', '에스퍼', 97, 107, 101, 127, 89, 79, 800, null, false),
 (1300, 434, 1, '마기아나', '인조포켓몬', '의식을 동조시켜 상대의 마음을 이해한다. 사람을 도울 때 편리한 능력이다.', '1m', '80.5kg', '강철/페어리', 80, 95, 115, 130, 115, 65, 801, null, false),
 (1303, 435, 1, '마샤도', '그림자살이포켓몬', '상대 그림자에 숨어들어 움직임이나 능력을 흉내 낸다. 그러다가 진짜보다 강해진다.', '0.7m', '22.2kg', '격투/고스트', 90, 125, 80, 90, 90, 125, 802, null, false),
 (1306, 436, 1, '베베놈', '독침포켓몬', '다른 세계에서는 여행 파트너로 삼을 정도로 친근한 울트라비스트다.', '0.6m', '1.8kg', '독', 67, 73, 67, 73, 67, 73, 803, null, false),
 (1307, 436, 2, '아고용', '독침포켓몬', '체내에 수백 리터의 독액을 갖고 있다. UB라고 불리는 생물의 일종이다.', '3.6m', '150kg', '독/드래곤', 73, 73, 73, 127, 73, 121, 804, 25, false),
 (1309, 437, 1, '차곡차곡', '돌담포켓몬', '울트라홀에서 출현했다. 여러 개의 생명이 쌓여 1마리를 형성하고 있는 듯하다.', '5.5m', '820kg', '바위/강철', 61, 131, 211, 53, 101, 13, 805, null, false),
 (1312, 438, 1, '두파팡', '불꽃놀이포켓몬', '꿈틀거리며 사람에게 다가오다 느닷없이 머리를 폭발시킨다. 울트라비스트의 일종인 듯하다.', '1.8m', '13kg', '불꽃/고스트', 53, 127, 53, 151, 79, 107, 806, null, false),
 (1315, 439, 1, '제라오라', '신뢰포켓몬', '양 손발톱에 전기를 머금어 상대를 갈가리 찢는다. 피하더라도 흩날리는 전격으로 감전시킨다.', '1.5m', '44.5kg', '전기', 88, 112, 75, 102, 80, 143, 807, null, false),
 (1318, 440, 1, '멜탄', '너트포켓몬', '걸쭉하게 녹은 강철의 몸을 가졌다. 땅속의 철분이나 금속을 녹여서 흡수한다.', '0.2m', '8kg', '강철', 46, 65, 65, 55, 35, 34, 808, null, false),
 (1319, 440, 2, '멜메탈', '너트포켓몬', '철을 만들어내는 힘을 가졌다고 추앙받았었다. 모종의 이유로 3000년의 세월이 흘러 되살아났다.', '2.5m', '800kg', '강철', 135, 143, 143, 80, 65, 34, 809, 25, false)
